(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,9335,e=>{"use strict";var a=e.i(98142),o=e.i(95676),s=e.i(20793);function t(e,a){return void 0===e?a:e}function r(e,a){return e&&e.length===a.length?e:a}function n(e,a){return a.fields||a.presets?{...e,fields:e.fields.map(e=>(function(e,a){let o=a?.[e.key];if(!o)return e;let s={...e,label:t(o.label,e.label),help:t(o.help,e.help),group:t(o.group,e.group)};return"enum"===s.kind?{...s,options:s.options.map(e=>({...e,label:o.options?.[String(e.value)]??e.label}))}:s})(e,a.fields)),presets:e.presets.map(e=>({...e,label:a.presets?.[e.id]??e.label}))}:e}function i(e,a){var o,s;return a?{...e,name:t(a.name,e.name),subtitle:t(a.subtitle,e.subtitle),tagline:t(a.tagline,e.tagline),description:t(a.description,e.description),facts:r(a.facts,e.facts),howToPlay:(o=e.howToPlay,(s=a.howToPlay)?{summary:t(s.summary,o.summary),objective:t(s.objective,o.objective),sections:o.sections.map((e,a)=>(function(e,a){if(!a)return e;let o={heading:t(a.heading,e.heading)};return e.body&&(o.body=r(a.body,e.body)),e.bullets&&(o.bullets=e.bullets.map((e,o)=>{let s=a.bullets?.[o];return{label:t(s?.label,e.label),text:t(s?.text,e.text)}})),o})(e,s.sections?.[a]))}:o),modes:e.modes.map(e=>{var o;return(o=a.modes?.[e.id])?{...e,name:t(o.name,e.name),tagline:t(o.tagline,e.tagline),description:t(o.description,e.description),facts:r(o.facts,e.facts)}:e}),configSchema:n(e.configSchema,a)}:e}let l={es:{blitz:{name:"Blitz",subtitle:"el juego del 31",tagline:"Persigue el treinta y uno",description:"Roba, cambia y toca para llegar a 31 en un mismo palo. Tres formatos de partida, bots astutos y una celebración muy ruidosa.",facts:["2–4 jugadores","clásico · rápido · cronometrado","solo o con amigos"],howToPlay:{summary:"El clásico del bar, el 31 — roba, cambia y toca para llegar a un palo que valga 31.",objective:"Ten en la mano un valor mayor que el de todos los demás cuando termine la ronda. Las manos puntúan según su mejor palo: A=11, figuras=10, las demás su valor. 31 en un mismo palo es un BLITZ y gana en el acto.",sections:[{heading:"Tu turno",body:["Tienes dos acciones:"],bullets:[{label:"Robar",text:"toma la carta de arriba del mazo, o coge la de arriba del descarte"},{label:"Descartar",text:"desliza una carta de tu mano boca arriba sobre la pila"}]},{heading:"Puntuar una mano",body:["Solo cuenta tu mejor palo. Tres corazones que sumen 27 vencen a tres cartas mixtas que sumen 30.","Un trío (tres del mismo valor) es una mano especial que vale 30½ (regla de casa activable)."]},{heading:"Tocar",body:["En lugar de robar, puedes TOCAR para terminar la ronda. Todos los demás juegan exactamente un turno más, y luego se muestran las manos.","La mano más baja pierde una vida. Si TÚ tocaste y empatas o quedas en la más baja, la penalización es tuya — toca con confianza."]},{heading:"¡Blitz!",body:["Tener 31 en un mismo palo hace estallar la ronda al instante — todos los demás jugadores pierden una vida, sin mostrar manos.","¿Te repartieron un Blitz antes de tu primer turno? Cuenta igual. Puedes presumir sin problema."]},{heading:"Formatos de partida",bullets:[{label:"Clásico",text:"pierdes una vida por cada ronda perdida; gana el último jugador con vidas"},{label:"Rápido",text:"rondas independientes, contador a primero-a-N victorias, redistribución instantánea"},{label:"Cronometrado",text:"reloj de partida, temporizadores de turno obligatorios, gana quien tenga más rondas ganadas cuando suene el timbre"}]},{heading:"Reglas de casa",body:["Cada mesa puede ajustarse en las opciones de la sala — vidas, penalizaciones por tocar, empates, trío, bloqueo de descarte y temporizadores de turno están todos ahí."]}]},modes:{classic:{name:"Clásico",tagline:"Vidas en juego",description:"Pierde una ronda, pierde una vida. Toca pronto o persigue el 31 perfecto — el último jugador con fichas gana la partida.",facts:["3 vidas cada uno","el último en pie","~5–10 min"]},fast:{name:"Rápido",tagline:"Una ronda a la vez",description:"Rondas independientes, redistribución instantánea. La mano más alta gana el bote — el primero en llegar a tres gana la partida.",facts:["primero a 3 gana","sin eliminaciones","~2–4 min"]},timed:{name:"Cronometrado",tagline:"Corre contra el timbre",description:"Un reloj de partida de tres minutos y temporizadores de turno relámpago. Quien tenga más rondas ganadas cuando suene la campana se lo lleva.",facts:["reloj de partida 3:00","temporizador de turno 7 s","desempate a muerte súbita"]}},fields:{threeOfAKind:{label:"Trío",options:{"30.5":"Vale 30,5",30:"Vale 30",off:"Desactivado"}},tieLowest:{label:"Empate en la más baja",options:{both:"Pierden ambos",nobody:"No pierde nadie",redeal:"Nuevo reparto entre los empatados"}},discardLock:{label:"Bloquear el descarte que acabas de robar"}},presets:{"classic-pub":"Clásico de bar",cutthroat:"Sin piedad",friendly:"Amistoso"}},cribbage:{name:"Cribbage",subtitle:"la carrera de las clavijas",tagline:"Clava hasta el 121",description:"La clásica carrera de bar — forma quinces, escaleras y parejas en tu mano, clávalas en el clavijero y reza para que nadie corte una jota detrás de ti.",facts:["2 jugadores","clásico · despiadado","solo o con amigos"],howToPlay:{summary:"La clásica carrera de bar — forma combinaciones que puntúan en tu mano y clávalas hasta el 121.",objective:"Sé el primero en clavar 121 puntos en el clavijero. Los puntos llegan dos veces: al jugar cartas en la mesa (clavando) y al contar tu mano y la cuna en el recuento.",sections:[{heading:"El reparto",body:["Se te reparten seis cartas. Quédate con cuatro y desliza dos boca abajo hacia LA CUNA — una mano extra que puntúa para quien reparte esta vez.","Descarta con generosidad cuando la cuna es tuya, y a la defensiva cuando es de tu rival."]},{heading:"El corte",body:["Quien reparte corta el mazo para revelar la carta de arranque, compartida por todas las manos.","Cortar una jota puntúa SUS TALONES — dos puntos para quien reparte, al instante."]},{heading:"El clavado",body:["Empezando a la izquierda de quien reparte, los jugadores se turnan para poner una carta cada uno, llevando una cuenta acumulada de los valores (las figuras valen 10). Nunca puedes hacer que la cuenta pase de 31.","Puntúa mientras juegas:"],bullets:[{label:"Quince",text:"tu carta hace que la cuenta llegue exactamente a 15 — 2 puntos"},{label:"Pareja / trío / póker",text:"iguala el rango de la carta anterior — 2 / 6 / 12 puntos"},{label:"Escalera",text:"tres o más cartas en secuencia, sin importar el orden — 1 punto por carta"},{label:"Treinta y uno",text:"tu carta hace que la cuenta llegue exactamente a 31 — 2 puntos"},{label:"Paso y última carta",text:"si nadie puede jugar por debajo de 31, quien jugó la última carta anota 1 punto y la cuenta se reinicia"}]},{heading:"El recuento",body:["Después del clavado, todos cuentan en voz alta: primero la mano de quien no reparte, luego la de quien reparte, y por último la cuna. La carta de arranque cuenta como una quinta carta."],bullets:[{label:"Quinces",text:"cada combinación de cartas que suma 15 — 2 puntos cada una"},{label:"Parejas",text:"una pareja 2, un trío 6, un póker 12"},{label:"Escaleras",text:"las secuencias puntúan por carta; las escaleras dobles se multiplican (7-7-8-9 = 12)"},{label:"Color",text:"cuatro cartas del mismo palo en tu MANO puntúan 4, cinco si la de arranque hace juego. En LA CUNA solo cuenta un color de las cinco cartas."},{label:"Su jota",text:"una jota del palo de la carta de arranque — 1 punto"}]},{heading:"Victoria y zurras",body:["El primero en llegar a 121 gana, incluso a mitad de un conteo. Quien reparte cambia en cada mano.","Con la regla de la zurra activada, el perdedor que termine por debajo de 90 queda ZURRADO — una humillación en toda regla, para saborear."]},{heading:"Reglas de la casa",body:["Los ajustes de la sala llevan las discusiones de bar:"],bullets:[{label:"Zurras",text:"señala a los perdedores por debajo de 90 (activado por defecto)"},{label:"Muggins",text:"si no reclamas los puntos que ganaste en la mesa, tu rival puede robártelos (desactivado por defecto) — ¡reclama a tiempo!"}]}]},modes:{"classic-pub":{name:"Clásica de bar",tagline:"El auténtico",description:"Seis cartas, dos a la cuna, y una larga carrera de clavijas hasta el 121. Las zurras cuentan — termina por debajo de 90 y te lo recordarán para siempre.",facts:["carrera a 121","línea de zurra en 90","~10–15 min"]},cutthroat:{name:"Despiadado",tagline:"Muggins vigila",description:"La misma carrera, con garras más afiladas: si no reclamas tus puntos en la mesa, tu rival se los queda.",facts:["muggins activado","roba puntos no reclamados","sin piedad"]},"match-play":{name:"Mejor de tres",tagline:"Al mejor de tres mangas",description:"Una velada como debe ser: corre hasta el 121, reinicia las clavijas, y repite. El primero en ganar dos mangas completas se lleva la partida.",facts:["primero a 2 mangas","el reparto alterna","~25–40 min"]}},fields:{skunks:{label:"Línea de zurra en 90"},muggins:{label:"Muggins (roba puntos no reclamados)"},gamesToWin:{label:"Mangas para ganar"}},presets:{"classic-pub":"Clásica de bar",cutthroat:"Despiadado","match-play":"Mejor de tres",friendly:"Amistosa"}},wild:{name:"Wild",subtitle:"el juego de vaciar la mano",tagline:"Suelta todas tus cartas",description:"Un alboroto de 112 cartas con saltos, cambios de sentido, +4, descartes de color y jugadas fuera de turno. La misma mesa cálida, con un mazo mucho más ruidoso.",facts:["2–4 jugadores","reparto cronometrado","solo o con amigos"],howToPlay:{summary:"Un alboroto de 112 cartas: empareja la carta de arriba, desata cartas de acción y vacía tu mano antes que nadie.",objective:"Sé el primero en quedarte sin cartas. Las cartas de acción frenan a los demás... a menos que se defiendan.",sections:[{heading:"Jugar una carta",body:["En tu turno, juega una carta que coincida con la de arriba en color o en valor, o roba en su lugar.","Los comodines se pueden jugar en cualquier momento y te dejan elegir el próximo color."]},{heading:"Cartas de acción",bullets:[{label:"Saltar",text:"el siguiente jugador pierde el turno, y no puede colarse de vuelta"},{label:"Cambio de sentido",text:"invierte el sentido del juego; entre dos jugadores te da otro turno seguido"},{label:"+2",text:"el siguiente jugador roba dos cartas y pierde el turno"},{label:"Descartar todo",text:"descarta todas las cartas de tu mano de ese color debajo de ella; las cartas de acción arrastradas no se activan"},{label:"Comodín",text:"juégalo cuando quieras y canta el próximo color"},{label:"Comodín +4",text:"canta el color Y hace que el siguiente jugador robe cuatro cartas"},{label:"Comodín Intercambiar Manos",text:"canta el color y luego intercambia tu mano con quien quieras (carta opcional)"},{label:"Comodín Barajar Manos",text:"junta todas las manos, barájalas y repártelas de nuevo (carta opcional)"}]},{heading:"Última carta",body:['¿Te quedan dos cartas? Pulsa "¡Última carta!" antes de jugar. Si te quedas con una sin cantarla, te pillan y robas dos.',"Si robas, vuelves a tener más cartas, así que hay que volver a cantarla."]},{heading:"Los relojes",body:["Cada turno tiene un tiempo límite. Si el reloj llega a cero, la mesa hace una jugada válida por ese jugador para que la partida siga.","El reparto también tiene un reloj de partida. Durante su último minuto, aparecen las posiciones en vivo del primero al cuarto puesto y se actualizan según cambian las manos."],bullets:[{label:"Al llegar a cero",text:"gana quien tenga menos cartas; los empates se resuelven por orden de asiento, así cada partida tiene un resultado claro"},{label:"Opciones avanzadas",text:"ajusta los segundos por turno y los minutos totales de la partida antes de repartir"}]},{heading:"Caos de la casa",body:["Todos los ajustes de la mesa están en Opciones avanzadas antes de repartir:"],bullets:[{label:"Acumular",text:"responde a un +2 o un +4 con la misma carta y la penalización se acumula para la próxima víctima"},{label:"Colarse",text:"¿tienes una carta idéntica a la que se acaba de jugar? Suéltala fuera de turno antes de que nadie reaccione"},{label:"Robar hasta poder jugar",text:"sigue robando hasta conseguir una carta jugable, en vez de robar solo una"},{label:"Jugada forzada",text:"si robas una carta que se puede jugar, tienes que jugarla"},{label:"Desafiar los +4",text:"un +4 solo es legítimo si no tienes ninguna carta del color anterior: desafía el farol y, si aciertas, se lleva la pila; si fallas, te llevas dos más"},{label:"Sietes y ceros",text:"un 7 intercambia tu mano con el jugador que elijas; un 0 pasa todas las manos un asiento"},{label:"Comodines de intercambio",text:"añade al mazo los comodines Intercambiar Manos y Barajar Manos"}]},{heading:"Ganar",body:["Vacía tu mano para ganar antes de que se acabe el tiempo de la partida. Si no, gana quien tenga la mano más ligera al llegar a cero."]}]},modes:{classic:{name:"Clásico",tagline:"Al pie de la letra",description:"Empareja el color o el número, y suelta todo un color de golpe. Sin acumular, sin colarte: un alboroto educado.",facts:["un reparto","sin acumular","~5 min"]},party:{name:"Fiesta",tagline:"Acumula y arrasa",description:"Los +2 y los +4 se acumulan, y una coincidencia exacta deja que cualquiera se cuele fuera de turno. Caos, con buena luz.",facts:["acumulación activada","colarse activado","~5 min"]},houseRules:{name:"Reglas de la casa",tagline:"Todo activado",description:"Los sietes intercambian manos, los ceros las pasan, los comodines de intercambio se unen al mazo, y la carta que robas hay que jugarla.",facts:["cambios 7-0","comodines de intercambio","jugada forzada"]}},fields:{handSize:{label:"Cartas repartidas",help:"Cuántas cartas recibe cada asiento al empezar.",group:"El reparto"},turnTimeSeconds:{label:"Segundos por turno",help:"Cuando se acaba el tiempo, la mesa hace una jugada válida por ese asiento.",group:"Tiempo"},matchTimeMinutes:{label:"Minutos de partida",help:"Al llegar a cero, gana quien tenga la mano más ligera.",group:"Tiempo"},stackDrawTwo:{label:"Acumular +2",help:"Responde a un +2 con otro tuyo y pasa la pila, cada vez más grande.",group:"Penalizaciones"},stackDrawFour:{label:"Acumular +4",help:"Lo mismo con los +4. Las penalizaciones pueden crecer rápido.",group:"Penalizaciones"},jumpIn:{label:"Colarse",help:"¿Tienes la carta exacta que se acaba de jugar? Suéltala fuera de turno.",group:"Reglas de la casa"},drawToMatch:{label:"Robar hasta poder jugar",help:"Sigue robando hasta que consigas una carta jugable, en vez de robar solo una.",group:"Reglas de la casa"},forcePlay:{label:"Jugada forzada",help:"Si robas una carta que se puede jugar, tienes que jugarla.",group:"Reglas de la casa"},sevenZero:{label:"Sietes y ceros",help:"Juega un 7 para intercambiar tu mano con alguien; juega un 0 para pasar todas las manos un asiento.",group:"Reglas de la casa"},challengeDrawFour:{label:"Desafiar los +4",help:"Un +4 solo es legítimo si no tienes ninguna carta del color en juego. Desafía el farol: si aciertas, se lleva las cartas; si fallas, te llevas dos más.",group:"Reglas de la casa"},swapCards:{label:"Comodines de intercambio",help:"Añade al mazo los comodines Intercambiar Manos y Barajar Manos.",group:"El mazo"}},presets:{classic:"Wildpile clásico",party:"Pila de fiesta",houseRules:"Reglas de la casa"}},ratscrew:{name:"Rat Screw",subtitle:"el juego de la palmada",tagline:"Sé el primero en dar la palmada",description:"Voltea cartas sobre un montón compartido y da la palmada en parejas, sándwiches y mucho más antes que nadie. Reflejos en tiempo real, desafíos con figuras y quemazos por palmada en falso.",facts:["2–4 jugadores","palmadas en tiempo real","solo o con amigos"],howToPlay:{summary:"Por turnos, voltea cartas sobre un montón compartido y da PALMADAS para ganar todas las cartas de la mesa.",objective:"Gana las 52 cartas. Haces crecer tu mazo dando la palmada en los patrones antes que nadie o colocando figuras que tus rivales no puedan responder. Cuando todos los demás se quedan sin cartas —o vuelven al juego a base de palmadas— ganas la partida.",sections:[{heading:"El volteo",body:["Empezando por ti, los jugadores se turnan para colocar la carta de arriba de su propio mazo boca abajo sobre el montón central, girándola lejos de sí mismos para que nadie la vea antes de tiempo.",'Si tu mazo se queda seco, dejas de voltear —pero con "Volver con una palmada" activado, una palmada afortunada te devuelve al juego.']},{heading:"Figuras y desafíos",body:["Una figura inicia un desafío contra el siguiente jugador en el orden de turno:"],bullets:[{label:"Jota",text:"tiene 1 oportunidad de voltear otra figura"},{label:"Reina",text:"2 oportunidades"},{label:"Rey",text:"3 oportunidades"},{label:"As",text:"4 oportunidades"}]},{heading:"Resolver un desafío",body:["Cada carta que no sea figura que voltee el jugador desafiado le quema una oportunidad.","¿Voltea una nueva figura? El desafío pasa al siguiente jugador de la mesa con oportunidades renovadas.","¿Se queda sin oportunidades? El jugador que lanzó la figura se lleva todo el montón central bajo su mazo y abre el siguiente volteo."]},{heading:"Palmadas",body:["En cuanto un patrón que se puede palmear cae en el montón, TODOS corren a darle la palmada. La primera palmada válida se lleva todo el montón central y abre el siguiente volteo.","Cada vez que un patrón está activo se abre una breve ventana de palmada: ¡pulsa el botón de PALMADA antes de que se cierre!"],bullets:[{label:"Pareja",text:"dos cartas del mismo valor seguidas (7♦ 7♣)"},{label:"Sándwich",text:"el mismo valor con una carta en medio (7♦ Q♠ 7♥)"},{label:"Matrimonio",text:"un Rey y una Reina seguidos, en cualquier orden (K♦ Q♠) — regla de la casa"},{label:"Diez",text:"dos cartas numéricas seguidas que suman diez (3♦ 7♠) — regla de la casa"},{label:"Arriba-abajo",text:"la carta de arriba coincide con la última carta del fondo del montón — regla de la casa"},{label:"Escalera",text:"tres valores seguidos, ascendentes o descendentes (4-5-6 o 9-8-7) — regla de la casa"}]},{heading:"Palmadas en falso",body:['Dar la palmada cuando no hay ningún patrón activo tiene un precio: con "La palmada en falso quema una carta" activado, tu carta de arriba se desliza bajo el montón como penalización. Los nervios salen caros — mantén los ojos en las cartas, no en la gente.']},{heading:"Reglas de la casa",body:["Ajusta el caos en las opciones de la sala antes de empezar:"],bullets:[{label:"Parejas / Sándwiches",text:"los patrones clásicos de palmada, ambos activados por defecto"},{label:"Matrimonio / Dieces / Arriba-abajo / Escaleras",text:"patrones extra, todos desactivados por defecto para una mesa clásica"},{label:"La palmada en falso quema una carta",text:"activado por defecto; desactívalo y solo se podrán palmear los patrones activos"},{label:"Volver con una palmada al quedarte sin cartas",text:"los jugadores sin cartas aún pueden dar la palmada en un patrón activo para ganar el montón y volver al juego"},{label:"Ventana de palmada",text:"cuánto tiempo permanece abierta la carrera — cuanto más corta, más despiadada"}]},{heading:"Modales de mesa",body:["Quien gana el montón lo desliza bajo su mazo sin barajar y abre el siguiente volteo. Gana la partida el último jugador que se queda con todas las cartas.","Un breve margen de gracia mantiene honestas las palmadas a distancia: la mesa espera un instante más allá de la ventana antes de darla por cerrada."]}]},modes:{classic:{name:"Palmada clásica",tagline:"Parejas y sándwiches",description:"El clásico de bar: voltea rápido, vigila las parejas y los sándwiches, y da la palmada antes de que se cierre la ventana.",facts:["ventana de palmada: 1,2 s","la palmada en falso quema","~8 min"]},"quick-reflex":{name:"Reflejos rápidos",tagline:"Ventanas crueles",description:"Los mismos patrones clásicos con el gatillo fácil: la ventana de palmada se cierra de golpe en 0,7 segundos.",facts:["ventana de palmada: 0,7 s","para ojos rápidos","~6 min"]},slaphappy:{name:"Palmada total",tagline:"Todos los patrones activos",description:"Matrimonios, dieces, arriba-abajo y escaleras cuentan además de los clásicos. Caos, con buena luz y muy ruidoso.",facts:["todos los patrones","ventana de palmada: 0,8 s","~5 min"]}},fields:{doubles:{label:"Parejas"},sandwiches:{label:"Sándwiches"},marriage:{label:"Matrimonio (K+Q)"},tens:{label:"Los dieces suman diez"},topBottom:{label:"Arriba-abajo"},runs:{label:"Escaleras"},misSlapBurn:{label:"La palmada en falso quema una carta"},slapBackIn:{label:"Volver con una palmada al quedarte sin cartas"},slapWindowMs:{label:"Ventana de palmada"}},presets:{classic:"Palmada clásica","quick-reflex":"Reflejos rápidos",slaphappy:"Palmada total"}},euchre:{name:"Euchre",subtitle:"el juego de parejas",tagline:"Gana bazas para tu equipo",description:"Acepta el triunfo, nombra tu palo y persigue a los jacks con el jugador de enfrente. El primer equipo en llegar a diez gana la partida.",facts:["4 jugadores · 2v2","juego de bazas","solo o con amigos"],howToPlay:{summary:"El clásico de parejas — nombra el triunfo y corre con tu equipo hasta los 10 puntos.",objective:"Sentado frente a tu compañero, gana al menos tres de las cinco bazas de cada mano haciendo rey de la mesa a tu palo cantado. El primer equipo en llegar a la puntuación objetivo gana la partida.",sections:[{heading:"La mesa",body:["Cuatro jugadores, dos equipos: tú y el jugador de enfrente sois compañeros. Cinco cartas cada uno; las cuatro últimas forman el descarte, con su carta superior boca arriba."]},{heading:"Aceptar el triunfo — primera ronda de puja",body:["Empezando a la izquierda del repartidor, cada uno acepta o pasa la carta boca arriba:"],bullets:[{label:"Aceptar el triunfo",text:"ese palo pasa a ser triunfo, el repartidor recoge la carta en su mano y entierra una boca abajo"},{label:"Ir en solitario",text:"toma el triunfo y manda a tu compañero al banquillo para esta mano"},{label:"Pasar",text:"la decisión avanza a la izquierda"}]},{heading:"Nombrar el triunfo — segunda ronda",body:["Si los cuatro pasan, la carta boca arriba se entierra y cada silla puede nombrar cualquier otro palo como triunfo. El palo descartado queda fuera de juego.","Obligar al repartidor (por defecto): si todos los demás pasan en la segunda ronda, el repartidor debe cantar un palo."]},{heading:"Los jacks",body:["Cuando se nombra un palo, su jack es el JACK MAYOR — la carta más alta en juego. El jack del palo del mismo color es el JACK MENOR, solo por debajo del jack mayor, y cuenta como triunfo. Así, con corazones como triunfo, J♥ y luego J♦ son las dos cartas dominantes."]},{heading:"Jugar las bazas",body:["El jugador a la izquierda del repartidor abre. Debes seguir el palo abierto si puedes — recuerda que el jack menor pertenece al triunfo, no a su palo impreso. Gana la carta más alta del palo abierto, salvo que alguien juegue triunfo; el triunfo más alto se lleva todo. El ganador abre la siguiente."]},{heading:"Puntuar una mano",body:["El equipo que cantó es el de los HACEDORES. Tras las cinco bazas:"],bullets:[{label:"3 o 4 bazas",text:"los hacedores anotan 1 punto"},{label:"5 bazas",text:"una marcha — los hacedores anotan 2"},{label:"Marcha en solitario",text:"las cinco bazas yendo en solitario — los hacedores anotan 4"},{label:"¡Euchred!",text:"los hacedores ganan menos de tres bazas — los defensores anotan 2"}]},{heading:"Ir en solitario",body:["Un jugador con confianza puede jugar sin su compañero, que se queda fuera de la mano por completo. Ganar las cinco en solitario vale 4 puntos — pero si consigues menos de tres, la defensa igualmente te deja en euchre por 2."]},{heading:"Reglas de la casa",body:["Los ajustes de la sala afinan la partida: juego a 5/10/15, obligar al repartidor activado o no, y si se permite ir en solitario. Cuando una mano entera se descarta sin que nadie cante triunfo, el reparto simplemente pasa a la izquierda."]}]},modes:{classic:{name:"Pub clásico",tagline:"La cosa de verdad",description:"Diez puntos, obligar al repartidor, ir en solitario. El juego tal como se juega en cualquier salón y mesa de cocina.",facts:["partida a 10","obliga al repartidor","~20 min"]},"quick-cut":{name:"Corte rápido",tagline:"Primero a cinco",description:"Las mismas reglas, carrera más corta — cinco puntos y se acabó. Perfecto mientras se calienta la tetera.",facts:["partida a 5","~10 min"]},"long-game":{name:"Partida larga",tagline:"Acomódate",description:"Quince puntos para una tarde entera. Las rencillas son bienvenidas.",facts:["partida a 15","~30 min"]},"old-school":{name:"A la antigua",tagline:"El repartidor puede pasar",description:"Sin obligar al repartidor — todos pueden pasar y el reparto sigue adelante. Como insisten algunos abuelos.",facts:["partida a 10","sin obligar","~20 min"]}},fields:{targetScore:{label:"Partida a",group:"Partida",options:{5:"5 — corte rápido",10:"10 — estándar",15:"15 — partida larga"},help:"La primera pareja en llegar a esta puntuación gana la partida."},stickDealer:{label:"Obligar al repartidor",group:"Puja",help:"En la segunda ronda de puja, el repartidor debe cantar un palo cuando todos los demás pasan."},goingAlone:{label:"Permitir ir en solitario",group:"Puja",help:"Un jugador con una mano espectacular puede mandar a su compañero al banquillo durante esa mano."}},presets:{classic:"Pub clásico","quick-cut":"Corte rápido","long-game":"Partida larga","old-school":"A la antigua"}},hearts:{name:"Corazones",subtitle:"el juego de la evasión",tagline:"Evita los corazones",description:"Esquiva todos los corazones, elude a la Dama Negra y deja que otro cargue con los puntos. Pases rotativos, elecciones secretas, una reina muy afilada.",facts:["4 jugadores","pasar · baza · esquivar","solo o con amigos"],howToPlay:{summary:"El clásico juego de evasión: no te lleves corazones, esquiva a la Dama Negra y deja que otro cargue con los puntos.",objective:"Termina la partida con la puntuación más baja. Cada corazón que captures cuesta 1 punto y la reina de picas cuesta 13; cuando alguien supera el límite de fin de partida (100 por defecto), gana quien tenga el total más bajo.",sections:[{heading:"El pase",body:["Antes de cada mano eliges tres cartas y se las pasas a un vecino de mesa: todos eligen en secreto y los cuatro pases llegan a la vez.","La dirección rota en cada mano: izquierda, derecha, enfrente y luego una mano sin pase."]},{heading:"Jugar las bazas",body:["El dos de tréboles abre la primera baza. Sigue el palo si puedes; la carta más alta del palo jugado se lleva la baza y su ganador sale en la siguiente."],bullets:[{label:"Primera baza",text:"no se pueden tirar cartas de penalización en ella (regla de la casa opcional)"},{label:"Romper corazones",text:"los corazones no pueden salir hasta que se haya descartado uno en una baza anterior, a menos que tu mano sea solo corazones"},{label:"Sin palo",text:"¿te quedaste sin el palo jugado? Tira lo que quieras: aquí es donde la reina le cae a alguien"}]},{heading:"Puntuar una mano",body:["Cuando se juegan las trece bazas, cada corazón que capturaste vale 1 punto y la reina de picas vale 13."],bullets:[{label:"Jota de diamantes",text:"regla de la casa opcional: da −10 a quien la capture"},{label:"Cazar la luna",text:"captura los trece corazones y la reina y tú sumas cero mientras los demás se llevan +26; o, con la otra regla de la casa, tu propia puntuación baja 26"}]},{heading:"La partida",body:["Las manos se acumulan hasta que alguien cruza el límite de fin de partida (50 / 75 / 100). El total más bajo gana la partida; los empates comparten la corona."]},{heading:"Reglas de la casa",body:["Los ajustes de la sala controlan todo: la dirección del pase, las manos sin pase, la protección de la primera baza, la jota de diamantes, el límite de fin de partida y el cambio de la luna. Las mesas clásicas mantienen los valores por defecto."]}]},modes:{classic:{name:"Clásico",tagline:"Al pie de la letra",description:"Pases rotativos izquierda-derecha-enfrente, una mano sin pase cada cuarto reparto, sin puntos en la primera baza. Partida a 100.",facts:["partida a 100","manos sin pase activas","~15 min"]},quickcut:{name:"Corte Rápido",tagline:"Los mismos corazones, más rápido",description:"Reglas idénticas, techo más bajo: el primero en pasar de 50 termina la partida. Un partido entero en lo que dura un café.",facts:["partida a 50","manos sin pase activas","~8 min"]},cutthroat:{name:"Despiadado",tagline:"La jota anda suelta",description:"La jota de diamantes da −10 a quien la capture, y las cartas de penalización vuelan desde la primera baza. Nadie está a salvo.",facts:["J♦ −10","puntos en la primera baza","partida a 100"]}},fields:{passDirection:{label:"Pasar cartas",options:{left:"Izquierda",right:"Derecha",across:"Enfrente",hold:"Retener (sin pase)"}},holdHand:{label:"Mano sin pase cada cuarto reparto"},noPointsFirstTrick:{label:"Sin cartas de penalización en la primera baza"},jackDiamonds:{label:"La jota de diamantes puntúa −10"},gameOver:{label:"La partida termina en",options:{50:"50 puntos",75:"75 puntos",100:"100 puntos"}},moonShift:{label:"Cazar la luna",options:{opponents:"+26 para los demás",self:"−26 de tu propia puntuación"}}},presets:{classic:"Corazones Clásico",quickcut:"Corte Rápido",cutthroat:"Despiadado"}},gin:{name:"Gin",subtitle:"el clásico del rummy",tagline:"Combina, toca y gana la noche",description:"Diez cartas, dos sillas. Forma tríos y escaleras, deshazte de tus cartas sueltas y golpea la mesa antes que tu rival.",facts:["2 jugadores","toque · gin · gin grande","solo o con amigos"],howToPlay:{summary:"El clásico para dos — roba, descarta y combina hasta lograr una mano digna de un toque.",objective:"Convierte tus diez cartas en tríos y escaleras para que casi no sobre nada, y toca antes que tu rival. La primera silla en superar el objetivo de la partida gana.",sections:[{heading:"Combinaciones y cartas sueltas",body:["Una combinación es un trío o cuarteto del mismo valor, o tres o más cartas seguidas del mismo palo. Los ases solo valen como cartas bajas (A-2-3, nunca Q-K-A).","Todo lo que no forme parte de una combinación son cartas sueltas, que cuentan por su valor nominal: las figuras valen diez y los ases uno. Cuanto menos, mejor."]},{heading:"Tu turno",body:["Dos pasos, cada turno:"],bullets:[{label:"Robar",text:"toma la carta de arriba del mazo, o desliza la de arriba del descarte"},{label:"Descartar",text:"coloca una carta boca arriba sobre la pila — nunca la carta que acabas de robar este turno, sea del mazo o del descarte"}]},{heading:"La carta inicial",body:["Tras el reparto queda una carta boca arriba. Quien no reparte puede tomarla para su mano o pasar; después el repartidor tiene la misma opción. Si ambos pasan, quien no reparte roba del mazo y comienza la partida."]},{heading:"El toque",body:["En vez de descartar, puedes tocar cuando tus cartas sueltas estén en el límite de toque (10 por defecto) o por debajo. Eso termina la mano de inmediato — sin descarte. Robar antes una undécima carta abre la vía del gin grande si todo queda combinado."]},{heading:"Gin y cartas adosadas",body:["Cero cartas sueltas es gin — el defensor no puede adosar nada y paga todas sus cartas sueltas más la bonificación de gin.","En un toque normal, el defensor adosa primero: cualquiera de sus cartas sobrantes que amplíe un trío de quien toca a cuarteto, o que extienda una escalera por cualquier extremo, se descuenta de la cuenta antes de la comparación.","Si las cartas sueltas del defensor terminan siendo iguales o menores que las tuyas, eso es un contragolpe — en su lugar, cobra la diferencia más una bonificación."]},{heading:"Puntuación y la partida",body:["Las manos se suceden hasta que alguien supera el objetivo de la partida (100 por defecto), alternando el reparto en cada mano."],bullets:[{label:"Toque",text:"diferencia entre las cartas sueltas"},{label:"Contragolpe",text:"diferencia + 25 para el defensor"},{label:"Gin",text:"todas las cartas sueltas del defensor + 25"},{label:"Gin grande",text:"once cartas todas combinadas — cartas sueltas del defensor + 31 (activable)"},{label:"Bonificación de caja",text:"+25 opcional por mano ganada, sumado al final (activable)"}]},{heading:"Reglas de la casa",body:["Cada mesa se puede ajustar en las opciones de la sala:"],bullets:[{label:"Límite de toque",text:"qué tan bajo debes estar para tocar — límites más ajustados alargan las manos"},{label:"Objetivo de la partida",text:"50 para una partida rápida, 100 la clásica, más para los incansables"},{label:"Gin grande / bonificaciones / bonificación de caja",text:"los ajustes de pago"}]},{heading:"Manos muertas",body:["Si el mazo queda en dos cartas, la mano muere — sin puntos, el repartidor reparte de nuevo. Toca antes."]}]},modes:{classic:{name:"Clásico",tagline:"Directo a 100",description:"El estándar de siempre — toca con diez cartas sueltas o menos, el gin paga 25, el gin grande paga 31. El primero en superar los 100 se lo lleva.",facts:["límite de toque 10","partida a 100","~15 min"]},quick:{name:"Rápida",tagline:"Carrera a 50",description:"Las mismas reglas, escalera más corta. Una partida ágil para dos, ideal para el descanso del café.",facts:["partida a 50","~8 min"]},purist:{name:"Purista",tagline:"Sin adornos",description:"El gin grande está desactivado y las bonificaciones de caja se quedan en casa. Toques puros, cartas sueltas puras, sin red de seguridad.",facts:["sin gin grande","sin bonificación de caja"]}},fields:{knockCap:{label:"Límite de toque",help:"Cartas sueltas máximas con las que puedes tocar",group:"Mesa"},matchTarget:{label:"Partida a",help:"La primera silla en superar esta puntuación gana la partida",group:"Mesa"},ginBonus:{label:"Bonificación de gin",group:"Bonificaciones"},bigGin:{label:"Gin grande",help:"Roba una undécima carta que combine por completo",group:"Bonificaciones"},bigGinBonus:{label:"Bonificación de gin grande",group:"Bonificaciones"},boxBonus:{label:"Bonificación de caja",help:"+25 por mano ganada, sumado al total final",group:"Bonificaciones"}},presets:{classic:"Clásico",quick:"Partida rápida",purist:"Purista"}},president:{name:"Presidente",subtitle:"el juego de la escalada",tagline:"Sube hasta la corona",description:"Corona la pila con un conjunto más alto, deshazte de tu mano antes que nadie y sube de Escoria a Presidente. Hasta ocho sillas, con coronas y sustos incluidos.",facts:["2–8 jugadores","roles y trueques","solo o con amigos"],howToPlay:{summary:"El clásico juego de escalada — deshazte de tu mano primero, sube la escalera de Escoria a Presidente y haz que tus rivales te sirvan cartas.",objective:"Termina cada reparto en la mejor silla que puedas. El primero en quedarse sin cartas es Presidente, el último es Escoria. Los puntos de posición se acumulan entre repartos; gana quien primero llegue al total objetivo.",sections:[{heading:"Jugar a la pila",body:["Quien lidera abre una baza con cualquier conjunto — una carta, pareja, trío o cuarteto de un mismo valor.","En el sentido de las agujas del reloj, cada jugador debe coronar la pila con el MISMO tamaño de conjunto y un valor estrictamente más alto, o pasar."],bullets:[{label:"Orden de valores",text:"el 3 es el más bajo, subiendo hasta el As, con el 2 por encima de todo"},{label:"Pasar",text:"pasar solo te salta este turno — si alguien más corona la pila más tarde en la baza, vuelves a entrar (salvo que esté activa la regla de la casa de paso bloqueado)"},{label:"Ganar la baza",text:"cuando todos los demás han pasado, se recoge la pila y quien ganó lidera lo que quiera"},{label:"Un 2 limpia",text:"un 2 solo gana la pila al instante y mantiene el turno — regla de la casa, activa por defecto"}]},{heading:"Terminar un reparto",body:["Te quedas sin cartas y aseguras el siguiente puesto en la escalera. Se sigue jugando hasta que solo queda un jugador con cartas en la mano — la Escoria.","El primero es Presidente, el segundo es Vicepresidente, el penúltimo es Vice Escoria y el último puesto es Escoria."]},{heading:"Puntuación y la partida",body:["Cada reparto acumula puntos de posición: el Presidente anota tantos puntos como sillas haya, el segundo uno menos, y así hasta un único punto para la Escoria.","La partida termina en el momento en que alguien alcanza el objetivo — gana el total acumulado más alto, los empates comparten la corona."]},{heading:"El intercambio",body:["Antes del siguiente reparto, las sillas bajas pagan tributo desde sus manos recién repartidas y las sillas altas devuelven su elección:"],bullets:[{label:"Escoria → Presidente",text:"las dos mejores cartas de la Escoria; el Presidente devuelve las dos que quiera"},{label:"Vice Escoria → Vicepresidente",text:"una carta en cada sentido"},{label:"Interruptor de desactivación",text:"desactiva el trueque en los ajustes de la sala para un todos-contra-todos más puro"}]},{heading:"Reglas de la casa",body:["Ajusta la mesa en los ajustes de la sala antes de empezar:"],bullets:[{label:"El 2 limpia la pila",text:"activo por defecto — desactivado, el 2 es solo otra carta imbatible"},{label:"Pases bloqueados",text:"una vez pasas, te quedas fuera del resto de la baza (por defecto desactivado: vuelves a entrar cuando cambia la pila)"},{label:"Trueque",text:"el intercambio de cartas por roles entre repartos"},{label:"Puntos objetivo",text:"lo larga que es la partida — 7 para una carrera corta, 11 para una sesión, 21 para una maratón"}]},{heading:"Etiqueta de mesa",body:["El primer reparto lo abre la silla inicial; después, quien sea Presidente lidera cada reparto.","Las manos se reparten por turnos hasta que el mazo se agota, así que en mesas impares algunas sillas se quedan con una carta menos — todos están en el mismo barco."]}]},modes:{classic:{name:"Clásico",tagline:"La escalera completa",description:"Coronas, tributos y remontadas — el primero en llegar a once puntos se lleva la sala. Como se juega en el bar.",facts:["a 11 puntos","trueque activo","2 limpiezas"]},rapid:{name:"Rápida",tagline:"Corta y picante",description:"El primero en llegar a siete mantiene la mesa en movimiento. Las mismas reglas, menos repartos, remontadas más ruidosas.",facts:["a 7 puntos","~10 min","genial con 6+"]},marathon:{name:"Maratón",tagline:"Reinados largos",description:"Veintiún puntos de política. Las escorias se convierten en presidentes, las dinastías suben y caen.",facts:["a 21 puntos","sesión larga","arco completo"]}},fields:{twoClears:{label:"Un 2 limpia la pila",help:"un 2 solo gana la pila al instante y mantiene el turno para quien lo juega"},passLocks:{label:"Pasar te deja fuera de la baza",help:"variante de paso bloqueado: pasar te elimina del resto de la baza. Por defecto desactivado — pasar solo salta el turno actual, así que puedes volver a entrar si alguien más corona la pila antes de que termine la baza"},trading:{label:"Intercambio de cartas por roles entre repartos",help:"intercambio de cartas basado en roles entre repartos (necesita 4 o más sillas)"},targetPoints:{label:"Primero a (puntos)",help:"la partida termina cuando una silla acumula esta cantidad de puntos de posición"}},presets:{classic:"Presidente Clásico",rapid:"Gabinete Rápido",marathon:"Maratón"}},spades:{name:"Picas",subtitle:"el juego de parejas",tagline:"Canta tus bazas",description:"Siéntate frente a tu compañero, canta un número y consigue esa cantidad de bazas — ni una más, ni una menos si puedes evitarlo. Las picas son siempre triunfo. Las bolsas te encontrarán.",facts:["4 jugadores · 2v2","canto · triunfo · bolsas","solo o con amigos"],howToPlay:{summary:"El clásico americano de parejas — canta tus bazas, rompe picas y corre hacia los 500.",objective:"Sentado frente a tu compañero, consigue al menos tantas bazas como hayáis cantado entre los dos. El primer equipo en llegar a la puntuación objetivo (500 por defecto) gana; un empate en la línea o por encima juega otra mano.",sections:[{heading:"La mesa",body:["Cuatro jugadores, dos equipos: tú y el jugador de enfrente sois compañeros. Cada mano reparte el mazo completo de 52 cartas — trece cartas por jugador. Tanto el reparto como el primer canto empiezan a la izquierda del repartidor y avanzan en sentido horario."]},{heading:"El canto",body:["Cada silla canta un número, una sola vez. No hay paso ni recanto. El contrato de tu equipo es la suma de los dos cantos que no son nil."],bullets:[{label:"1–13",text:"cuántas bazas esperas conseguir"},{label:"Nil",text:"un canto aparte — no lleves ninguna baza y ganas +100, o −100 si llevas alguna. Las bazas de un nil fallido no ayudan a tu compañero a cumplir su contrato, pero cada una sigue contando como bolsa"}]},{heading:"Jugar las bazas",body:["El jugador a la izquierda del repartidor abre la primera baza. Sigue el palo si puedes; gana la pica más alta, o si no, la carta más alta del palo abierto. Quien gana la baza abre la siguiente."],bullets:[{label:"Romper picas",text:"no se puede abrir con una pica hasta que alguien haya fallado con una estando sin ese palo — salvo que en tu mano solo te queden picas"},{label:"Sin palo",text:"¿te has quedado sin el palo abierto? Juega lo que quieras, incluido un triunfo"}]},{heading:"Puntuar una mano",body:["Si las sillas del equipo que no cantaron nil consiguen al menos el contrato, el equipo anota 10 puntos por baza cantada más 1 por cada baza de más. Si os quedáis cortos, el contrato cuesta −10 por baza cantada."],bullets:[{label:"Bolsas",text:"las bazas de más (y las bazas de un nil fallido) son bolsas. Se arrastran de mano en mano; cada diez bolsas cuestan 100 puntos y las bolsas sobrantes se quedan en la cuenta"},{label:"Nil",text:"se puntúa aparte, sumado al resultado del contrato del compañero"}]},{heading:"La partida",body:["Las manos se acumulan hasta que un equipo alcanza el objetivo (250 / 500 / 750). Gana la puntuación más alta; si ambos equipos llegan al mismo total en la línea o por encima, se reparte otra mano."]},{heading:"Reglas de la casa",body:["Los ajustes de la sala solo tocan tres cosas: la puntuación objetivo, si se permite el nil y si cuentan las bolsas. Las mesas clásicas mantienen los valores por defecto. El nil a ciegas no está disponible."]}]},modes:{classic:{name:"Clásico",tagline:"Al pie de la letra",description:"Picas por parejas a 500, con nil y con bolsas. El juego tal como se juega en cualquier mesa de cocina.",facts:["partida a 500","nil · bolsas","~25 min"]},quick:{name:"Rápida",tagline:"Primero en llegar a 250",description:"Las mismas reglas, carrera más corta — 250 puntos y se acabó. Una partida entera en el rato de la comida.",facts:["partida a 250","nil · bolsas","~12 min"]},"clean-books":{name:"Bazas limpias",tagline:"Sin bolsas",description:"Cumple tu canto o cae en falta — las bazas de más no son bolsas y no suman puntos. Precisión antes que relleno.",facts:["partida a 500","nil activo","bolsas desactivadas"]}},fields:{targetScore:{label:"Partida a",help:"Después de cada mano, gana el equipo más alto en la línea o por encima de esta puntuación. Si empatan, se juega otra mano.",group:"Partida",options:{250:"250 — corte rápido",500:"500 — estándar",750:"750 — partida larga"}},nil:{label:"Permitir nil",help:"Un canto de cero es nil: no lleves ninguna baza y ganas +100, o −100 si llevas alguna. Las bazas de un nil fallido no ayudan al contrato del compañero.",group:"Canto"},bags:{label:"Contar bolsas",help:"Las bazas de más y las bazas de un nil fallido son bolsas. Cada diez bolsas cuestan 100 puntos; las bolsas sobrantes se quedan en la cuenta.",group:"Puntuación"}},presets:{classic:"Clásico",quick:"Rápida","clean-books":"Bazas limpias"}},poker:{name:"Póker",subtitle:"Texas hold’em sin límite",tagline:"La última pila en pie",description:"Dos cartas propias, cinco en el centro, y todas las fichas que tengas para decir cuánto te las crees. Las ciegas suben hasta que alguien se lo lleva todo.",facts:["2–6 jugadores","Texas hold’em sin límite","solo fichas de juego"],howToPlay:{summary:"Texas hold’em sin límite, jugado como un sit-and-go: todos empiezan igual, las ciegas suben y la última pila en pie gana.",objective:"Gana todas las fichas. En cada mano recibes dos cartas propias y compartes cinco en el centro; la mejor mano de cinco cartas se lleva el bote, y quien se queda sin fichas queda fuera de la partida.",sections:[{heading:"Las fichas",body:["Las fichas son solo para llevar la cuenta, no hay nada que comprar ni que cobrar. Todos empiezan con la misma pila, y la partida termina cuando un jugador las tiene todas."]},{heading:"Una mano",body:["Dos cartas boca abajo para cada silla, y una ronda de apuestas. Tres cartas comunitarias (el flop), otra ronda. Una cuarta (el turn), otra ronda. Una quinta (el river), la última ronda. Quien siga en juego muestra sus cartas, y las mejores cinco de las siete disponibles ganan."],bullets:[{label:"El botón",text:"marca al repartidor y se mueve una silla a la izquierda cada mano"},{label:"Ciegas",text:"las dos sillas a la izquierda del botón ponen fichas antes de que salgan las cartas, así siempre hay algo por lo que jugar"}]},{heading:"Tu turno",body:["Cuando te toca actuar, solo hay cuatro cosas que puedes hacer."],bullets:[{label:"Retirarse",text:"abandonar la mano y lo que ya hayas puesto"},{label:"Pasar",text:"seguir en juego sin poner fichas, solo cuando no debes igualar nada"},{label:"Igualar",text:"igualar la apuesta actual"},{label:"Apostar / subir",text:"poner más, y todos los demás deben igualarlo para seguir en juego. Una subida debe ser al menos del tamaño de la anterior, salvo que apuestes todo lo que te queda"}]},{heading:"Todo dentro",body:["Nunca puedes perder más de lo que tienes delante. Apostar tu última ficha es ir todo dentro: sigues en la mano hasta el final, y cualquier apuesta mayor que tu pila forma un bote secundario que no puedes ganar ni perder."]},{heading:"Jerarquía de manos",body:["De mejor a peor. Los empates se resuelven con la siguiente carta más alta, y un empate real reparte el bote."],bullets:[{label:"Escalera de color",text:"cinco seguidas del mismo palo; con el as arriba es una escalera real"},{label:"Póker",text:"las cuatro cartas de un mismo valor"},{label:"Full",text:"tres cartas de un valor y dos de otro"},{label:"Color",text:"cinco cartas del mismo palo"},{label:"Escalera",text:"cinco seguidas; el as juega alto o bajo"},{label:"Trío",text:"tres cartas de un mismo valor"},{label:"Doble pareja",text:"dos cartas de un valor y dos de otro"},{label:"Pareja",text:"dos cartas de un mismo valor"},{label:"Carta alta",text:"ninguna de las anteriores"}]},{heading:"La partida",body:["Las ciegas suben según un calendario, así que retirarse para siempre no es un plan: la partida siempre termina. Si te quedas sin fichas quedas fuera; el último jugador con fichas gana, y el resto termina en el orden en que fue quedando fuera."]},{heading:"Reglas de la casa",body:["Los ajustes de la sala eligen la pila inicial, la velocidad con la que suben las ciegas, si la ciega grande pone una ciega adicional para toda la mesa a partir del tercer nivel, y si las manos perdedoras se muestran en el enfrentamiento o se retiran boca abajo."]}]},modes:{classic:{name:"Clásico",tagline:"La mesa completa",description:"Tres mil fichas cada uno y ciegas que suben cada ocho manos. Margen para jugar una mano entera antes de que nadie esté comprometido.",facts:["3.000 fichas","ciegas cada 8","~25 min"]},turbo:{name:"Turbo",tagline:"Todo dentro o a casa",description:"Pilas cortas y ciegas que se duplican cada cuatro manos. Nadie tiene tiempo de esperar a los ases.",facts:["1.500 fichas","ciegas cada 4","~10 min"]},deep:{name:"Pila Profunda",tagline:"Juega al jugador",description:"Seis mil fichas y una escalada lenta, sin ciega ante. La partida larga, donde la posición y la paciencia valen algo.",facts:["6.000 fichas","ciegas cada 12","sin ante"]}},fields:{startingStack:{label:"Pila inicial",group:"Partida",help:"Fichas con las que empieza cada silla. Pilas más profundas dan más juego tras el flop antes de que nadie esté comprometido.",options:{1500:"1.500 — corta",3e3:"3.000 — estándar",6e3:"6.000 — profunda"}},blindSpeed:{label:"Subida de ciegas",group:"Partida",help:"Las ciegas suben según un calendario para que la partida siempre termine. Turbo obliga a jugar rápido.",options:{slow:"Lenta — cada 12 manos",standard:"Estándar — cada 8 manos",turbo:"Turbo — cada 4 manos"}},ante:{label:"Ciega ante de mesa",group:"Apuestas",help:"A partir del tercer nivel, la ciega grande pone una ciega adicional para toda la mesa, así siempre hay algo que merezca la pena ganar."},showMucked:{label:"Mostrar manos perdedoras",group:"Enfrentamiento",help:"Desactivado, una mano perdedora se retira boca abajo como en una mesa real. Activado, todos ven cada mano que llegó al river."}},presets:{classic:"Clásico",turbo:"Turbo",deep:"Pila Profunda"}},ohhell:{name:"Oh Hell",subtitle:"el juego de las predicciones",tagline:"Canta tus bazas. Llévate justo esas.",description:"Las manos crecen y menguan en cada ronda mientras predices el número exacto de bazas que te vas a llevar. La regla del repartidor garantiza que alguien falle — procura que no seas tú.",facts:["3–7 jugadores","predicción · triunfo · exacto","solo o con amigos"],howToPlay:{summary:"Predice el número exacto de bazas que vas a llevarte, ni una más ni una menos. El mazo mengua y crece en cada ronda, hasta que alguien predice más bazas de las que la mesa puede repartir.",objective:"A lo largo de una partida de manos que crecen y luego menguan, consigue más puntos que nadie cumpliendo tu predicción con exactitud. En cada ronda, un jugador está matemáticamente condenado a fallar — procura que no seas tú.",sections:[{heading:"La mesa",body:["De tres a siete jugadores, cada uno por su cuenta. Una partida es una secuencia de rondas: la primera reparte una carta a cada uno, luego las manos crecen hasta un máximo (limitado para que siempre quede una carta que voltear como triunfo) y vuelven a bajar hasta una. El reparto rota en sentido horario en cada ronda."]},{heading:"La vuelta",body:["Después del reparto, se voltea boca arriba la siguiente carta del mazo — su palo es el triunfo de la ronda."],bullets:[{label:"Sin carta que voltear",text:"cuando el reparto agota el mazo entero no queda nada que voltear y la ronda se juega sin triunfo"},{label:"Cortar triunfo",text:'las mesas con "cortar triunfo" activado reducen en una carta la ronda de mazo completo, así aún se puede cortar un triunfo desde el fondo'}]},{heading:"La predicción",body:["Empezando a la izquierda del repartidor y siguiendo el sentido horario, cada silla canta un número entre 0 y el tamaño de su mano: exactamente cuántas bazas dice que se llevará. No hay paso ni segunda oportunidad."],bullets:[{label:"La regla del repartidor",text:"el repartidor canta EN ÚLTIMO LUGAR y no puede hacer que la suma de las predicciones iguale las bazas disponibles: el repartidor no puede empatar, así que alguien en la mesa está condenado a fallar. La predicción prohibida sencillamente no está disponible"},{label:"Cero",text:"una predicción legal como cualquier otra: no llevarte ninguna baza"}]},{heading:"Jugar las bazas",body:["El jugador a la izquierda del repartidor abre la primera baza. Sigue el palo si puedes; gana el triunfo más alto, o si no hay triunfo, la carta más alta del palo abierto. Quien gana la baza abre la siguiente."]},{heading:"Puntuar una ronda",body:["Cumple tu predicción EXACTAMENTE o no sumas nada (por defecto). La puntuación de cada silla en la ronda se suma a su total acumulado; tras la última ronda del arco, gana el total más alto."],bullets:[{label:"Solo exacto",text:"acertar exactamente da 10 + la predicción; cualquier otra cosa da 0"},{label:"Penalización",text:"acertar exactamente da 10 + la predicción; fallar cuesta menos la diferencia de tu fallo"},{label:"Más uno",text:"acertar exactamente da el doble de tu predicción; cualquier otra cosa da 0"}]},{heading:"Variante Mago",body:["Con Magos y Bufones activados, cuatro Magos y cuatro Bufones se unen al mazo (60 cartas) y alteran el orden habitual de las cosas."],bullets:[{label:"Mago",text:"gana a todo; el PRIMER Mago jugado se lleva la baza. Si lo abres, la baza queda sin palo abierto — cualquiera puede jugar lo que quiera"},{label:"Bufón",text:"pierde contra todo; si todas las cartas de una baza son Bufones, gana el primero jugado. Si lo abres, el palo abierto lo define la siguiente carta real"},{label:"Vuelta de triunfo",text:"si se voltea un Mago, el REPARTIDOR elige el triunfo; si se voltea un Bufón, la ronda se juega sin triunfo"}]}]},modes:{classic:{name:"Clásico",tagline:"Sube y baja",description:"El arco clásico: una carta, sube hasta un máximo, y vuelve a bajar hasta una. Regla del repartidor activada, solo predicciones exactas. Alguien falla en cada ronda; ojalá no seas tú.",facts:["manos 1…máximo…1","regla del repartidor activada","~20 min"]},quick:{name:"Rápida",tagline:"Reparte mucho, reduce rápido",description:"Empieza con cinco cartas y baja directo hasta una. Toda una partida en diez minutos, puro nervio y sin relleno.",facts:["manos 5→1","~10 min"]},wizard:{name:"Mago",tagline:"Sesenta cartas, cuatro certezas",description:"Cuatro Magos ganan siempre y cuatro Bufones nunca lo hacen. El palo abierto se dobla a su alrededor y el repartidor a veces elige el triunfo. El caos, formalizado.",facts:["mazo de 60 cartas","magos activados"]}},fields:{handSize:{label:"Cartas en mano",help:"Cartas repartidas a cada jugador en esta ronda. Una partida completa lo ajusta automáticamente en cada ronda.",group:"Partida"},dealer:{label:"Silla del repartidor",help:"Silla que reparte esta ronda y canta en último lugar. Una partida completa rota el reparto en cada ronda.",group:"Partida"},handArc:{label:"Arco de manos",help:"Cómo cambia el tamaño de las manos a lo largo de la partida: sube y luego baja, solo sube, o reparte mucho y reduce.",group:"Partida",options:{updown:"Sube y baja — 1…máximo…1",up:"Solo sube — 1…máximo",down:"Solo baja — máximo…1"}},maxHand:{label:"Mano más grande",help:"El arco nunca reparte más que esto — limitado para que en cada ronda quede una carta que voltear como triunfo.",group:"Partida"},hookRule:{label:"Regla del repartidor",help:"El repartidor no puede empatar: la última predicción no puede hacer que el total iguale exactamente las bazas disponibles, así que siempre falla alguien.",group:"Predicción"},scoring:{label:"Puntuación",help:"Cumple tu predicción con exactitud para puntuar. Los esquemas difieren en lo que cuesta fallar.",group:"Puntuación",options:{exactOnly:"Solo exacto — 10 + predicción o nada",penalty:"Penalización — fallas por n, pierdes n",plusOne:"Más uno — el doble de la predicción si aciertas"}},wizards:{label:"Magos y bufones",help:"Añade cuatro Magos (ganan siempre) y cuatro Bufones (pierden siempre) — un mazo de 60 cartas.",group:"Avanzado"},trumpOnLastRound:{label:"Cortar triunfo en rondas de mazo completo",help:"Cuando una ronda repartiría el mazo entero, corta antes un triunfo desde el fondo (las manos se reducen en una carta) en lugar de jugar sin triunfo.",group:"Avanzado"}},presets:{classic:"Clásico",quick:"Rápida",wizard:"Mago"}},scopa:{name:"Scopa",subtitle:"el juego de pesca",tagline:"Barre la mesa",description:"Captura cartas de la mesa por igualdad o por suma, acapara las monedas de oro y ve a por el settebello. Deja la mesa limpia del todo y cántala como scopa: la palabra más dulce en las salas de cartas italianas.",facts:["2–6 jugadores","capturar · sumar","solo o con amigos"],howToPlay:{summary:"El clásico italiano de pesca: captura cartas de la mesa y déjala limpia para hacer scopa.",objective:"Captura cartas de la mesa igualando o sumando su valor. Más cartas, más monedas, el settebello, la primiera y cada scopa suman un punto; la primera en llegar al objetivo (11 por defecto) gana la partida.",sections:[{heading:"La mesa",body:["Scopa se juega con una baraja italiana de 40 cartas: Denari (monedas), Coppe (copas), Spade (espadas) y Bastoni (bastos), del 1 al 10. Pueden jugar dos, tres, cuatro o seis personas; a cuatro y a seis os sentáis en parejas fijas, alternando asientos alrededor de la mesa.","Cada reparto da tres cartas a cada jugador y coloca cuatro boca arriba sobre la mesa. Si aparecen tres o más Reyes en el tablero inicial, se baraja de nuevo y se reparte otra vez."]},{heading:"Capturar",body:["En tu turno juegas exactamente una carta de tu mano. Las cartas capturan solo por número: el palo nunca importa."],bullets:[{label:"Igualar",text:"tu carta se lleva una sola carta de la mesa del mismo valor: un 5 se lleva un 5"},{label:"Elegir",text:"si dos cartas de la mesa comparten ese valor, eliges cuál te llevas — elige con cuidado, lo que queda importa"},{label:"Sumar",text:"tu carta puede llevarse dos o más cartas de la mesa que sumen su valor: un 8 se lleva un 3 y un 5. Pero si existe una captura simple DEBES hacerla — las combinaciones solo valen cuando no hay ninguna igualdad disponible"},{label:"Dejar",text:"¿nada encaja? Tu carta se queda en la mesa, boca arriba y a disposición de cualquiera"}]},{heading:"Scopa",body:["Si barres todas las cartas que quedan en la mesa en una sola captura, haces una scopa: un punto, anotado al instante. Una scopa en la última carta del último reparto no cuenta — esas cartas se barren de todos modos. Cuando las manos se vacían, se reparten tres cartas nuevas a cada jugador; la mesa nunca se reabastece. Cuando se agota el mazo, el último jugador que capturó se lleva las cartas que queden en la mesa, y esa barrida no es una scopa."]},{heading:"Puntuar una ronda",body:["Tras el último reparto se reparten cuatro puntos, más las scopas que se hayan hecho. En las mesas por parejas, las capturas del equipo se juntan antes de puntuar."],bullets:[{label:"Carte",text:"más cartas capturadas — 21 o más de las 40 en partidas a dos; un empate no da el punto a nadie"},{label:"Denari",text:"más monedas capturadas — 6 o más de las 10; un empate no da el punto a nadie"},{label:"Settebello",text:"quien capturó el hermoso 7 de monedas suma 1, siempre"},{label:"Primiera",text:"la mejor carta de cada palo, sumadas — el 7 vale 21, el 6 vale 18, el As 16, el 5 → 15, el 4 → 14, el 3 → 13, el 2 → 12, y las figuras solo 10. Si no tienes ninguna carta de algún palo, no puedes ganarla. El total más alto se lleva 1 punto; los empates no dan el punto a nadie"},{label:"Scope",text:"un punto por cada una, ya anotado durante la partida"}]},{heading:"La partida",body:["Las rondas se repiten — la mano de repartir pasa a la izquierda cada vez — hasta que alguien supera la puntuación objetivo. Si dos bandos empatan justo en la línea, otra ronda lo decide."]},{heading:"Reglas de la casa",body:["Los ajustes de la sala exponen los mandos clásicos: el objetivo (11/16/21), Scopone (mazo entero repartido, sin robo), Napola (una bonificación por escalera de monedas), Re di denari (una bonificación por el Rey de monedas) y la visualización con palos franceses, que es puramente visual."]}]},modes:{classic:{name:"Clásica",tagline:"La primera a 11",description:"Scopa tal como se juega en cualquier bar italiano: tres cartas cada vez, cuatro puntos por ronda, la primera a once.",facts:["partida a 11","repartos de 3 cartas","~20 min"]},lungo:{name:"Lungo",tagline:"La partida larga",description:"Las mismas reglas, carrera hasta veintiuno. Espacio para remontadas, rencillas y scopas legendarias.",facts:["partida a 21","repartos de 3 cartas","~40 min"]},scopone:{name:"Scopone",tagline:"Mazo entero, sin piedad",description:"El clásico de toda la vida a cuatro manos: diez cartas repartidas de golpe a cada uno, sin mazo de robo, sin nada oculto. Cada captura es un compromiso.",facts:["4 jugadores · 2 contra 2","mazo entero","~30 min"]}},fields:{target:{label:"Partida a",group:"Partida",help:"Tras cada ronda gana quien tenga la puntuación más alta en esta línea o por encima. Un empate en la línea reparte otra ronda.",options:{11:"11 — clásica",16:"16 — larga",21:"21 — lungo"}},scopone:{label:"Scopone",group:"Reparto",help:"El clásico de toda la vida a cuatro manos: se reparte todo el mazo de golpe y no hay mazo de robo. Capturar se vuelve mucho más ajustado."},napola:{label:"Napola",group:"Puntuación",help:"Ten el As, el 2 y el 3 de monedas para 3 puntos extra, más 1 más por cada carta de monedas que continúe la escalera (4, 5, …)."},reDenari:{label:"Re di denari",group:"Puntuación",help:"Un punto extra para quien capture el Rey de monedas."},frenchSuits:{label:"Visualización con palos franceses",group:"Mesa",help:"Muestra monedas/copas/espadas como diamantes/corazones/picas para que se vea la baraja estándar. Puramente visual: los identificadores y las reglas siguen en italiano."}},presets:{classic:"Clásica",lungo:"Lungo","scopone-preset":"Scopone"}},spite:{name:"Spite & Malice",subtitle:"la carrera del montón principal",tagline:"Devuélvesela con creces",description:"Construye los montones centrales del 1 al 12, vacía tu montón principal y arruina los planes de los demás con comodines bien colocados. El nombre ya lo dice todo.",facts:["2–4 jugadores","clásico · rápido · despiadado","solo o con amigos"],howToPlay:{summary:"Spite & Malice — construye los montones centrales compartidos del 1 al 12 y vacía tu montón principal antes que nadie más el suyo.",objective:"Sé el primer jugador con el montón principal vacío. Cada carta que entierras en él es una carta de la que otro podrá presumir.",sections:[{heading:"La mesa",body:["Cuatro tipos de cartas, cuatro sitios donde ponerlas:"],bullets:[{label:"Montón principal",text:"tu pila objetivo boca abajo; la carta de arriba va boca arriba"},{label:"Mano",text:"cinco cartas, se reponen a cinco al empezar tu turno"},{label:"Montones de descarte",text:"cuatro montones personales — terminar tu turno significa descartar en uno"},{label:"Montones centrales",text:"hasta cuatro construcciones compartidas en las que juega todo el mundo"}]},{heading:"Tu turno",body:["Primero, roba hasta completar cinco cartas. Después haz tantas jugadas como quieras, en el orden que prefieras:","juega en un montón central, juega la carta de arriba de tu montón principal, o juega la de arriba de uno de tus montones de descarte.","Tu turno solo termina cuando descartas una carta de tu mano en uno de tus montones de descarte."]},{heading:"Construir",body:["Un montón central empieza en un As y sube de rango en rango hasta la Reina. El palo nunca importa.","Completa un montón hasta la Reina y todo él vuelve al mazo de robo — el montón se reinicia vacío, a la espera de un As o un comodín."]},{heading:"Comodines",bullets:[{label:"Comodines",text:"dieciocho en la baraja — juega uno como el rango que necesites, y ese rango se recuerda para el montón"},{label:"Rangos recordados",text:"un comodín que hace de 6 convierte la siguiente carta en un 7, la juegue quien la juegue"}]},{heading:"El montón principal",body:["Jugar la carta de arriba de tu montón principal voltea la siguiente de inmediato — y si era la última, ganas en el acto, en mitad del turno, sin necesidad de descartar.","¿Atascado sin nada que jugar? Descarta con cabeza: lo que apiles ahora es una jugada que podrás desbloquear más tarde."]},{heading:"Cuando se agota el mazo",body:["Los montones completados vuelven directamente al mazo de robo, así que las cartas siguen circulando.","Si el mazo se agota al empezar tu turno, todos los montones centrales a medio construir también vuelven a él — las exigencias se reinician al As y las cartas enterradas salen de su tumba.","Si la mesa se bloquea del todo, se lleva la partida el montón principal más cercano a vaciarse, en lugar de dejar que nadie se estanque."]},{heading:"Formas de jugar",bullets:[{label:"Clásica",text:"la carrera completa de montón principal de 20 cartas — trae algo de picar"},{label:"Rápida",text:"un montón principal de 10 cartas para un duelo veloz"},{label:"Despiadada",text:"montón principal de 13 cartas y sin reponer a mitad de turno: vacía tu mano pronto y jugarás en desventaja"}]}]},modes:{classic:{name:"Clásica",tagline:"La carrera completa",description:"Veinte cartas enterradas en cada montón principal y todos los comodines de la baraja. El juego tal como debía jugarse, con calma.",facts:["montón principal de 20","reyes y jokers comodín","~15 min"]},quick:{name:"Rápida",tagline:"Ajuste de cuentas más corto",description:"Montones principales de diez cartas dejan el resto intacto — mismos comodines, misma malicia, la mitad de espera para tu venganza.",facts:["montón principal de 10","todos los comodines","~5–8 min"]},cutthroat:{name:"Despiadada",tagline:"Sin piedad, sin repuestos",description:"Trece cartas de fondo y sin reponer a mitad de turno: vacía tu mano en mal momento y jugarás en desventaja mientras otro gana.",facts:["montón principal de 13","sin reponer a mitad de turno","severo"]}},fields:{payoffSize:{label:"Montón principal",help:"Cartas enterradas en cada montón principal. Vacía el tuyo para ganar — números más bajos acortan la partida.",group:"El reparto"},handSize:{label:"Cartas repartidas",help:"Tamaño de la mano, que se repone al empezar cada turno.",group:"El reparto"},discardPiles:{label:"Montones de descarte",help:"Montones delante de cada jugador. Terminar un turno significa descartar en uno de ellos.",group:"El reparto"},wilds:{label:"Comodines en la baraja",help:"Un comodín vale por el rango que digas. Dieciocho es la baraja de caja; menos hace que cada uno sea oro.",group:"Comodines"},buildPiles:{label:"Montones centrales",help:"Montones de construcción compartidos en los que juega todo el mundo. Menos montones significa más espera por los unos de los demás.",group:"El centro"},refillMidTurn:{label:"Reponer a mitad de turno",help:"Vacía tu mano y se repone a cinco de inmediato para que sigas jugando. Desactivado es la variante despiadada.",group:"Reglas de la casa"}},presets:{classic:"Clásica",quick:"Rápida",cutthroat:"Despiadada"}},klondike:{name:"Klondike",subtitle:"el clásico del solitario",tagline:"Despeja la mesa diaria",description:"Levanta siete columnas en colores alternados, gira el mazo y manda cada palo a casa de As a Rey. El mismo reparto diario espera a todos.",facts:["1 jugador","reparto diario con semilla","sin conexión"],howToPlay:{summary:"El clásico del solitario a siete columnas, repartido de forma determinista para una mesa nueva o para el reparto diario.",objective:"Construye las cuatro bases de As a Rey, un palo por pila.",sections:[{heading:"El reparto",body:["Siete columnas del tablero guardan de una a siete cartas. Solo la carta superior de cada columna empieza boca arriba; las otras veinticuatro cartas forman el mazo."]},{heading:"Construye el tablero",body:["Coloca las cartas en orden descendente y en colores alternados. Una serie boca arriba se mueve en bloque. Solo un Rey —solo o encabezando una serie— puede entrar en una columna vacía."]},{heading:"Gira y recicla",body:["Clásico gira tres cartas del mazo a la vez; Relajado gira una. Solo la carta superior del descarte puede moverse. Cuando el mazo se agota, da la vuelta al descarte sin barajar. No hay límite de pasadas."]},{heading:"Las bases",body:["Empieza cada palo con su As y sigue subiendo hasta el Rey. Una carta de la base puede volver al tablero si necesitas deshacer una jugada."]},{heading:"Despeja la mesa",body:["Mover la última carta boca arriba de una columna voltea automáticamente la carta que queda al descubierto. Completa las cuatro bases para ganar."]}]},modes:{daily:{name:"Diario",tagline:"Una mesa para todos",description:"Un reparto de Robar Tres con semilla de la fecha. Repítelo, compártelo o vuelve mañana a por una mesa nueva.",facts:["robar tres","mismo reparto diario","pasadas ilimitadas"]},classic:{name:"Clásico",tagline:"Robar tres",description:"Un reparto nuevo con semilla y tres cartas giradas del mazo cada vez.",facts:["robar tres","reparto nuevo","pasadas ilimitadas"]},relaxed:{name:"Relajado",tagline:"Robar una",description:"Un reparto nuevo más suave: cada carta del mazo llega de una en una.",facts:["robar una","reparto nuevo","pasadas ilimitadas"]}},fields:{drawCount:{label:"Robo del mazo",group:"Reparto",options:{3:"Robar tres — clásico",1:"Robar una — relajado"},help:"Gira una o tres cartas a la vez. El descarte puede reciclarse sin límite de pasadas."}},presets:{classic:"Clásico",relaxed:"Relajado"}},golf:{name:"Golf",subtitle:"el solitario rápido",tagline:"Juega ±1 al hoyo",description:"Siete columnas de cinco, todas las cartas boca arriba. Juega un rango junto al hoyo, encadena todo lo que puedas y deja lo menos posible sobre el césped.",facts:["1 jugador","hoyo diario con semilla","sin conexión"],howToPlay:{summary:"Un solitario rápido a un jugador: siete columnas de cinco, todas las cartas visibles y un solo hoyo.",objective:"Quita todas las cartas del césped. Las que queden son tu puntuación: cuanto menos, mejor.",sections:[{heading:"El reparto",body:["Siete columnas guardan cinco cartas boca arriba cada una. Las diecisiete restantes forman el mazo. La primera carta del mazo abre el hoyo."]},{heading:"Juega al hoyo",body:["Solo puede moverse la carta más baja de cada columna. Júegala al hoyo cuando esté a un rango de distancia: un 8 admite un 7 o un 9. Palos y colores no importan."]},{heading:"Gira el mazo",body:["Si nada del césped encaja, gira la siguiente carta del mazo sobre el hoyo. La carta anterior queda enterrada y no vuelve. No hay reciclaje."]},{heading:"As y Rey",body:["El Golf clásico trata el As y el Rey como callejones sin salida. Fairway permite que se conecten para que una cadena siga corriendo."]},{heading:"La puntuación",body:["El hoyo termina cuando el césped está limpio o el mazo se acaba y ya no hay jugadas. Las cartas que quedan en el tablero son tu puntuación. Cero es un clear."]}]},modes:{daily:{name:"Diario",tagline:"Un hoyo para todos",description:"Un hoyo Clásico con semilla de la fecha. Repítelo, compártelo o vuelve mañana a por una mesa nueva.",facts:["sin envolvente","mismo reparto diario","gana quien deja menos"]},classic:{name:"Clásico",tagline:"As y Rey te detienen",description:"Un hoyo nuevo con semilla. As y Rey son callejones sin salida; el mazo no vuelve.",facts:["sin envolvente","reparto nuevo","sin reciclaje"]},fairway:{name:"Fairway",tagline:"El As envuelve al Rey",description:"El mismo hoyo rápido, pero As y Rey se juegan entre sí para que las cadenas duren más.",facts:["envuelve A–K","reparto nuevo","sin reciclaje"]}},fields:{wrap:{label:"El As envuelve al Rey",group:"Hoyo",help:"El Golf clásico se detiene en As y Rey. Fairway deja que A y K se jueguen el uno al otro."}},presets:{classic:"Clásico",fairway:"Fairway"}},freecell:{name:"FreeCell",subtitle:"el solitario abierto",tagline:"Despeja la mesa diaria",description:"Ocho columnas, todas las cartas boca arriba. Aparca extras en las celdas libres y manda cada palo a casa de As a Rey. El mismo reparto diario espera a todos.",facts:["1 jugador","reparto diario con semilla","sin conexión"],howToPlay:{summary:"El clásico del solitario a cartas abiertas, repartido de forma determinista para una mesa nueva o para el reparto diario.",objective:"Construye las cuatro bases de As a Rey, un palo por pila.",sections:[{heading:"El reparto",body:["Ocho columnas del tablero muestran todas las cartas boca arriba. Las primeras cuatro columnas reciben siete cartas; las últimas cuatro reciben seis."]},{heading:"Celdas libres",body:["Aparca una carta en cada celda libre. Clásico tiene cuatro celdas; Relajado tiene seis. Una celda guarda una sola carta, que puede ir al tablero o a una base."]},{heading:"Construye el tablero",body:["Coloca las cartas en orden descendente y en colores alternados. Una serie empaquetada se mueve junta si el límite de supermovimiento lo permite. Cualquier carta —no solo un Rey— puede entrar en una columna vacía."]},{heading:"Las bases",body:["Empieza cada palo con su As y sigue subiendo hasta el Rey. Una carta de la base puede volver al tablero si necesitas deshacer una línea."]},{heading:"Despeja la mesa",body:["Manda todas las cartas a casa. Completa las cuatro bases para ganar."]}]},modes:{daily:{name:"Diario",tagline:"Una mesa para todos",description:"Un reparto Clásico con semilla de la fecha. Repítelo, compártelo o vuelve mañana a por una mesa nueva.",facts:["cuatro celdas","mismo reparto diario","cualquier carta al vacío"]},classic:{name:"Clásico",tagline:"Cuatro celdas libres",description:"Un reparto nuevo con semilla y cuatro celdas de una carta.",facts:["cuatro celdas","reparto nuevo","cualquier carta al vacío"]},relaxed:{name:"Relajado",tagline:"Seis celdas libres",description:"Un reparto nuevo más suave: dos celdas extra facilitan mover series largas.",facts:["seis celdas","reparto nuevo","cualquier carta al vacío"]}},fields:{freeCells:{label:"Celdas libres",group:"Reparto",options:{4:"Cuatro celdas — clásico",6:"Seis celdas — relajado"},help:"Aparca una carta en cada celda. Relajado añade dos celdas extra."}},presets:{classic:"Clásico",relaxed:"Relajado"}},spider:{name:"Spider",subtitle:"el solitario de dos barajas",tagline:"Pela ocho series del mismo palo",description:"Construye diez columnas en orden descendente, mueve solo series del mismo palo y saca cada Rey-a-As de la mesa. El mismo reparto diario de dos palos espera a todos.",facts:["1 jugador","reparto diario con semilla","sin conexión"],howToPlay:{summary:"Spider al estilo Microsoft con dos barajas: diez columnas, cinco filas de reserva y ocho palos que hay que pelar.",objective:"Lleva ocho series del mismo palo de Rey a As a las bases.",sections:[{heading:"El reparto",body:["Se reparten diez columnas: las cuatro primeras tienen seis cartas y el resto cinco. Solo la carta superior de cada columna empieza boca arriba. Quedan cincuenta cartas en el mazo como cinco filas de diez."]},{heading:"Construye el tablero",body:["Coloca las cartas en orden descendente, cualquier palo. Solo una serie descendente del mismo palo puede moverse en bloque. Una columna vacía acepta cualquier carta o serie."]},{heading:"Reparte una fila",body:["Pulsa el mazo para dar una carta boca arriba a cada columna. No puedes repartir si alguna columna está vacía o si quedan menos de diez cartas."]},{heading:"Pela un palo",body:["Cuando se completa una serie del mismo palo de Rey a As en una columna, se retira a una base en el mismo movimiento. Una carta tapada que quede al descubierto se voltea sola."]},{heading:"Los palos",body:["Relajado pinta las 104 cartas como picas. Clásico (el diario) usa picas y corazones. Difícil usa todos los palos, así que las series empaquetadas son más raras."]}]},modes:{daily:{name:"Diario",tagline:"Una mesa para todos",description:"Un reparto de dos palos con semilla de la fecha. Repítelo, compártelo o vuelve mañana a por una mesa nueva.",facts:["dos palos","mismo reparto diario","cinco filas de mazo"]},relaxed:{name:"Relajado",tagline:"Todas picas",description:"Un reparto nuevo más suave: cada carta es una pica, así que las series se arman con facilidad.",facts:["un palo","reparto nuevo","cinco filas de mazo"]},classic:{name:"Clásico",tagline:"Dos palos",description:"Un reparto nuevo con semilla pintado en picas y corazones — el predeterminado de Microsoft.",facts:["dos palos","reparto nuevo","cinco filas de mazo"]},hard:{name:"Difícil",tagline:"Cuatro palos",description:"El reparto completo de dos barajas. Las series del mismo palo escasean y cada pelo se gana.",facts:["cuatro palos","reparto nuevo","cinco filas de mazo"]}},fields:{suitCount:{label:"Palos",group:"Reparto",options:{1:"Un palo — relajado",2:"Dos palos — clásico",4:"Cuatro palos — difícil"},help:"Los repartos de un palo son todas picas. El clásico usa picas y corazones. El difícil usa todos los palos."}},presets:{relaxed:"Relajado",classic:"Clásico",hard:"Difícil"}},pyramid:{name:"Pirámide",subtitle:"empareja hasta trece",tagline:"Despeja la pirámide diaria",description:"Veintiocho cartas en un triángulo. Empareja rangos libres que sumen 13, gira el mazo y deja lo menos posible.",facts:["1 jugador","pirámide diaria con semilla","sin conexión"],howToPlay:{summary:"Un solitario a un jugador: veintiocho cartas en pirámide y un mazo que se gira sobre un único descarte.",objective:"Empareja cartas libres que sumen trece y limpia la mesa. Las que queden son tu puntuación: cuanto menos, mejor.",sections:[{heading:"El reparto",body:["Siete filas forman una pirámide de veintiocho cartas boca arriba. Una carta está libre cuando desaparecen las dos que la cubren — o cuando está en la última fila. Las veinticuatro restantes son el mazo. El descarte empieza vacío."]},{heading:"Empareja hasta trece",body:["El As vale 1 y el Rey vale 13. Cualquier par de cartas libres cuyos rangos sumen 13 se puede emparejar — Dama y As, Jota y 2, y así. Un Rey ya vale 13 y se retira solo. Los palos no importan."]},{heading:"El descarte",body:["Gira una carta del mazo al descarte cada vez. Solo la carta superior del descarte está viva: emparéjala con una carta libre de la pirámide, o retírala si es un Rey. Las cartas enterradas del descarte no se emparejan entre sí."]},{heading:"Reciclar",body:["Cuando el mazo se acaba, vuelve a voltear el descarte sin barajar. Clásico permite dos reciclajes — tres pasadas. Relajado no se acaba nunca."]},{heading:"La puntuación",body:["La partida termina cuando no queda ninguna carta, o cuando nada empareja y el mazo no puede volver. Cada carta que siga en la pirámide, el mazo o el descarte cuenta. Cero es un clear."]}]},modes:{daily:{name:"Diario",tagline:"Una pirámide para todos",description:"Una pirámide Clásica con semilla de la fecha. Repítela, compártela o vuelve mañana a por una mesa nueva.",facts:["dos reciclajes","mismo reparto diario","gana quien deja menos"]},classic:{name:"Clásico",tagline:"Tres pasadas",description:"Una pirámide nueva con semilla. El descarte se puede reciclar dos veces — tres viajes por el mazo.",facts:["dos reciclajes","reparto nuevo","tres pasadas"]},relaxed:{name:"Relajado",tagline:"Pasadas ilimitadas",description:"La misma mesa de emparejar, pero el descarte se puede volver a girar las veces que quieras.",facts:["reciclajes ilimitados","reparto nuevo","sin límite de pasadas"]}},fields:{recyclesLimit:{label:"Reciclajes del descarte",group:"Mazo",options:{2:"Dos reciclajes — clásico","-1":"Ilimitados — relajado"},help:"Clásico permite dos reciclajes, tres pasadas por el mazo. Relajado no se acaba nunca."}},presets:{classic:"Clásico",relaxed:"Relajado"}},eights:{name:"Ocho Loco",subtitle:"el juego de vaciar la mano con comodines",tagline:"Los ochos van donde quieran",description:"Una baraja corriente y una pila que no para de crecer. Sigue el palo o el valor, suelta un ocho para doblar la mesa al palo que quieras y cóbrale a los demás todo lo que aún tengan en la mano.",facts:["2–6 jugadores","partida a puntos","solo o con amigos"],howToPlay:{summary:"Una baraja corriente, una pila y ochos que van encima de cualquier cosa. Vacía tu mano y cóbrale a la mesa lo que todavía tenga.",objective:"Vacía tu mano para terminar la ronda y cóbrate todas las cartas que les queden a los demás. El primero en superar la puntuación objetivo se lleva la partida.",sections:[{heading:"Jugar una carta",body:["En tu turno, juega una carta que coincida con la pila en palo o en valor: un 7♦ vale sobre cualquier diamante y sobre cualquier otro siete.","El ocho es comodín. Va encima de cualquier carta, y eliges tú el palo que debe seguirlo.","¿Nada que jugar? Roba. La pila pide el mismo palo hasta que alguien lo cambie."]},{heading:"Cartas de acción",body:["Cada una de estas es un ajuste de mesa, así que cada casa puede jugar tan tranquila o tan ruidosa como quiera."],bullets:[{label:"8 — comodín",text:"siempre se puede jugar; tú eliges el palo que sigue (siempre activo)"},{label:"2 — roba dos",text:"el siguiente asiento roba dos cartas y pierde el turno"},{label:"Q — saltar",text:"el turno pasa por encima del siguiente asiento"},{label:"A — invertir",text:"la mesa cambia de sentido; entre dos jugadores te da otro turno seguido"}]},{heading:"Robar",body:["Por tradición, sigues robando hasta que tengas algo jugable. Desactívalo y cada turno solo te da derecho a una carta.","Una carta que robas y que se puede jugar es tuya para jugarla en el acto o para quedártela, a menos que la mesa obligue a jugarla.","Cuando se acaba el mazo, todo lo que hay bajo la carta boca arriba se vuelve a barajar en un mazo nuevo."]},{heading:"Puntuación de la ronda",body:["En el momento en que una mano se vacía, todos los demás cuentan lo que aún tienen en la mano y quien se quedó sin cartas se lleva el total."],bullets:[{label:"Cada ocho",text:"50 puntos"},{label:"Cualquier 10, J, Q o K",text:"10 puntos"},{label:"Cualquier as",text:"1 punto"},{label:"Todo lo demás",text:"su valor nominal"},{label:"Una ronda bloqueada",text:"se acaba el mazo y nadie puede jugar: gana la mano más ligera y se lleva la diferencia"}]},{heading:"Ganar la partida",body:["Se siguen repartiendo rondas, con el reparto pasando un asiento cada vez, hasta que alguien supera la puntuación objetivo. Gana la puntuación más alta.","Un empate en la cima reparte otra ronda en vez de repartir la corona."]}]},modes:{classic:{name:"Clásico",tagline:"Ochos y nada más",description:"El juego tal como lo repartía tu abuela. Sigue el palo o el valor, juega un ocho para cantar un palo y roba hasta que algo encaje. El primero en llegar a 100 gana.",facts:["solo el 8 es comodín","roba hasta poder jugar","a 100"]},house:{name:"Casero",tagline:"Doses, reinas y ases",description:"Las reglas que casi todo el mundo juega en realidad: los doses reparten cartas, las reinas saltan al siguiente asiento y los ases dan la vuelta a la mesa. El primero en llegar a 100 gana.",facts:["2 · Q · A activos","sin acumular","a 100"]},chaos:{name:"Alocado",tagline:"A acumular sin parar",description:"Los doses se acumulan sobre doses hasta que alguien se traga el montón entero, la carta que robas hay que jugarla, y solo tienes derecho a robar una vez por turno. Partida larga, mesa ruidosa.",facts:["acumulación activada","jugada forzada","a 150"]}},fields:{handSize:{label:"Cartas repartidas",help:"Cuántas cartas recibe cada asiento al empezar una ronda.",group:"El reparto"},targetScore:{label:"Jugar hasta",help:"Se siguen repartiendo rondas hasta que alguien supera esta puntuación.",group:"El reparto"},twosDrawTwo:{label:"Doses roban dos",help:"El siguiente asiento roba dos cartas y pierde el turno.",group:"Cartas de acción"},queensSkip:{label:"Reinas saltan",help:"El turno pasa por encima del siguiente asiento.",group:"Cartas de acción"},acesReverse:{label:"Ases invierten",help:"Da la vuelta a la mesa. Con dos jugadores actúa como un salto.",group:"Cartas de acción"},stackDrawTwo:{label:"Acumular doses",help:"Responde a un dos con el tuyo y pasa toda la penalización acumulada.",group:"Reglas de la casa"},drawUntilPlayable:{label:"Robar hasta poder jugar",help:"La regla tradicional. Desactívala para robar exactamente una carta por turno.",group:"Reglas de la casa"},forcePlay:{label:"Jugada forzada",help:"Una carta que robas y que se puede jugar, hay que jugarla.",group:"Reglas de la casa"}},presets:{classic:"Ochos clásicos",house:"Ochos de casa",chaos:"Ocho Loco"}},durak:{name:"Durak",subtitle:"el tonto que nadie quiere ser",tagline:"Nunca seas el último con cartas en la mano",description:"Una baraja corta, un palo de triunfo y una mesa de ataques y defensas. Detén cada carta que te lancen o recógelo todo — el último asiento que se quede con cartas se lleva el gorro de tonto.",facts:["2–6 jugadores","baraja de 36 cartas","solo o con amigos"],howToPlay:{summary:"Una baraja corta, un palo de triunfo y un solo trabajo: no ser el último asiento con cartas en la mano.",objective:"Vacía tu mano y quédate fuera para siempre. En cuanto se acaba el mazo, el último asiento que aún tenga cartas es el Durak.",sections:[{heading:"El reparto",body:["Cada asiento recibe seis cartas de una baraja de 36: del seis al as, cuatro palos, sin doses, treses, cuatros ni cincos.","La siguiente carta del mazo se voltea: su palo es el triunfo de toda la mano, y queda boca arriba hasta que se acaba el mazo.","Quien tenga el triunfo más bajo ataca primero. ¿Nadie tiene uno? Abre el asiento uno."]},{heading:"Atacar y defender",body:["El atacante juega una carta. El defensor debe superarla: una carta más alta del mismo palo, o cualquier triunfo si el ataque no era de triunfo.","Los demás asientos pueden sumar más cartas, siempre que el valor ya haya aparecido en la mesa — ganada o perdida, esa carta sigue siendo válida hasta que termine la baza.","Supera todas las cartas y toda la mesa se retira, fuera del juego para siempre — atacas tú a continuación.","¿No puedes superar una? Recoge toda la mesa en tu mano. El turno pasa al asiento siguiente al tuyo."],bullets:[{label:"Límite de ataque",text:"un defensor nunca ve más cartas de las que tenía cuando empezó la baza"},{label:"Reponer",text:"después de cada baza, las manos vuelven a seis — primero el atacante, luego el resto, el defensor al final"}]},{heading:"Perevodnoy (transferencia)",body:["Cuando esta regla de casa está activa, un defensor que aún no haya superado nada puede transferir en su lugar: juega una carta del mismo valor, y el siguiente asiento hereda todo el ataque."]},{heading:"El final de la mano",body:["En cuanto se acaba el mazo, vaciar tu mano te deja fuera para siempre — para bien, en el orden en que ocurra.","El último asiento que se queda con cartas es el Durak. Todos los demás se clasifican según lo pronto que salieron."]}]},modes:{classic:{name:"Clásico",tagline:"Podkidnoy — el juego tradicional de sumar cartas",description:"Ataca, defiende y suma cualquier carta cuyo valor ya esté en la mesa. Sin transferencias: superas la carta o recoges la mesa.",facts:["sumar cartas activo","sin transferencia","manos de 6 cartas"]},transfer:{name:"Perevodnoy",tagline:"Pasa todo el ataque",description:"Todo lo del modo Clásico, más una salida: un defensor que aún no haya superado nada puede transferir un valor igual directo al siguiente asiento.",facts:["transferencias activas","sumar cartas activo","manos de 6 cartas"]},"heads-up":{name:"Uno contra uno",tagline:"Cara a cara, final rápido",description:"Pensado para dos. La primera mano que se vacía gana en el acto, con o sin mazo — sin esperar a que se agote la baraja.",facts:["2 jugadores","victoria instantánea","rápido"]}},fields:{transfer:{label:"Transferencia (perevodnoy)",help:"Un defensor con un valor igual puede pasar todo el ataque al siguiente asiento en vez de superarlo.",group:"La baza"},throwIns:{label:"Sumar cartas (podkidnoy)",help:"Cualquier asiento atacante puede sumar más cartas cuyo valor ya esté en la mesa.",group:"La baza"},maxAttacks:{label:"Límite de ataque",help:"El máximo de cartas de ataque que puede ver un defensor en una baza.",group:"La baza"},refillTo:{label:"Tamaño de mano",help:"Cartas repartidas al empezar, y el tamaño al que vuelve cada mano tras una baza.",group:"El reparto"},instantWin:{label:"Victoria instantánea",help:"La primera mano que se vacía gana en el acto, aunque el mazo todavía tenga cartas.",group:"Reglas de la casa"}},presets:{classic:"Durak clásico",transfer:"Perevodnoy","heads-up":"Uno contra uno"}},palace:{name:"Palace",subtitle:"el juego de vaciar capas",tagline:"Vacía la mesa, capa por capa",description:"Mano, luego boca arriba, luego boca abajo — quema los dieses, esquiva los doses y sé el primero en vaciar cada capa. También conocido como Shithead o Karma.",facts:["2–6 jugadores","doses, dieces y ochos","solo o con amigos"],howToPlay:{summary:"Deshazte de todo lo que tengas — mano, luego fila boca arriba, luego fila boca abajo — antes de que nadie más vacíe la mesa.",objective:"Vacía tu mano, tu fila boca arriba y tu fila boca abajo primero para ganar la ronda. Las rondas ganadas se acumulan en la partida; el primero en llegar al objetivo se lleva la partida.",sections:[{heading:"El reparto",body:["A todos les tocan tres cartas boca abajo, tres cartas boca arriba encima de esas, y tres cartas en la mano.","Antes de empezar, cambia tantas cartas de la mano como quieras por tus propias cartas boca arriba — tienes un solo cambio, luego te declaras listo."]},{heading:"Jugar a la pila",body:["En tu turno, juega una o más cartas del mismo valor que igualen o superen el valor de la pila, o recoge toda la pila hacia tu mano.","Debes vaciar tu mano antes de tocar tu fila boca arriba, y vaciar la fila boca arriba antes de tocar la fila boca abajo."],bullets:[{label:"Abrir la ronda",text:"quien tenga la carta ordinaria más baja empieza — primero los treses, luego subiendo"},{label:"Recoge cuando quieras",text:"puedes tomar la pila incluso teniendo una jugada legal — a veces es la jugada más segura"},{label:"Jugadas boca abajo",text:"con la mano y la fila boca arriba vacías, voltea una carta boca abajo a ciegas — si supera la pila, se queda en juego y continúas; si no, recoges la pila y la carta"}]},{heading:"Especiales",body:["Cuatro valores cambian las reglas — todos activos por defecto, todos ajustables:"],bullets:[{label:"2 — reinicio",text:"se juega sobre cualquier cosa; el nivel de la pila baja casi a cero"},{label:"10 — quema",text:"se juega sobre cualquier cosa; la pila sale del juego y juegas otra vez"},{label:"8 — invisible",text:"siempre se puede jugar y nunca cambia lo que pide la pila — el siguiente responde a lo que hay debajo"},{label:"Cuatro iguales",text:"cuatro cartas del mismo valor encima de la pila la queman, como sea que hayan llegado ahí — juegas otra vez"}]},{heading:"Ganar la ronda",body:["En el momento en que un asiento vacía mano, fila boca arriba y fila boca abajo juntas, la ronda termina de inmediato.","Todos los demás se ordenan por cuántas cartas les quedan — menos es mejor — y el desempate es cuántas cartas boca abajo les quedan."]},{heading:"Reglas de la casa",body:["Ajusta la mesa en las opciones de sala antes de empezar:"],bullets:[{label:"Cambio antes de jugar",text:"desactívalo para pasar directo del reparto a la primera jugada"},{label:"El 2 reinicia / el 10 quema / el 8 siempre se juega",text:"desactiva cualquier especial para que ese valor sea ordinario"},{label:"Cuatro iguales queman",text:"desactívalo para que una pila de valores iguales simplemente siga creciendo"},{label:"Primero a (rondas ganadas)",text:"cuántas rondas hacen falta para ganar la partida — 1 para una mano rápida, hasta 7 para una noche larga"}]}]},modes:{classic:{name:"Clásico",tagline:"La subida completa por capas",description:"Cambia, luego vacía mano, boca arriba y boca abajo. El primero en ganar tres rondas se lleva la mesa.",facts:["a 3 rondas","cambio activado","todos los especiales"]},quick:{name:"Rápido",tagline:"Una ronda y ya está",description:"Una sola ronda lo decide todo — los mismos especiales, sin partida larga que acumular.",facts:["a 1 ronda","~10 min","ideal para calentar"]},chaos:{name:"Caos",tagline:"Sin cambio, sin piedad",description:"Directo del reparto a la partida — sin fase de cambio para planear. Todos los especiales al máximo: el 2 reinicia, el 10 quema, el 8 sigue siendo invisible, cuatro iguales incendian la pila.",facts:["a 3 rondas","sin fase de cambio","espera quemas"]}},fields:{allowSwap:{label:"Cambio antes de jugar",help:"La fase de cambio entre el reparto y la primera jugada."},twosReset:{label:"El 2 reinicia la pila",help:"Se juega sobre cualquier cosa y reinicia el nivel de la pila."},tensBurn:{label:"El 10 quema la pila",help:"Se juega sobre cualquier cosa y quema la pila; el mismo asiento juega otra vez."},eightsBlind:{label:"El 8 siempre se puede jugar",help:"Siempre es una jugada legal y no cambia el nivel de la pila."},fourKindBurn:{label:"Cuatro iguales queman",help:"Cuatro cartas del mismo valor encima de la pila la queman; el mismo asiento juega otra vez."},winsTo:{label:"Primero a (rondas ganadas)",help:"La partida termina cuando un asiento acumula esta cantidad de rondas ganadas."}},presets:{classic:"Palace clásico",quick:"Palace rápido",chaos:"Palace caótico"}},pinochle:{name:"Pinacle",subtitle:"el juego de parejas",tagline:"Puja, declara y hazte con las bazas",description:"Siéntate frente a tu compañero, gana la subasta, nombra el triunfo y declara tu juego. Ases, dieces y reyes son las cartas que cuentan — cumple tu puja o te quedas corto y lo pagas.",facts:["4 jugadores · 2v2","puja · declaración · bazas","solo o con amigos"],howToPlay:{summary:"El clásico americano de parejas — puja, nombra el triunfo, declara tu juego y juega las bazas.",objective:"Sentado frente a tu compañero, gana la subasta y cumple tu puja — declaración más puntos de baza al menos iguales a lo que cantaste. El primer equipo en llegar a la puntuación objetivo tras una mano completa gana la partida.",sections:[{heading:"La mesa",body:["Cuatro jugadores, dos equipos: tú y el jugador de enfrente sois compañeros. Cada mano reparte el mazo doble completo de 48 cartas — doce para cada uno, sin viuda. El reparto rota a la izquierda en cada mano."]},{heading:"La puja",body:["Empezando a la izquierda del repartidor, cada silla pasa o puja más alto que la puja anterior. Una vez que pasas, quedas fuera de la mano. La última silla con una puja en pie gana la subasta y nombra el triunfo. Si todos pasan sin que nadie puje, la mano se descarta y se reparte de nuevo con el mismo repartidor."],bullets:[{label:"Puja inicial",text:"debe superar el mínimo de la mesa (25 en el modo Clásico)"},{label:"Subidas",text:"cualquier entero más alto, hasta un tope de 60"}]},{heading:"La declaración",body:["Una vez nombrado el triunfo, cada silla declara su juego para sumar puntos. Las cartas se quedan en la mano — declarar es puntuar, no descartar — y la mesa lo calcula por ti, así que nadie puede declarar de más."],bullets:[{label:"Escalera de triunfo",text:"As-10-Rey-Reina-Jota de triunfo, 15 puntos"},{label:"Matrimonio",text:"Rey + Reina de un palo — 4 si es triunfo (2 más si es una segunda pareja además de la escalera), 2 si no lo es"},{label:"Pinacle",text:"Reina de picas + Jota de diamantes vale 4; tener ambas copias de cada una es un doble pinacle que vale 30"},{label:"Rondas",text:"una carta de un valor en los cuatro palos — Ases 10, Reyes 8, Reinas 6, Jotas 4"},{label:"Dix",text:"cada 9 de triunfo que tengas vale 1"}]},{heading:"Jugar las bazas",body:["El pujador abre la primera baza. Debes seguir el palo si puedes; el triunfo vence a un palo abierto que no sea triunfo, y si no, gana la carta más alta. As, diez y rey valen 10 puntos cada uno al capturarlos en una baza; la última baza vale 10 más. El ganador de una baza abre la siguiente."]},{heading:"Puntuar una mano",body:["Suma la declaración del equipo pujador a los puntos de baza que consiguió. Si cumple la puja, se anota el total completo. Si se queda corto, se queda en contra — pierde exactamente el valor de la puja, declaración incluida. El otro equipo siempre anota sus propios puntos de baza, y también su declaración salvo que la mesa lo haya desactivado."]},{heading:"La partida",body:["Las manos se acumulan hasta que un equipo llega al objetivo (100 / 150 / 500). Si ambos equipos lo superan en la misma mano, el equipo pujador gana la partida directamente salvo que se haya quedado corto — en ese caso pierde el desempate frente a la puntuación más alta, y el pujador gana cualquier empate restante."]},{heading:"Reglas de la casa",body:["Los ajustes de la sala cambian la puntuación objetivo, la puja mínima de apertura y si los rivales anotan su declaración. Las mesas Clásicas mantienen los valores por defecto."]}]},modes:{classic:{name:"Clásico",tagline:"Partida a 150",description:"Pinacle de parejas a 150, puja mínima de apertura 25. El juego tal como se juega en cualquier mesa de cocina.",facts:["partida a 150","puja mín. 25","~30 min"]},quick:{name:"Rápida",tagline:"Primero a 100",description:"Las mismas reglas, carrera más corta — 100 puntos, puja de apertura más baja, se acaba antes.",facts:["partida a 100","puja mín. 20","~15 min"]},marathon:{name:"Maratón",tagline:"Partida a 500",description:"Una larga batalla de parejas hasta 500 — cada declaración y cada puja fallida cuentan.",facts:["partida a 500","puja mín. 25","~90 min"]}},fields:{target:{label:"Partida a",group:"Partida",help:"Tras cada mano, la primera pareja que llegue a esta puntuación o la supere gana.",options:{100:"100 — rápida",150:"150 — clásica",500:"500 — maratón"}},minBid:{label:"Puja mínima",group:"Puja",help:"La puja de apertura de la subasta debe superar este mínimo. Cada puja posterior debe superar a la anterior, hasta 60."},opponentsScoreMeld:{label:"Los rivales anotan declaración",group:"Puntuación",help:"Si está desactivado, el equipo que no puja solo anota los puntos de baza que consiga — no su declaración."}},presets:{classic:"Clásico",quick:"Rápida",marathon:"Maratón"}},tripeaks:{name:"TriPeaks",subtitle:"despeja los tres picos",tagline:"Juega ±1 sobre el hueco",description:"Dieciocho cartas en tres picos, todas boca arriba. Libera una carta despejando lo que la cubre, encadena jugadas sobre el hueco y despeja los picos.",facts:["1 jugador","picos diarios con semilla","sin conexión"],howToPlay:{summary:"Un solitario a un jugador: tres picos de dieciocho cartas, todas boca arriba, y un mazo que se gira sobre un único hueco.",objective:"Despeja todas las cartas de los picos. Las que queden son tu puntuación: cuanto menos, mejor.",sections:[{heading:"El reparto",body:["Tres picos de dieciocho cartas están boca arriba en cuatro filas. La fila base de nueve siempre está libre. Las treinta y cuatro cartas restantes forman el mazo, y la primera abre el hueco."]},{heading:"Cartas libres",body:["Una carta queda libre cuando las dos cartas que descansan sobre ella desaparecen. Solo las cartas libres se pueden mover — las que siguen cubiertas quedan atrapadas hasta que sus hijas se despejen."]},{heading:"Juega sobre el hueco",body:["Juega una carta libre sobre el hueco cuando esté a un rango de distancia — un 8 acepta un 7 o un 9. Los palos y colores no importan. Encadena todas las jugadas que puedas."]},{heading:"Gira el mazo",body:["Si nada en los picos encaja, gira la siguiente carta del mazo sobre el hueco. La carta anterior del hueco queda enterrada debajo."]},{heading:"As, Rey y el mazo",body:["El TriPeaks Clásico trata el As y el Rey como callejones sin salida, y el mazo nunca vuelve. Relajado permite que el As y el Rey se enlacen, y permite barajar el hueco de vuelta al mazo una vez que se agota."]},{heading:"La puntuación",body:["La partida termina cuando los picos quedan despejados, o cuando nada juega y el mazo no puede volver. Las cartas que queden en los picos son tu puntuación. Cero es un despeje total."]}]},modes:{daily:{name:"Diario",tagline:"Un reparto para todos",description:"Un reparto Clásico con semilla de la fecha. Repítelo, compártelo o vuelve mañana a por picos nuevos.",facts:["sin enlace","mismo reparto diario","gana quien deja menos"]},classic:{name:"Clásico",tagline:"As y Rey te detienen",description:"Un reparto nuevo con semilla. El As y el Rey son callejones sin salida; el mazo nunca vuelve.",facts:["sin enlace","reparto nuevo","sin reciclaje"]},relaxed:{name:"Relajado",tagline:"El As enlaza con el Rey",description:"Los mismos tres picos, pero el As y el Rey se juegan entre sí y el hueco se puede reciclar una vez.",facts:["enlaza A–K","reparto nuevo","un reciclaje"]}},fields:{wrap:{label:"El As enlaza con el Rey",group:"Hueco",help:"El TriPeaks Clásico detiene en el As y el Rey. Relajado deja que A y K se jueguen entre sí."},recycle:{label:"Reciclar el hueco",group:"Mazo",help:"Cuando el mazo se agota, baraja el hueco (menos su carta superior) de vuelta al mazo una vez."}},presets:{classic:"Clásico",relaxed:"Relajado"}}},fr:{blitz:{name:"Blitz",subtitle:"le jeu du 31",tagline:"File vers le 31",description:"Pioche, échange et frappe pour atteindre 31 dans une seule couleur. Trois formats de partie, des robots rusés et une célébration très bruyante.",facts:["2–4 joueurs","classique · rapide · chronométré","solo ou entre amis"],howToPlay:{summary:"Le classique du pub, le 31 — pioche, échange et frappe pour réunir une couleur qui vaut 31.",objective:"Avoir une main plus forte que tout le monde à la fin de la manche. Une main compte sa meilleure couleur : A=11, figures=10, cartes numérotées leur valeur. 31 dans une seule couleur, c’est un BLITZ, et ça gagne sur-le-champ.",sections:[{heading:"Ton tour",body:["Tu as deux actions :"],bullets:[{label:"Piocher",text:"prends la carte du dessus du talon, ou rafle le dessus de la défausse"},{label:"Défausser",text:"glisse une carte de ta main, face visible, sur la pile"}]},{heading:"Compter une main",body:["Seule ta meilleure couleur compte. Trois cœurs qui totalisent 27 battent trois cartes mélangées qui totalisent 30.","Un brelan est une main spéciale qui vaut 30½ (option de la maison)."]},{heading:"Frapper",body:["Au lieu de piocher, tu peux FRAPPER pour clore la manche. Tout le monde a exactement un dernier tour, puis les mains se retournent pour le dénouement.","La main la plus faible perd une vie. Si c’est TOI qui as frappé et que tu finis à égalité ou dernier, la pénalité est pour toi — frappe avec assurance."]},{heading:"Blitz !",body:["31 dans une seule couleur et la manche explose aussitôt — tous les autres joueurs perdent une vie, sans dénouement.","Un Blitz servi avant ton premier tour ? Ça compte. N’hésite pas à fanfaronner."]},{heading:"Formats de partie",bullets:[{label:"Classique",text:"perds une vie à chaque manche perdue ; le dernier joueur avec des vies gagne"},{label:"Rapide",text:"manches indépendantes, compteur de victoires, redonne immédiate"},{label:"Chronométré",text:"horloge de partie, tours forcés au chrono, le plus de manches gagnées au gong l’emporte"}]},{heading:"Règles de la maison",body:["Chaque table se règle dans les paramètres de la salle — vies, pénalités de frappe, égalités, brelan, verrou de défausse et chronos de tour s’y trouvent."]}]},modes:{classic:{name:"Classique",tagline:"Des vies en jeu",description:"Perds une manche, perds une vie. Frappe tôt ou vise le 31 parfait — le dernier joueur avec des jetons remporte la partie.",facts:["3 vies chacun","le dernier debout","~5–10 min"]},fast:{name:"Rapide",tagline:"Une manche à la fois",description:"Des manches indépendantes, une redonne immédiate. La meilleure main remporte le pot — le premier à trois gagne la partie.",facts:["le premier à 3 victoires","pas d’élimination","~2–4 min"]},timed:{name:"Chronométré",tagline:"Course contre le gong",description:"Une horloge de partie de trois minutes et des tours éclair. Le plus de manches gagnées à la cloche l’emporte.",facts:["horloge de 3:00","chrono de 7 s par tour","égalités en mort subite"]}},fields:{threeOfAKind:{label:"Brelan",options:{"30.5":"Vaut 30.5",30:"Vaut 30",off:"Désactivé"}},tieLowest:{label:"Derniers à égalité",options:{both:"Les deux perdent",nobody:"Personne ne perd",redeal:"Redonne entre les ex æquo"}},discardLock:{label:"Verrouiller la défausse que tu viens de piocher"}},presets:{"classic-pub":"Pub classique",cutthroat:"Sans pitié",friendly:"Amicale"}},cribbage:{name:"Cribbage",subtitle:"la course aux fiches",tagline:"Fiche jusqu’à 121",description:"La grande course de pub — fabrique des quinzes, des suites et des paires dans ta main, fiche-les sur le plateau, et prie pour que personne ne retourne un valet derrière toi.",facts:["2 joueurs","classique · sans pitié","solo ou entre amis"],howToPlay:{summary:"La grande course de pub — fabrique des combinaisons qui rapportent dans ta main, puis fiche-les jusqu’à 121.",objective:"Sois le premier à ficher 121 points sur le plateau. Les points viennent deux fois : en jouant les cartes sur la table (le fichage) puis en comptant ta main et le crib au décompte.",sections:[{heading:"La donne",body:["Tu reçois six cartes. Gardes-en quatre et glisses-en deux, face cachée, dans le CRIB — une main bonus qui rapporte à celui qui donne.","Donne généreusement quand le crib est à toi, prudemment quand il est à l’autre."]},{heading:"La coupe",body:["Le donneur coupe le talon pour révéler la carte de départ, commune à toutes les mains.","Couper un valet rapporte ses TALONS — deux points immédiats pour le donneur."]},{heading:"Le fichage",body:["En commençant à gauche du donneur, chacun pose une carte à tour de rôle en tenant le compte courant des valeurs (les figures valent 10). Tu ne peux jamais faire dépasser 31 au compte.","Marque en jouant :"],bullets:[{label:"Quinze",text:"ta carte porte le compte courant à exactement 15 — 2 points"},{label:"Paire / brelan / carré",text:"même rang que la carte précédente — 2 / 6 / 12 points"},{label:"Suite",text:"trois cartes ou plus qui se suivent, dans n’importe quel ordre — 1 point par carte"},{label:"Trente-et-un",text:"ta carte porte le compte à exactement 31 — 2 points"},{label:"Go et dernière carte",text:"si personne ne peut jouer sous 31, le dernier à avoir posé une carte marque 1 et le compte repart à zéro"}]},{heading:"Le décompte",body:["Après le fichage, chacun compte à voix haute : d’abord la main du non-donneur, puis celle du donneur, puis le crib. La carte de départ compte comme cinquième carte."],bullets:[{label:"Quinzes",text:"chaque combinaison de cartes dont la somme fait 15 — 2 points chacune"},{label:"Paires",text:"une paire 2, un brelan 6, un carré 12"},{label:"Suites",text:"les suites rapportent par carte ; les suites doubles se multiplient (7-7-8-9 = 12)"},{label:"Couleur",text:"quatre cartes de même couleur dans ta MAIN rapportent 4, cinq avec une carte de départ assortie. Dans le CRIB, seule une couleur aux cinq cartes compte."},{label:"Son valet",text:"un valet de la couleur de la carte de départ — 1 point"}]},{heading:"Victoire et skunks",body:["Le premier à 121 gagne, même en plein décompte. La donne alterne à chaque manche.","Avec la règle du skunk, un perdant qui finit sous 90 est SKUNKÉ — une vraie humiliation à savourer."]},{heading:"Règles de la maison",body:["Les réglages de la salle tranchent les disputes de pub :"],bullets:[{label:"Skunks",text:"signale les perdants sous 90 (activé par défaut)"},{label:"Muggins",text:"si tu oublies de réclamer des points gagnés à la table, ton adversaire peut te les voler (désactivé par défaut) — réclame vite !"}]}]},modes:{"classic-pub":{name:"Pub classique",tagline:"Le vrai jeu",description:"Six cartes, deux au crib, et une longue course de fiches jusqu’à 121. Les skunks comptent — finis sous 90 et on t’en parlera pour toujours.",facts:["course à 121","ligne de skunk à 90","~10–15 min"]},cutthroat:{name:"Sans pitié",tagline:"Muggins te regarde",description:"Même course, griffes plus longues : oublie de réclamer tes points à la table et ton adversaire les prend pour toi.",facts:["muggins activé","vole les points oubliés","aucune pitié"]},"match-play":{name:"Match",tagline:"Le meilleur de trois manches",description:"Une vraie longue soirée : cours jusqu’à 121, remets les fiches à zéro, puis recommence. Le premier à gagner deux parties complètes remporte le match.",facts:["2 parties gagnantes","la donne alterne","~25–40 min"]}},fields:{skunks:{label:"Ligne de skunk à 90"},muggins:{label:"Muggins (voler les points oubliés)"},gamesToWin:{label:"Parties à gagner"}},presets:{"classic-pub":"Pub classique",cutthroat:"Sans pitié","match-play":"Match",friendly:"Amical"}},wild:{name:"Wild",subtitle:"le jeu du délestage",tagline:"Débarrasse-toi de tout",description:"Une émeute de 112 cartes : passes, inversions, +4, vidages de couleur et cartes claquées à tout moment. Même table chaleureuse, un paquet bien plus bruyant.",facts:["2–4 joueurs","donne chronométrée","solo ou entre amis"],howToPlay:{summary:"Une émeute de délestage à 112 cartes — suis le dessus de la pile, déchaîne les cartes action et vide ta main en premier.",objective:"Sois le premier joueur sans cartes. Les cartes action ralentissent tout le monde — sauf si on te riposte.",sections:[{heading:"Jouer une carte",body:["À ton tour, joue une carte qui suit le dessus de la pile par la couleur ou par la figure, ou pioche à la place.","Les jokers se jouent à tout moment et te laissent choisir la prochaine couleur."]},{heading:"Cartes action",bullets:[{label:"Passe",text:"le joueur suivant perd son tour — et ne peut pas claquer de carte pour revenir"},{label:"Inversion",text:"le sens du jeu se renverse ; en tête-à-tête, elle te redonne un tour"},{label:"+2",text:"le joueur suivant pioche deux cartes et perd son tour"},{label:"Vide la couleur",text:"défausse sous elle toutes les cartes de sa couleur dans ta main ; les cartes action balayées ne se déclenchent pas"},{label:"Joker",text:"joue-le à tout moment et annonce la prochaine couleur"},{label:"Joker +4",text:"annonce la couleur ET colle quatre cartes au joueur suivant"},{label:"Joker échange",text:"annonce la couleur, puis échange ta main avec qui tu veux (carte optionnelle)"},{label:"Joker mélange",text:"rassemble toutes les mains, mélange, redonne (carte optionnelle)"}]},{heading:"Dernière carte",body:["Plus que deux cartes ? Appuie sur « Dernière carte ! » avant de jouer. Arrive à une carte sans l’avoir annoncé et tu es pris pour deux.","Piocher te fait repasser au-dessus de la ligne, il faudra donc l’annoncer à nouveau."]},{heading:"Les chronos",body:["Chaque tour est chronométré. Si le chrono tombe à zéro, la table joue un coup légal pour ce joueur afin que la pile continue de tourner.","La donne a aussi son horloge de partie. Pendant sa dernière minute, les places en direct de la première à la quatrième s’affichent et bougent avec les mains."],bullets:[{label:"À zéro",text:"le moins de cartes gagne ; les mains de même taille se départagent dans l’ordre des places pour que chaque partie ait un résultat net"},{label:"Options avancées",text:"règle les secondes par tour et les minutes de partie avant la donne"}]},{heading:"Chaos maison",body:["Chaque réglage de table se trouve dans les options avancées avant la donne :"],bullets:[{label:"Cumul",text:"réponds à un +2 / +4 par la même carte et la pénalité s’empile pour la prochaine victime"},{label:"Carte claquée",text:"tu tiens exactement la même figure que la carte qui vient d’être jouée ? Claque-la hors de ton tour avant que quiconque réagisse"},{label:"Pioche jusqu’à pouvoir jouer",text:"pioche jusqu’à ce qu’une carte suive, au lieu d’en piocher une seule"},{label:"Jeu forcé",text:"une carte piochée qui peut être jouée doit être jouée"},{label:"Défier les +4",text:"un +4 n’est honnête que sans rien dans l’ancienne couleur — dénonce le bluff et il ramasse la pile, trompe-toi et tu prends deux cartes de plus"},{label:"Sept et zéros",text:"un 7 échange ta main avec le joueur que tu nommes ; un 0 fait tourner toutes les mains d’une place"},{label:"Jokers d’échange",text:"ajoute le Joker échange et le Joker mélange au paquet"}]},{heading:"Gagner",body:["Vide ta main pour gagner avant la fin de l’horloge de partie. Sinon, à zéro, la main restante la plus légère l’emporte."]}]},modes:{classic:{name:"Classique",tagline:"À la lettre",description:"Suis la couleur ou le chiffre, puis vide toute une couleur d’un coup. Pas de cumul, pas de cartes claquées — une émeute polie.",facts:["une seule donne","pas de cumul","~5 min"]},party:{name:"Fête",tagline:"Empile et claque",description:"Les +2 et +4 s’empilent, et une carte identique permet à quiconque de claquer hors de son tour. Le chaos, sous une lumière chaude.",facts:["cumul activé","cartes claquées","~5 min"]},houseRules:{name:"Règles maison",tagline:"Tout est activé",description:"Les 7 échangent les mains, les 0 les font tourner, les jokers d’échange rejoignent le paquet, et une carte piochée doit être jouée.",facts:["échanges 7-0","jokers d’échange","jeu forcé"]}},fields:{handSize:{label:"Cartes distribuées",group:"La donne",help:"Combien de cartes chaque place reçoit au départ."},turnTimeSeconds:{label:"Secondes par tour",group:"Chronos",help:"Quand le chrono s’épuise, la table joue un coup légal pour cette place."},matchTimeMinutes:{label:"Minutes de partie",group:"Chronos",help:"À zéro, le joueur à la main restante la plus légère gagne."},stackDrawTwo:{label:"Cumuler les +2",group:"Pénalités",help:"Réponds à un +2 par le tien et fais passer la pile grandissante."},stackDrawFour:{label:"Cumuler les +4",group:"Pénalités",help:"Pareil pour les +4. Les pénalités peuvent monter vite."},jumpIn:{label:"Carte claquée",group:"Règles de la maison",help:"Tu tiens exactement la carte qui vient d’être jouée ? Claque-la hors de ton tour."},drawToMatch:{label:"Pioche jusqu’à pouvoir jouer",group:"Règles de la maison",help:"Pioche jusqu’à ce qu’une carte suive, au lieu d’en piocher une seule."},forcePlay:{label:"Jeu forcé",group:"Règles de la maison",help:"Une carte piochée qui peut être jouée doit être jouée."},sevenZero:{label:"Sept et zéros",group:"Règles de la maison",help:"Joue un 7 pour échanger ta main avec quelqu’un ; joue un 0 pour faire tourner toutes les mains."},challengeDrawFour:{label:"Défier les +4",group:"Règles de la maison",help:"Un +4 n’est honnête que sans rien dans la couleur en cours. Dénonce le bluff : gagné, il ramasse les cartes ; perdu, tu en prends deux de plus."},swapCards:{label:"Jokers d’échange",group:"Le paquet",help:"Ajoute le Joker échange et le Joker mélange à la donne."}},presets:{classic:"Wild classique",party:"Pile en fête",houseRules:"Règles maison"}},ratscrew:{name:"Bataille corse",subtitle:"le jeu de tapes",tagline:"Tape le tas la première",description:"Retourne tes cartes sur un tas commun et tape les doubles, les sandwichs et plus encore avant tout le monde. Réflexes en temps réel, défis de figures, cartes brûlées pour les fausses tapes.",facts:["2–4 joueurs","tapes en temps réel","solo ou entre amis"],howToPlay:{summary:"Retourne des cartes à tour de rôle sur un tas commun et TAPE pour gagner toutes les cartes de la table.",objective:"Gagne les 52 cartes. Tu grossis ton paquet en tapant les motifs en premier ou en posant des figures auxquelles tes adversaires ne peuvent pas répondre. Quand tout le monde est à court de cartes — ou tape pour revenir en jeu — tu remportes la partie.",sections:[{heading:"Retourner les cartes",body:["En commençant par toi, chacun pose à tour de rôle la carte du dessus de son paquet face cachée sur le tas central, en la retournant loin de soi pour que personne ne triche.","Si ton paquet s’épuise, tu arrêtes de retourner — mais avec Retour par la tape activé, une seule tape chanceuse te remet directement en jeu."]},{heading:"Figures et défis",body:["Une figure lance un défi contre le joueur suivant dans l’ordre du tour :"],bullets:[{label:"Valet",text:"il a 1 chance de retourner une autre figure"},{label:"Dame",text:"2 chances"},{label:"Roi",text:"3 chances"},{label:"As",text:"4 chances"}]},{heading:"Résoudre un défi",body:["Chaque carte qui n’est pas une figure brûle une des chances du joueur défié.","Il retourne une nouvelle figure ? Le défi fait le tour de la table avec des chances fraîches pour le joueur suivant.","Il est à court de chances ? Le joueur de la figure ramasse tout le tas central sous son paquet et entame le prochain retournement."]},{heading:"Les tapes",body:["Dès qu’un motif tappable tombe sur le tas, TOUT LE MONDE se précipite pour taper. La première tape valide gagne tout le tas central et entame la suite.","Une courte fenêtre de tape s’ouvre chaque fois qu’un motif est en jeu — écrase le bouton TAPE avant qu’elle ne se referme !"],bullets:[{label:"Double",text:"deux cartes du même rang à la suite (7♦ 7♣)"},{label:"Sandwich",text:"même rang avec une carte entre les deux (7♦ Q♠ 7♥)"},{label:"Mariage",text:"un roi et une dame à la suite, dans n’importe quel ordre (K♦ Q♠) — option de la maison"},{label:"Dix",text:"deux cartes à points consécutives dont la somme fait dix (3♦ 7♠) — option de la maison"},{label:"Haut-bas",text:"la carte du dessus correspond à celle tout en bas du tas — option de la maison"},{label:"Suite",text:"trois rangs qui montent ou descendent d’affilée (4-5-6 ou 9-8-7) — option de la maison"}]},{heading:"Fausses tapes",body:["Taper sans motif en jeu te coûte cher : avec Fausse tape brûlante activé, ta carte du dessus glisse sous le tas en pénalité. Les nerfs coûtent cher — garde les yeux sur les cartes, pas sur le public."]},{heading:"Règles de la maison",body:["Règle le chaos dans les paramètres de la salle avant de commencer :"],bullets:[{label:"Doubles / Sandwichs",text:"les motifs de tape classiques, tous deux actifs par défaut"},{label:"Mariage / Dix / Haut-bas / Suites",text:"motifs supplémentaires, tous désactivés par défaut pour une table classique"},{label:"Fausse tape brûle une carte",text:"actif par défaut ; désactivé, seuls les motifs en jeu peuvent être tapés"},{label:"Retour par la tape",text:"les joueurs à court de cartes peuvent encore taper un motif en jeu pour gagner le tas et revenir"},{label:"Fenêtre de tape",text:"la durée pendant laquelle la course reste ouverte — plus court, plus cruel"}]},{heading:"Savoir-vivre à table",body:["Le vainqueur du tas le glisse sous son paquet sans mélanger et retourne la suivante. Le dernier joueur à détenir toutes les cartes remporte la partie.","Un bref moment de grâce garde les tapes à distance honnêtes : la table attend un temps après la fenêtre avant de la déclarer close."]}]},modes:{classic:{name:"Tape classique",tagline:"Doubles et sandwichs",description:"Le standard du pub : retourne vite, guette les doubles et les sandwichs, et tape avant que la fenêtre ne se referme.",facts:["fenêtre de tape 1,2 s","fausses tapes brûlent","~8 min"]},"quick-reflex":{name:"Réflexe éclair",tagline:"Fenêtres cruelles",description:"Les mêmes motifs classiques sur une gâchette ultra-sensible — la fenêtre de tape se referme en 0,7 seconde.",facts:["fenêtre de tape 0,7 s","pour les yeux affûtés","~6 min"]},slaphappy:{name:"Tapette folle",tagline:"Tous les motifs en jeu",description:"Mariages, dix, haut-bas et suites comptent en plus des classiques. Le chaos, chaleureusement éclairé, très bruyant.",facts:["tous les motifs","fenêtre de tape 0,8 s","~5 min"]}},fields:{doubles:{label:"Doubles"},sandwiches:{label:"Sandwichs"},marriage:{label:"Mariage (R+D)"},tens:{label:"Les cartes font dix"},topBottom:{label:"Haut-bas"},runs:{label:"Suites"},misSlapBurn:{label:"Fausse tape brûle une carte"},slapBackIn:{label:"Retour par la tape"},slapWindowMs:{label:"Fenêtre de tape"}},presets:{classic:"Tape classique","quick-reflex":"Réflexe éclair",slaphappy:"Tapette folle"}},euchre:{name:"Euchre",subtitle:"le jeu en équipe",tagline:"Fais des plis pour ton équipe",description:"Prends la carte retournée, nomme ton atout et cours après les volets avec le joueur d’en face. La première équipe à dix remporte la partie.",facts:["4 joueurs · 2v2","jeu de plis","solo ou entre amis"],howToPlay:{summary:"Le classique du Midwest — fais équipe, nomme l’atout et mène ton équipe à 10 points.",objective:"Assis face à ton partenaire, gagne au moins trois des cinq plis de chaque manche en faisant de ta couleur annoncée la reine de la table. La première équipe à atteindre le score cible remporte la partie.",sections:[{heading:"La table",body:["Quatre joueurs, deux équipes : toi et le joueur en face de toi êtes partenaires. Cinq cartes chacun ; les quatre dernières forment le talon, dont la carte du dessus est retournée face visible."]},{heading:"Prendre ou passer — premier tour d’annonce",body:["En commençant à la gauche du donneur, chacun prend la carte retournée ou passe :"],bullets:[{label:"Prendre",text:"cette couleur devient atout, le donneur ramasse la carte dans sa main et en écarte une face cachée"},{label:"Jouer seul",text:"prends l’atout et envoie ton partenaire sur le banc pour cette manche"},{label:"Passer",text:"la décision passe à gauche"}]},{heading:"Nommer l’atout — deuxième tour",body:["Si les quatre passent, la carte retournée est écartée et chaque place peut nommer n’importe quelle autre couleur comme atout. La couleur refusée est hors jeu.","Donneur pris au piège (par défaut) : si tout le monde passe au deuxième tour, le donneur doit annoncer une couleur."]},{heading:"Les volets",body:["Quand une couleur est nommée, son valet est le GROS volet — la carte la plus forte en jeu. Le valet de la couleur de même teinte est le PETIT volet, juste derrière le gros, et compte comme atout. Avec cœur atout, le V♥ puis le V♦ sont donc les deux cartes maîtresses."]},{heading:"Jouer les plis",body:["Le joueur à la gauche du donneur entame. Tu dois suivre la couleur entamée si tu peux — souviens-toi que le petit volet appartient à l’atout, pas à sa couleur imprimée. La carte la plus haute de la couleur entamée gagne le pli, sauf si quelqu’un coupe ; l’atout le plus haut bat tout. Le gagnant entame le pli suivant."]},{heading:"Compter une manche",body:["L’équipe qui a annoncé est l’équipe PRENEUSE. Après cinq plis :"],bullets:[{label:"3 ou 4 plis",text:"les preneurs marquent 1 point"},{label:"5 plis",text:"une razzia — les preneurs marquent 2"},{label:"Razzia en solo",text:"les cinq plis en jouant seul — les preneurs marquent 4"},{label:"Euchré !",text:"les preneurs font moins de trois plis — les défenseurs marquent 2"}]},{heading:"Jouer seul",body:["Un preneur assez confiant peut jouer sans son partenaire, qui reste complètement à l’écart de la manche. Gagne les cinq plis seul et ça vaut 4 points — mais fais-en moins de trois et la défense t’euchre quand même pour 2."]},{heading:"Règles maison",body:["Les réglages de la salle ajustent la partie : jeu en 5/10/15, donneur pris au piège ou non, et si l’on peut jouer seul. Quand toutes les mains sont jetées sans annonce d’atout, la donne passe simplement à gauche."]}]},modes:{classic:{name:"Pub classique",tagline:"Le vrai jeu",description:"Dix points, donneur pris au piège, jeu en solo. Le jeu tel qu’on y joue dans chaque caserne et à chaque table de cuisine.",facts:["partie à 10","donneur pris au piège","~20 min"]},"quick-cut":{name:"Coupe rapide",tagline:"Premier à cinq",description:"Mêmes règles, course plus courte — cinq points et c’est fini. Parfait pendant que la bouilloire chauffe encore.",facts:["partie à 5","~10 min"]},"long-game":{name:"Longue partie",tagline:"Installe-toi",description:"Quinze points pour une vraie soirée de jeu. Les rancunes sont les bienvenues.",facts:["partie à 15","~30 min"]},"old-school":{name:"À l’ancienne",tagline:"Le donneur peut passer",description:"Pas de donneur pris au piège — tout le monde peut passer et la donne tourne. Comme certains grands-pères l’exigent.",facts:["partie à 10","sans piège","~20 min"]}},fields:{targetScore:{label:"Partie à",help:"La première équipe à atteindre ce score remporte la partie.",group:"Partie",options:{5:"5 — coupe rapide",10:"10 — standard",15:"15 — longue partie"}},stickDealer:{label:"Donneur pris au piège",help:"Au deuxième tour d’annonce, le donneur doit nommer une couleur quand tout le monde a passé.",group:"Annonces"},goingAlone:{label:"Permettre de jouer seul",help:"Un preneur avec une main monstrueuse peut envoyer son partenaire sur le banc pour la manche.",group:"Annonces"}},presets:{classic:"Pub classique","quick-cut":"Coupe rapide","long-game":"Longue partie","old-school":"À l’ancienne"}},hearts:{name:"Cœurs",subtitle:"le jeu d’évitement",tagline:"Ne prends aucun cœur",description:"Esquive chaque cœur, fuis la Dame noire et fais porter les points à quelqu’un d’autre. Passes tournantes, choix secrets, une dame bien acérée.",facts:["4 joueurs","passe · pli · évite","solo ou entre amis"],howToPlay:{summary:"Le classique de l’évitement — ne prends aucun cœur, esquive la Dame noire et laisse un autre avaler les points.",objective:"Termine la partie avec le score le plus bas. Chaque cœur capturé coûte 1 point et la dame de pique en coûte 13 ; quand un joueur franchit le seuil de fin (100 par défaut), le total le plus bas gagne.",sections:[{heading:"La passe",body:["Avant chaque donne, tu choisis trois cartes et tu les glisses à un voisin — tout le monde choisit en secret, puis les quatre passes arrivent ensemble.","Le sens tourne à chaque donne : gauche, droite, en face, puis une donne sans passe du tout."]},{heading:"Jouer les plis",body:["Le deux de trèfle entame le premier pli. Suis la couleur si tu peux ; la carte la plus haute de la couleur entamée prend le pli et son vainqueur entame le suivant."],bullets:[{label:"Premier pli",text:"aucune carte à points ne peut y être jetée (option de la maison)"},{label:"Briser les cœurs",text:"on ne peut pas entamer cœur tant qu’aucun cœur n’a été défaussé sur un pli précédent — sauf si ta main n’est que des cœurs"},{label:"À sec",text:"plus rien dans la couleur entamée ? Jette ce que tu veux — c’est là que la dame tombe sur quelqu’un"}]},{heading:"Compter une donne",body:["Quand les treize plis sont joués, chaque cœur capturé vaut 1 point et la dame de pique en vaut 13."],bullets:[{label:"Valet de carreau",text:"règle de la maison optionnelle — il rapporte −10 à qui le capture"},{label:"Grand chelem",text:"capture les TREIZE cœurs plus la dame et tu marques zéro pendant que tous les autres prennent +26 — ou, avec l’autre règle de la maison, ton propre score baisse de 26"}]},{heading:"La partie",body:["Les donnes s’accumulent jusqu’à ce que quelqu’un franchisse la ligne de fin (50 / 75 / 100). Le total le plus bas remporte la partie ; les égalités partagent la couronne."]},{heading:"Règles de la maison",body:["Les paramètres de la salle règlent tout : sens de la passe, donnes sans passe, protection du premier pli, valet de carreau, seuil de fin et variante du grand chelem. Les tables classiques gardent les valeurs par défaut."]}]},modes:{classic:{name:"Classique",tagline:"À la lettre",description:"Passes tournantes gauche-droite-en face, une donne sans passe toutes les quatre, aucun point au premier pli. Partie en 100.",facts:["partie en 100","dones sans passe","~15 min"]},quickcut:{name:"Rapide",tagline:"Les mêmes cœurs, en plus vite",description:"Règles identiques, plafond plus bas — le premier joueur au-delà de 50 y met fin. Une partie entière le temps d’un café.",facts:["partie en 50","dones sans passe","~8 min"]},cutthroat:{name:"Sans pitié",tagline:"Le valet se balade",description:"Le valet de carreau rapporte −10 à qui l’attrape, et les cartes à points volent dès le premier pli. Personne n’est à l’abri.",facts:["J♦ −10","points dès le premier pli","partie en 100"]}},fields:{passDirection:{label:"Passe",options:{left:"Gauche",right:"Droite",across:"En face",hold:"Sans passe"}},holdHand:{label:"Donne sans passe toutes les quatre"},noPointsFirstTrick:{label:"Aucune carte à points au premier pli"},jackDiamonds:{label:"Le valet de carreau rapporte −10"},gameOver:{label:"Fin de partie à",options:{50:"50 points",75:"75 points",100:"100 points"}},moonShift:{label:"Grand chelem",options:{opponents:"+26 pour tous les autres",self:"−26 sur ton propre score"}}},presets:{classic:"Cœurs classique",quickcut:"Rapide",cutthroat:"Sans pitié"}},gin:{name:"Gin Rami",subtitle:"le classique du rami",tagline:"Combine, frappe, gagne la soirée",description:"Dix cartes, deux chaises. Forme des brelans et des suites, allège ton bois mort et frappe la table avant ton adversaire.",facts:["2 joueurs","frapper · gin · grand gin","solo ou entre amis"],howToPlay:{summary:"Le classique à deux — pioche, défausse et combine jusqu’à une main qui vaut le coup de frapper.",objective:"Transforme tes dix cartes en brelans et en suites pour qu’il ne reste presque rien, puis frappe avant ton adversaire. La première place à dépasser la cible de la partie gagne.",sections:[{heading:"Combinaisons et bois mort",body:["Une combinaison est soit trois ou quatre cartes de même rang, soit trois cartes ou plus de la même couleur en séquence. Les as sont toujours bas (A-2-3, jamais D-R-A).","Tout ce qui n’est pas dans une combinaison est du bois mort, compté à sa valeur faciale avec les figures à dix et les as à un. Plus c’est bas, mieux c’est."]},{heading:"Ton tour",body:["Deux étapes, à chaque tour :"],bullets:[{label:"Piocher",text:"prends le dessus du talon, ou rafle le dessus de la défausse"},{label:"Défausser",text:"glisse une carte face visible sur la pile — jamais une carte piochée ce tour-ci, d’une pile comme de l’autre"}]},{heading:"La carte retournée d’ouverture",body:["Après la donne, une carte reste face visible. Celui qui ne donne pas peut la prendre dans sa main, ou passer ; puis le donneur a le même choix. Si les deux passent, celui qui ne donne pas pioche dans le talon et le jeu commence."]},{heading:"Frapper",body:["Au lieu de te défausser, tu peux frapper dès que ton bois mort est au plafond de frappe ou en dessous (10 par défaut). Cela termine la manche immédiatement — sans défausse. Piocher d’abord une onzième carte ouvre la voie du grand gin si tout se combine."]},{heading:"Gin et décharges",body:["Zéro bois mort, c’est le gin — le défenseur ne peut rien décharger et paie tout son bois mort plus le bonus de gin.","Sur une frappe simple, le défenseur décharge d’abord : toutes ses cartes restantes qui allongent un brelan du frappeur à quatre ou prolongent une suite à l’un ou l’autre bout glissent hors des comptes avant la comparaison.","Si le bois mort du défenseur finit égal ou inférieur au tien, c’est une contre-frappe — c’est lui qui empoche la différence plus un bonus."]},{heading:"Score et partie",body:["Les manches s’enchaînent jusqu’à ce que quelqu’un dépasse la cible de la partie (100 par défaut), la donne alternant à chaque manche."],bullets:[{label:"Frappe",text:"la différence entre les bois morts"},{label:"Contre-frappe",text:"différence + 25 pour le défenseur"},{label:"Gin",text:"tout le bois mort du défenseur + 25"},{label:"Grand gin",text:"onze cartes toutes combinées — bois mort du défenseur + 31 (option)"},{label:"Bonus de ligne",text:"+25 optionnel par manche gagnée, ajouté à la fin (option)"}]},{heading:"Règles maison",body:["Chaque table peut être réglée dans les paramètres de la salle :"],bullets:[{label:"Plafond de frappe",text:"à quel point tu dois être bas pour frapper — des plafonds plus serrés font des manches plus longues"},{label:"Cible de la partie",text:"50 pour une partie rapide, 100 en classique, plus pour les acharnés"},{label:"Grand gin / bonus / bonus de ligne",text:"les réglages de gains"}]},{heading:"Manches mortes",body:["Si le talon tombe à deux cartes, la manche est morte — pas de score, le donneur redonne. Frappe plus tôt."]}]},modes:{classic:{name:"Classique",tagline:"Direct vers les 100",description:"Le standard du pub — frappe à dix de bois mort ou mieux, le gin paie 25, le grand gin paie 31. Le premier à passer 100 l’emporte.",facts:["plafond de frappe 10","partie à 100","~15 min"]},quick:{name:"Rapide",tagline:"Course à 50",description:"Mêmes règles, échelle plus courte. Une partie à deux rapide le temps que la bouilloire chauffe.",facts:["partie à 50","~8 min"]},purist:{name:"Puriste",tagline:"Sans fioritures",description:"Le grand gin est désactivé et les bonus de ligne restent à la maison. Que des frappes, que du bois mort, aucun filet de sécurité.",facts:["sans grand gin","sans bonus de ligne"]}},fields:{knockCap:{label:"Plafond de frappe",help:"Le bois mort le plus haut avec lequel tu peux frapper",group:"Table"},matchTarget:{label:"Partie à",help:"La première place à dépasser ce total remporte la partie",group:"Table"},ginBonus:{label:"Bonus de gin",group:"Bonus"},bigGin:{label:"Grand gin",help:"Pioche une onzième carte qui se combine entièrement",group:"Bonus"},bigGinBonus:{label:"Bonus de grand gin",group:"Bonus"},boxBonus:{label:"Bonus de ligne",help:"+25 par manche gagnée, ajouté au total final",group:"Bonus"}},presets:{classic:"Classique",quick:"Partie rapide",purist:"Puriste"}},president:{name:"Président",subtitle:"le jeu d’ascension",tagline:"Grimpe jusqu’à la couronne",description:"Couvre le tas avec un jeu plus fort, débarrasse-toi de ta main en premier, et monte de Trouduc à Président. Jusqu’à huit places, couronnes et humiliations incluses.",facts:["4–8 joueurs","rôles et échanges","solo ou entre amis"],howToPlay:{summary:"Le grand jeu d’ascension — débarrasse-toi de ta main en premier, grimpe l’échelle de Trouduc à Président, et fais servir les cartes par tes rivaux.",objective:"Termine chaque donne à la meilleure place possible. Le premier sortant est Président, le dernier est Trouduc. Les points de position s’accumulent d’une donne à l’autre ; le premier au total cible gagne la partie.",sections:[{heading:"Jouer sur le tas",body:["Le joueur qui entame ouvre le pli avec n’importe quel jeu — une carte seule, une paire, un brelan ou un carré d’un même rang.","Dans le sens horaire, chacun doit couvrir le tas avec le MÊME nombre de cartes d’un rang strictement supérieur, ou passer."],bullets:[{label:"Ordre des rangs",text:"le 3 est le plus faible, on monte jusqu’à l’as, et le 2 trône au-dessus de tout"},{label:"Passer",text:"passer ne saute que ce tour-là — si quelqu’un couvre le tas plus tard dans le pli, tu reviens en jeu (sauf si la règle du passe définitif est active)"},{label:"Remporter le pli",text:"quand tout le monde a passé, le tas est balayé et le vainqueur entame ce qu’il veut"},{label:"Un 2 dégage",text:"un 2 seul remporte le tas sur-le-champ et garde l’entame — règle de la maison, active par défaut"}]},{heading:"Finir une donne",body:["À court de cartes, tu verrouilles la prochaine place sur l’échelle. Le jeu continue jusqu’à ce qu’il ne reste qu’un joueur avec des cartes en main — le Trouduc.","Le premier sortant est Président, le deuxième Vice-Président, l’avant-dernier Vice-Trouduc, et la dernière place est Trouduc."]},{heading:"Les points et la partie",body:["Chaque donne rapporte des points de position : le Président marque autant de points qu’il y a de places, le suivant un de moins, jusqu’à un seul point pour le Trouduc.","La partie s’arrête dès que quelqu’un atteint la cible — le plus haut total gagne, les ex æquo partagent la couronne."]},{heading:"L’échange",body:["Avant la donne suivante, les places basses paient tribut depuis leurs nouvelles mains et les places hautes renvoient ce qu’elles veulent :"],bullets:[{label:"Trouduc → Président",text:"les deux meilleures cartes du Trouduc ; le Président en renvoie deux au choix"},{label:"Vice-Trouduc → Vice-Président",text:"une carte dans chaque sens"},{label:"Option désactivée",text:"désactive l’échange dans les réglages de la salle pour un chacun-pour-soi plus pur"}]},{heading:"Règles de la maison",body:["Règle la table dans les paramètres de la salle avant de commencer :"],bullets:[{label:"Un 2 dégage le tas",text:"actif par défaut — désactivé, un 2 est juste une carte imbattable de plus"},{label:"Passes définitives",text:"une fois passé, tu restes hors du pli jusqu’au bout (désactivé par défaut : tu reviens quand le tas change)"},{label:"Échange",text:"l’échange de cartes par rôles entre les donnes"},{label:"Points cibles",text:"la taille de la partie — 7 pour un sprint, 11 pour une session, 21 pour un marathon"}]},{heading:"Savoir-vivre à table",body:["La première donne commence à la place de départ ; ensuite, le Président en place entame chaque donne.","Les cartes sont distribuées une à une jusqu’à épuisement du talon, donc les tables impaires laissent certaines places à une carte de moins — tout le monde est dans le même bateau."]}]},modes:{classic:{name:"Classique",tagline:"L’échelle complète",description:"Couronnes, tributs et revanche — le premier à onze points remporte le salon. Comme on y joue au pub.",facts:["le premier à 11","échange activé","le 2 dégage"]},rapid:{name:"Rapide",tagline:"Court et relevé",description:"Le premier à sept fait tourner la table. Mêmes règles, moins de donnes, revanches plus bruyantes.",facts:["le premier à 7","~10 min","génial à 6+"]},marathon:{name:"Marathon",tagline:"Longs règnes",description:"Vingt-et-un points de politique. Les Trouducs deviennent Présidents, les dynasties naissent et tombent.",facts:["le premier à 21","longue session","arc complet"]}},fields:{twoClears:{label:"Un 2 dégage le tas"},passLocks:{label:"Passer t’exclut du pli"},trading:{label:"Échange de cartes par rôles entre les donnes"},targetPoints:{label:"Le premier à (points)"}},presets:{classic:"Salon classique",rapid:"Cabinet rapide",marathon:"Marathon"}},spades:{name:"Piques",subtitle:"le jeu en équipe",tagline:"Annonce tes plis",description:"Assieds-toi face à ton partenaire, annonce un nombre et fais autant de plis — ni plus, ni moins si tu peux l’éviter. Les piques sont toujours atout. Les sacs te retrouveront.",facts:["4 joueurs · 2v2","annonce · atout · sacs","solo ou entre amis"],howToPlay:{summary:"Le classique américain en équipe — annonce tes plis, brise les piques et fonce vers les 500.",objective:"Assis face à ton partenaire, fais au moins autant de plis que vous en avez annoncés à deux. La première équipe à atteindre le score cible (500 par défaut) gagne ; en cas d’égalité sur la ligne ou au-dessus, on joue une manche de plus.",sections:[{heading:"La table",body:["Quatre joueurs, deux équipes : toi et le joueur en face de toi êtes partenaires. Chaque manche distribue tout le jeu de 52 cartes — treize cartes chacun. La donne comme la première annonce commencent à la gauche du donneur et tournent dans le sens des aiguilles d’une montre."]},{heading:"Les annonces",body:["Chaque place annonce un nombre, une seule fois. On ne passe pas et on ne surenchérit pas. Le contrat de ton équipe est la somme des deux annonces qui ne sont pas capot."],bullets:[{label:"1–13",text:"combien de plis tu penses faire"},{label:"Capot",text:"une annonce à part — ne fais aucun pli pour +100, ou −100 si tu en fais un. Les plis d’un capot raté n’aident pas ton partenaire à remplir son contrat, mais chacun compte quand même comme un sac"}]},{heading:"Jouer les plis",body:["Le joueur à la gauche du donneur entame le premier pli. Suis la couleur si tu peux ; le pique le plus haut l’emporte, sinon la carte la plus haute de la couleur entamée. Celui qui gagne le pli entame le suivant."],bullets:[{label:"Briser les piques",text:"on ne peut pas entamer un pique tant que personne n’en a défaussé un en étant à sec de la couleur — sauf s’il ne te reste que des piques en main"},{label:"À sec",text:"plus de la couleur entamée ? Joue ce que tu veux, y compris un atout"}]},{heading:"Compter une manche",body:["Si les places de l’équipe qui n’ont pas annoncé capot font au moins le contrat, l’équipe marque 10 points par pli annoncé plus 1 par pli supplémentaire. Si vous tombez à court, le contrat coûte −10 par pli annoncé."],bullets:[{label:"Sacs",text:"les plis supplémentaires (et les plis d’un capot raté) sont des sacs. Ils s’accumulent de manche en manche ; chaque dizaine de sacs coûte 100 points et les sacs restants restent au compteur"},{label:"Capot",text:"compté à part, en plus du résultat du contrat du partenaire"}]},{heading:"La partie",body:["Les manches s’enchaînent jusqu’à ce qu’une équipe atteigne la cible (250 / 500 / 750). Le score le plus haut gagne ; si les deux équipes arrivent au même total sur la ligne ou au-dessus, on redonne."]},{heading:"Règles maison",body:["Les réglages de la salle ne touchent que trois choses : le score cible, si le capot est permis et si les sacs comptent. Les tables classiques gardent les valeurs par défaut. Le capot à l’aveugle n’est pas proposé."]}]},modes:{classic:{name:"Classique",tagline:"Dans les règles",description:"Piques en équipe jusqu’à 500, capot activé, sacs activés. Le jeu tel qu’on y joue à toutes les tables de cuisine.",facts:["partie à 500","capot · sacs","~25 min"]},quick:{name:"Rapide",tagline:"Premier à 250",description:"Mêmes règles, course plus courte — 250 points et c’est fini. Une partie entière le temps d’une pause déjeuner.",facts:["partie à 250","capot · sacs","~12 min"]},"clean-books":{name:"Plis propres",tagline:"Sans sacs",description:"Remplis ton annonce ou échoue — les plis supplémentaires ne sont pas des sacs et ne rapportent rien. La précision avant le remplissage.",facts:["partie à 500","capot activé","sacs désactivés"]}},fields:{targetScore:{label:"Partie à",help:"Après chaque manche, l’équipe la plus haute sur la ligne ou au-dessus de ce score gagne. En cas d’égalité, on joue une manche de plus.",group:"Partie",options:{250:"250 — coupe rapide",500:"500 — standard",750:"750 — longue partie"}},nil:{label:"Permettre le capot",help:"Une annonce de zéro est un capot : ne fais aucun pli pour +100, ou −100 si tu en fais un. Les plis d’un capot raté n’aident pas le contrat du partenaire.",group:"Annonces"},bags:{label:"Compter les sacs",help:"Les plis supplémentaires et les plis d’un capot raté sont des sacs. Chaque dizaine de sacs coûte 100 points ; les sacs restants restent au compteur.",group:"Score"}},presets:{classic:"Classique",quick:"Rapide","clean-books":"Plis propres"}},poker:{name:"Poker",subtitle:"hold’em sans limite",tagline:"Le dernier tapis gagne",description:"Deux cartes rien que pour toi, cinq au milieu, et tous tes jetons pour dire à quel point tu y crois. Les blinds montent jusqu’à ce qu’un joueur ait tout.",facts:["2–6 joueurs","hold’em sans limite","jetons fictifs"],howToPlay:{summary:"Le Texas hold’em sans limite, en sit-and-go — tout le monde part à égalité, les blinds montent, et le dernier tapis gagne.",objective:"Gagne tous les jetons. À chaque main, tu reçois deux cartes rien qu’à toi et tu partages cinq cartes au milieu ; la meilleure main de cinq cartes remporte le pot, et quiconque n’a plus de jetons est éliminé de la partie.",sections:[{heading:"Les jetons",body:["Les jetons servent à compter, pas à miser — il n’y a rien à acheter et rien à encaisser. Tout le monde commence avec le même tapis, et la partie s’arrête quand un joueur a tout."]},{heading:"Une main",body:["Deux cartes faces cachées à chaque place, puis un tour de mises. Trois cartes communes (le flop), un tour. Une quatrième (le turn), un tour. Une cinquième (la river), un dernier tour. Ceux qui restent montrent leurs cartes, et les cinq meilleures parmi les sept disponibles gagnent."],bullets:[{label:"Le bouton",text:"marque le donneur et avance d’une place vers la gauche à chaque main"},{label:"Blinds",text:"les deux places à gauche du bouton mettent des jetons avant la donne, pour qu’il y ait toujours quelque chose à gagner"}]},{heading:"À toi de jouer",body:["Quand l’action arrive à toi, il n’y a jamais que quatre choses possibles."],bullets:[{label:"Se coucher",text:"abandonner la main et ce que tu as déjà misé"},{label:"Parole",text:"rester sans miser — seulement quand tu ne dois rien"},{label:"Suivre",text:"égaler la mise en cours"},{label:"Miser / relancer",text:"mettre plus, que tous les autres doivent égaler pour rester. Une relance vaut au moins la taille de la précédente — sauf si tu mises tout ce qu’il te reste"}]},{heading:"Tapis",body:["Tu ne peux jamais perdre plus que ce que tu as devant toi. Miser ton dernier jeton, c’est faire tapis : tu restes dans la main jusqu’au bout, et toute mise plus grosse que ton tapis alimente un pot annexe que tu ne peux ni gagner ni perdre."]},{heading:"Valeur des mains",body:["De la plus forte à la plus faible. Les égalités se départagent à la carte suivante la plus haute, et une vraie égalité partage le pot."],bullets:[{label:"Quinte flush",text:"cinq cartes qui se suivent, même couleur — à l’as, c’est une quinte flush royale"},{label:"Carré",text:"les quatre cartes d’une même hauteur"},{label:"Full",text:"trois cartes d’une hauteur et deux d’une autre"},{label:"Couleur",text:"cinq cartes de la même couleur"},{label:"Quinte",text:"cinq cartes qui se suivent — l’as compte haut ou bas"},{label:"Brelan",text:"trois cartes d’une même hauteur"},{label:"Double paire",text:"deux cartes d’une hauteur et deux d’une autre"},{label:"Paire",text:"deux cartes d’une même hauteur"},{label:"Carte haute",text:"rien de tout ça"}]},{heading:"La partie",body:["Les blinds montent selon un calendrier, donc se coucher sans fin n’est pas un plan — une partie finit toujours. Saute et tu es éliminé ; le dernier joueur avec des jetons gagne, et les autres se classent dans l’ordre de leur sortie."]},{heading:"Règles de la maison",body:["Les réglages de la salle choisissent le tapis de départ, la vitesse de montée des blinds, si la grosse blind paie une ante pour toute la table à partir du troisième niveau, et si les mains battues sont retournées à l’abattage ou jetées faces cachées."]}]},modes:{classic:{name:"Classique",tagline:"La table au complet",description:"Trois mille jetons chacun et des blinds qui montent toutes les huit mains. De la place pour jouer une main à fond avant d’être engagé.",facts:["3 000 jetons","blinds toutes les 8","~25 min"]},turbo:{name:"Turbo",tagline:"Tapis ou rien",description:"Petits tapis et blinds qui doublent toutes les quatre mains. Personne n’a le temps d’attendre les as.",facts:["1 500 jetons","blinds toutes les 4","~10 min"]},deep:{name:"Deep Stack",tagline:"Joue le joueur",description:"Six mille jetons et une montée lente, sans ante. Le jeu long, où la position et la patience paient.",facts:["6 000 jetons","blinds toutes les 12","sans ante"]}},fields:{startingStack:{label:"Tapis de départ",help:"Les jetons que chaque place reçoit au départ. Des tapis plus profonds laissent plus de jeu après le flop avant d’être engagé.",group:"Partie",options:{1500:"1 500 — court",3e3:"3 000 — standard",6e3:"6 000 — profond"}},blindSpeed:{label:"Montée des blinds",help:"Les blinds montent selon un calendrier pour qu’une partie finisse toujours. Turbo force l’action tôt.",group:"Partie",options:{slow:"Lente — toutes les 12 mains",standard:"Standard — toutes les 8 mains",turbo:"Turbo — toutes les 4 mains"}},ante:{label:"Ante de table",help:"À partir du troisième niveau, la grosse blind paie une blind de plus pour toute la table, pour qu’il y ait toujours quelque chose à prendre.",group:"Mises"},showMucked:{label:"Montrer les mains perdantes",help:"Désactivé, une main battue est jetée faces cachées comme à une vraie table. Activé, tout le monde voit chaque main arrivée jusqu’à la river.",group:"Abattage"}},presets:{classic:"Classique",turbo:"Turbo",deep:"Deep Stack"}},ohhell:{name:"Oh Hell",subtitle:"le jeu d’annonces",tagline:"Annonce tes plis. Fais exactement ça.",description:"Les mains grandissent puis rétrécissent à chaque manche pendant que tu annonces le nombre exact de plis que tu feras. La règle du croc garantit que quelqu’un se trompe — fais en sorte que ce ne soit pas toi.",facts:["3–7 joueurs","annonce · atout · exact","solo ou entre amis"],howToPlay:{summary:"Annonce le nombre exact de plis que tu feras — ni plus, ni moins. Les mains grandissent puis rétrécissent à chaque manche jusqu’à ce que quelqu’un surclasse la table.",objective:"Sur une partie de mains qui grandissent puis rétrécissent, marque plus que tout le monde en réussissant ton annonce au pli près. Un joueur est mathématiquement condamné à chaque manche — fais en sorte que ce ne soit pas toi.",sections:[{heading:"La table",body:["De trois à sept joueurs, chacun pour soi. Une partie est une suite de manches : la première distribue une carte chacun, puis les mains grandissent jusqu’à un sommet (plafonné pour qu’il reste toujours une carte pour l’atout) et redescendent jusqu’à une. La donne tourne dans le sens horaire à chaque manche."]},{heading:"La retourne",body:["Après la donne, la carte suivante du talon est retournée face visible — sa couleur est l’atout de la manche."],bullets:[{label:"Plus de carte",text:"quand la donne a épuisé tout le paquet, il n’y a rien à retourner et la manche se joue sans atout"},{label:"Atout coupé",text:"les tables avec « atout coupé » réduisent plutôt la manche à paquet entier d’une carte, pour pouvoir couper un atout au fond du paquet"}]},{heading:"Les annonces",body:["En partant de la gauche du donneur et dans le sens horaire, chaque place annonce un nombre de 0 à la taille de sa main : exactement combien de plis elle prétend faire. Pas de passe, pas de seconde chance."],bullets:[{label:"La règle du croc",text:"le donneur annonce EN DERNIER et ne peut pas faire en sorte que le total des annonces égale les plis disponibles — un joueur à cette table est forcément à côté. L’annonce interdite n’apparaît tout simplement pas sur ton cadran"},{label:"Zéro",text:"une annonce comme une autre : ne faire aucun pli"}]},{heading:"Jouer les plis",body:["Le joueur à gauche du donneur entame le premier pli. Fournis la couleur si tu peux ; l’atout le plus haut gagne, sinon la carte la plus haute de la couleur entamée. Celui qui prend le pli entame le suivant."]},{heading:"Marquer une manche",body:["Réussis ton annonce EXACTEMENT ou ne marque rien (par défaut). Le score de manche de chaque place s’ajoute à son total ; après la dernière manche de l’arc, le total le plus haut gagne."],bullets:[{label:"Exact seulement",text:"une annonce réussie marque 10 + l’annonce ; tout le reste marque 0"},{label:"Pénalité",text:"une annonce réussie marque 10 + l’annonce ; rater coûte moins l’écart de ton erreur"},{label:"Plus un",text:"une annonce réussie marque le double de l’annonce ; tout le reste marque 0"}]},{heading:"Variante Wizard",body:["Avec Sorciers et Bouffons activés, quatre Sorciers et quatre Bouffons rejoignent le paquet (60 cartes) et bousculent l’ordre habituel des choses."],bullets:[{label:"Sorcier",text:"bat tout ; le PREMIER Sorcier joué prend le pli. En entamer un laisse le pli sans couleur entamée — chacun peut jouer ce qu’il veut"},{label:"Bouffon",text:"perd contre tout ; si toutes les cartes d’un pli sont des Bouffons, le premier gagne. En entamer un renvoie la couleur entamée à la prochaine vraie carte"},{label:"Retourne d’atout",text:"un Sorcier retourné laisse le DONNEUR choisir l’atout ; un Bouffon retourné signifie une manche sans atout"}]}]},modes:{classic:{name:"Classique",tagline:"Monte et redescends",description:"L’arc classique — une carte, en grandissant jusqu’au sommet, puis retour à une. Règle du croc activée, annonces exactes seulement. Quelqu’un se trompe à chaque manche ; pas toi, avec un peu de chance.",facts:["mains 1…sommet…1","règle du croc","~20 min"]},quick:{name:"Rapide",tagline:"Donne large, rétrécis vite",description:"On commence à cinq cartes et on descend directement jusqu’à une. Une partie entière en dix minutes, que du nerf et pas de gras.",facts:["mains 5→1","~10 min"]},wizard:{name:"Wizard",tagline:"Soixante cartes, quatre certitudes",description:"Quatre Sorciers gagnent toujours et quatre Bouffons jamais. La couleur entamée se plie autour d’eux et le donneur choisit parfois l’atout. Le chaos, formalisé.",facts:["paquet de 60 cartes","sorciers activés"]}},fields:{handSize:{label:"Cartes en main",help:"Cartes distribuées à chaque joueur pour cette manche. Une partie complète règle ça automatiquement à chaque manche.",group:"Partie"},dealer:{label:"Place du donneur",help:"La place qui donne cette manche et annonce en dernier. Une partie complète fait tourner la donne à chaque manche.",group:"Partie"},handArc:{label:"Arc des mains",help:"Comment les tailles de main évoluent sur une partie : montée puis descente, montée seule, ou donne large puis rétrécis.",group:"Partie",options:{updown:"Monte et redescends — 1…sommet…1",up:"Montée seule — 1…sommet",down:"Descente seule — sommet…1"}},maxHand:{label:"Main la plus grande",help:"L’arc ne distribue jamais plus que ça — plafonné pour que chaque manche garde une carte à retourner pour l’atout.",group:"Partie"},hookRule:{label:"Règle du croc",help:"Piège le donneur : la dernière annonce ne peut pas rendre le total exactement égal aux plis disponibles, donc quelqu’un se trompe toujours.",group:"Annonces"},scoring:{label:"Score",help:"Réussis ton annonce au pli près pour marquer. Les modes diffèrent sur ce que coûte un échec.",group:"Score",options:{exactOnly:"Exact seulement — 10 + l’annonce ou rien",penalty:"Pénalité — rate de n, perds n",plusOne:"Plus un — double l’annonce en cas de réussite"}},wizards:{label:"Sorciers et Bouffons",help:"Ajoute quatre Sorciers (gagnent toujours) et quatre Bouffons (perdent toujours) — un paquet de 60 cartes.",group:"Avancé"},trumpOnLastRound:{label:"Atout coupé sur les manches à paquet entier",help:"Quand une manche distribuerait tout le paquet, coupe d’abord un atout au fond (les mains rétrécissent d’une carte) au lieu de jouer sans atout.",group:"Avancé"}},presets:{classic:"Classique",quick:"Rapide",wizard:"Wizard"}},scopa:{name:"Scopa",subtitle:"le jeu de pêche",tagline:"Balaye la table",description:"Capture les cartes de la table par paire ou par somme, thésaurise les deniers dorés et chasse le settebello. Vide toute la table et crie scopa — le plus beau mot des cafés italiens.",facts:["2–6 joueurs","capture · sommes","solo ou entre amis"],howToPlay:{summary:"Le classique italien de la pêche — capture les cartes de la table, et balaie-la entièrement pour une scopa.",objective:"Capture les cartes de la table en égalant ou en additionnant leurs valeurs. Le plus de cartes, le plus de deniers, le settebello, la primiera et chaque scopa valent un point ; le premier à l’objectif (11 par défaut) gagne la partie.",sections:[{heading:"La table",body:["La scopa se joue avec un paquet italien de 40 cartes : Denari (deniers), Coppe (coupes), Spade (épées) et Bastoni (bâtons), hauteurs de 1 à 10. On peut jouer à deux, trois, quatre ou six — à quatre et à six, on joue en équipes fixes, les places alternant autour de la table.","Chaque donne distribue trois cartes à chaque joueur et en pose quatre faces visibles sur la table. Si trois Rois ou plus apparaissent sur le tapis de départ, on rebat et on redonne."]},{heading:"Capturer",body:["À ton tour, joue exactement une carte de ta main. Les captures se font au nombre uniquement — la couleur ne compte jamais."],bullets:[{label:"Paire",text:"ta carte prend une seule carte de la table de même valeur : un 5 prend un 5"},{label:"Choix",text:"si deux cartes de la table partagent cette valeur, tu choisis laquelle prendre — choisis bien, ce qui reste compte"},{label:"Somme",text:"ta carte peut prendre deux cartes de la table ou plus dont la somme égale sa valeur : un 8 prend un 3 et un 5. Mais si une paire à une carte existe, tu DOIS la prendre — les combinaisons ne servent que quand aucune paire ne se montre"},{label:"Pose",text:"rien ne correspond ? Ta carte reste sur la table, face visible et à la merci de tous"}]},{heading:"Scopa",body:["Balaye toutes les cartes restantes de la table en une seule capture et tu as fait une scopa : un point, marqué aussitôt. Une scopa sur la toute dernière carte de la dernière donne ne compte pas — ces cartes sont balayées de toute façon. Quand les mains se vident, trois nouvelles cartes sont distribuées à chacun ; la table n’est jamais réapprovisionnée. Quand le paquet est épuisé, le dernier joueur à avoir capturé balaie les cartes restantes, et ce balayage n’est pas une scopa."]},{heading:"Marquer une manche",body:["Après la dernière donne, quatre points sont répartis, plus toutes les scope gagnées en route. Aux tables en équipes, les captures des partenaires sont mises en commun avant le décompte."],bullets:[{label:"Carte",text:"le plus de cartes capturées — 21 ou plus sur les 40 à deux joueurs ; en cas d’égalité, personne ne marque"},{label:"Denari",text:"le plus de deniers capturés — 6 ou plus sur les 10 ; en cas d’égalité, personne ne marque"},{label:"Settebello",text:"celui qui a capturé le beau 7 de deniers marque 1, toujours"},{label:"Primiera",text:"la meilleure carte de chaque couleur, additionnées — le 7 vaut 21, le 6 vaut 18, l’As 16, le 5→15, le 4→14, le 3→13, le 2→12, et les figures seulement 10. Sans carte d’une couleur, tu ne peux pas la gagner. Le total le plus haut prend 1 point ; en cas d’égalité, personne ne marque"},{label:"Scope",text:"un point chacune, déjà empochées pendant le jeu"}]},{heading:"La partie",body:["Les manches s’enchaînent — le donneur avance vers la gauche à chaque fois — jusqu’à ce que quelqu’un franchisse le score cible. Si deux camps arrivent à égalité sur la ligne, une manche de plus les départage."]},{heading:"Règles de la maison",body:["Les réglages de la salle exposent les boutons classiques : l’objectif (11/16/21), le Scopone (tout le paquet distribué, pas de talon), la Napola (un bonus de série de deniers), le Re di denari (un bonus pour le Roi de deniers) et l’affichage aux couleurs françaises, qui est purement visuel."]}]},modes:{classic:{name:"Classique",tagline:"Premier à 11",description:"La scopa comme dans tous les bars d’Italie : trois cartes à la fois, quatre points par manche, premier à onze.",facts:["partie en 11","donnes de 3 cartes","~20 min"]},lungo:{name:"Lungo",tagline:"Le jeu long",description:"Mêmes règles, course jusqu’à vingt et un. De la place pour les remontées, les rancunes et les scope légendaires.",facts:["partie en 21","donnes de 3 cartes","~40 min"]},scopone:{name:"Scopone",tagline:"Tout le paquet, sans pitié",description:"Le quatre-joueurs à l’ancienne : dix cartes chacun distribuées d’un coup, pas de talon, rien de caché. Chaque capture est un engagement.",facts:["4 joueurs · 2v2","tout le paquet","~30 min"]}},fields:{target:{label:"Partie en",help:"Après chaque manche, le score le plus haut au niveau de cette ligne ou au-dessus gagne. Une égalité sur la ligne donne une manche de plus.",group:"Partie",options:{11:"11 — classique",16:"16 — long",21:"21 — lungo"}},scopone:{label:"Scopone",help:"Le quatre-joueurs à l’ancienne : tout le paquet est distribué d’un coup et il n’y a pas de talon où piocher. Les captures deviennent bien plus serrées.",group:"Donne"},napola:{label:"Napola",help:"Tiens l’As, le 2 et le 3 de deniers pour 3 points bonus, plus 1 de plus pour chaque carte de deniers qui prolonge la série (4, 5, …).",group:"Score"},reDenari:{label:"Re di denari",help:"Un point bonus pour celui qui capture le Roi de deniers.",group:"Score"},frenchSuits:{label:"Affichage aux couleurs françaises",help:"Affiche deniers/coupes/épées comme carreaux/cœurs/piques pour que les illustrations classiques passent. Purement visuel — les identifiants et les règles restent italiens.",group:"Table"}},presets:{classic:"Classique",lungo:"Lungo","scopone-preset":"Scopone"}},spite:{name:"Spite & Malice",subtitle:"la course à la pile gagnante",tagline:"Rends-leur la monnaie de leur carte",description:"Monte les piles du centre du 1 au 12, vide ta pile gagnante et ruine les plans des autres avec des jokers bien placés. Le nom du jeu, c’est la règle.",facts:["2–4 joueurs","classique · rapide · sans pitié","solo ou entre amis"],howToPlay:{summary:"Spite & Malice — monte les piles communes du centre du 1 au 12 et vide ta pile gagnante avant tout le monde.",objective:"Sois le premier joueur à vider ta pile gagnante. Chaque carte que tu y laisses enfermée, c’est un autre joueur qui s’en réjouira.",sections:[{heading:"La table",body:["Quatre sortes de cartes, quatre endroits où les poser :"],bullets:[{label:"Pile gagnante",text:"ta pile d’objectif, face cachée ; la carte du dessus est face visible"},{label:"Main",text:"cinq cartes, complétées à cinq au début de ton tour"},{label:"Piles de défausse",text:"quatre piles personnelles — finir ton tour, c’est te défausser sur l’une d’elles"},{label:"Piles du centre",text:"jusqu’à quatre constructions communes sur lesquelles tout le monde joue"}]},{heading:"Ton tour",body:["D’abord, pioche pour revenir à cinq cartes. Ensuite, fais autant de coups que tu veux, dans l’ordre que tu veux :","joue sur une pile du centre, joue le dessus de ta pile gagnante, ou joue le dessus de l’une de tes piles de défausse.","Ton tour ne se termine que lorsque tu te défausses d’une carte de ta main sur l’une de tes piles de défausse."]},{heading:"Construire",body:["Une pile du centre commence par un As et monte rang par rang jusqu’à la Dame. La couleur n’a aucune importance.","Termine une pile à la Dame et elle repart entièrement dans le talon — la pile repart à zéro, en attendant un As ou un joker."]},{heading:"Les jokers",bullets:[{label:"Jokers",text:"dix-huit dans le jeu — joue-en un comme n’importe quel rang, et ce rang est mémorisé pour la pile"},{label:"Rangs mémorisés",text:"un joker qui tient lieu de 6 fait de la carte suivante un 7, peu importe qui la joue"}]},{heading:"La pile gagnante",body:["Jouer le dessus de ta pile gagnante retourne aussitôt la carte suivante face visible — et si c’était ta dernière, tu gagnes sur-le-champ, en plein tour, sans défausse.","Coincé sans rien à jouer ? Défausse-toi à bon escient : ce que tu mets de côté maintenant, c’est un coup que tu débloqueras plus tard."]},{heading:"Talon à sec",body:["Les piles terminées repartent directement dans le talon, donc le paquet continue de circuler.","Si le talon est à sec au début de ton tour, toutes les piles du centre à moitié montées y retournent aussi — on redemande un As et les cartes enterrées sortent de leur tombe.","Et si la table se bloque complètement, c’est la pile gagnante la plus proche du vide qui l’emporte plutôt que de laisser tout le monde poireauter."]},{heading:"Façons de jouer",bullets:[{label:"Classique",text:"la grande course avec 20 cartes dans la pile gagnante — prévois le goûter"},{label:"Rapide",text:"une pile gagnante de 10 cartes pour une vengeance éclair"},{label:"Sans pitié",text:"13 cartes dans la pile gagnante et pas de pioche en cours de tour : vide ta main trop tôt et tu joueras à découvert"}]}]},modes:{classic:{name:"Classique",tagline:"La grande course",description:"Vingt cartes enterrées dans chaque pile gagnante et tous les jokers du paquet. Le jeu tel qu’il mérite d’être savouré.",facts:["pile gagnante de 20","rois et jokers sauvages","~15 min"]},quick:{name:"Rapide",tagline:"Rancune courte",description:"Des piles gagnantes de dix cartes, tout le reste intact — mêmes jokers, même malice, moitié moins d’attente avant ta revanche.",facts:["pile gagnante de 10","tous les jokers","~5–8 min"]},cutthroat:{name:"Sans pitié",tagline:"Ni merci, ni pioche",description:"Treize cartes à vider et aucune pioche en cours de tour : vide ta main au mauvais moment et tu joueras à découvert pendant qu’un autre gagne.",facts:["pile gagnante de 13","pas de pioche en cours de tour","impitoyable"]}},fields:{payoffSize:{label:"Pile gagnante",help:"Cartes enterrées dans chaque pile gagnante. Vide la tienne pour gagner — les petits chiffres font des parties plus courtes.",group:"La donne"},handSize:{label:"Cartes distribuées",help:"Taille de la main, complétée au début de chaque tour.",group:"La donne"},discardPiles:{label:"Piles de défausse",help:"Piles devant chaque joueur. Finir un tour, c’est se défausser sur l’une d’elles.",group:"La donne"},wilds:{label:"Jokers dans le jeu",help:"Un joker tient lieu du rang que tu annonces. Dix-huit, c’est le jeu de la boîte ; moins, et chacun devient précieux.",group:"Jokers"},buildPiles:{label:"Piles du centre",help:"Piles communes sur lesquelles tout le monde joue. Moins il y en a, plus tu attends le 1 d’un autre.",group:"Le centre"},refillMidTurn:{label:"Pioche en cours de tour",help:"Vide ta main et elle se complète aussitôt à cinq pour continuer. Désactivé, c’est sans pitié.",group:"Règles de la maison"}},presets:{classic:"Classique",quick:"Rapide",cutthroat:"Sans pitié"}},klondike:{name:"Klondike",subtitle:"le grand classique du solitaire",tagline:"Vide la table du jour",description:"Monte sept colonnes en alternant les couleurs, tourne le talon et renvoie chaque couleur à la maison, de l’As au Roi. La même donne du jour attend tout le monde.",facts:["1 joueur","donne du jour à graine","hors ligne"],howToPlay:{summary:"Le grand classique du solitaire à sept colonnes, distribué de façon déterministe pour une table neuve ou celle du jour.",objective:"Monte les quatre fondations de l’As au Roi, une couleur par pile.",sections:[{heading:"La donne",body:["Sept colonnes de tableau contiennent de une à sept cartes. Seule la carte du dessus de chaque colonne commence face visible ; les vingt-quatre autres forment le talon."]},{heading:"Construire le tableau",body:["Pose les cartes en rang décroissant en alternant les couleurs. Une suite face visible se déplace d’un bloc. Seul un Roi — seul ou en tête d’une suite — peut entrer dans une colonne vide."]},{heading:"Tourner et recycler",body:["En Classique, on tourne trois cartes du talon à la fois ; en Détente, une seule. Seule la carte du dessus de la défausse peut bouger. Quand le talon est vide, retourne la défausse sans la mélanger. Il n’y a pas de limite de passages."]},{heading:"Les fondations",body:["Commence chaque couleur par son As, puis monte jusqu’au Roi. Une carte de fondation peut revenir au tableau si tu dois défaire une ligne."]},{heading:"Vider la table",body:["Déplacer la dernière carte face visible d’une colonne retourne automatiquement la carte qui vient d’être dégagée. Termine les quatre fondations pour gagner."]}]},modes:{daily:{name:"Du jour",tagline:"Une table pour tout le monde",description:"Une donne Tirage trois à graine calée sur la date. Rejoue-la, partage-la, ou reviens demain pour une table neuve.",facts:["tirage trois","même donne du jour","passages illimités"]},classic:{name:"Classique",tagline:"Tirage trois",description:"Une donne neuve à graine, avec trois cartes du talon tournées à la fois.",facts:["tirage trois","donne neuve","passages illimités"]},relaxed:{name:"Détente",tagline:"Tirage un",description:"Une donne neuve plus douce : chaque carte du talon arrive une par une.",facts:["tirage un","donne neuve","passages illimités"]}},fields:{drawCount:{label:"Tirage du talon",group:"Donne",options:{3:"Tirage trois — classique",1:"Tirage un — détente"},help:"Tourne une ou trois cartes à la fois. La défausse peut être recyclée sans limite de passages."}},presets:{classic:"Classique",relaxed:"Détente"}},golf:{name:"Golf",subtitle:"le solitaire rapide",tagline:"Joue ±1 sur le trou",description:"Sept colonnes de cinq, toutes les cartes visibles. Joue un rang voisin du trou, enchaîne aussi loin que possible et laisse le moins possible sur l’herbe.",facts:["1 joueur","trou quotidien déterministe","hors ligne"],howToPlay:{summary:"Un solitaire rapide en solo : sept colonnes de cinq, toutes les cartes face visible, et un seul trou.",objective:"Enlève toutes les cartes de l’herbe. Celles qui restent font ton score — plus c’est bas, mieux c’est.",sections:[{heading:"La donne",body:["Sept colonnes reçoivent cinq cartes face visible. Les dix-sept restantes forment la pioche. La première carte de la pioche ouvre le trou."]},{heading:"Joue sur le trou",body:["Seule la carte la plus basse de chaque colonne peut bouger. Pose-la sur le trou si elle est à un rang de distance — un 8 prend un 7 ou un 9. Couleurs et enseignes n’ont aucune importance."]},{heading:"Tourne la pioche",body:["Si rien sur l’herbe ne convient, retourne la carte suivante de la pioche sur le trou. L’ancienne carte du trou est enterrée et ne revient pas. Il n’y a pas de recyclage."]},{heading:"As et Roi",body:["Le Golf classique traite l’As et le Roi comme des impasses. Fairway les relie pour qu’une chaîne puisse continuer."]},{heading:"Le score",body:["Le trou s’arrête quand l’herbe est vide ou que la pioche est épuisée et qu’il n’y a plus de coup. Les cartes encore sur le tableau font ton score. Zéro est un clear."]}]},modes:{daily:{name:"Quotidien",tagline:"Un trou pour tout le monde",description:"Un trou Classique semé par la date. Rejoue-le, partage-le, ou reviens demain pour une nouvelle table.",facts:["sans boucle","même donne quotidienne","le plus bas gagne"]},classic:{name:"Classique",tagline:"As et Roi t’arrêtent",description:"Un trou frais et déterministe. As et Roi sont des impasses ; la pioche ne revient jamais.",facts:["sans boucle","nouvelle donne","pas de recyclage"]},fairway:{name:"Fairway",tagline:"L’As rejoint le Roi",description:"Le même trou rapide, mais As et Roi se jouent l’un sur l’autre pour allonger les chaînes.",facts:["boucle A–R","nouvelle donne","pas de recyclage"]}},fields:{wrap:{label:"L’As rejoint le Roi",group:"Trou",help:"Le Golf classique s’arrête à l’As et au Roi. Fairway les laisse se jouer l’un sur l’autre."}},presets:{classic:"Classique",fairway:"Fairway"}},freecell:{name:"FreeCell",subtitle:"le solitaire à cartes ouvertes",tagline:"Vide la table du jour",description:"Huit colonnes, toutes les cartes faces visibles. Gare les extras dans les cellules libres et renvoie chaque couleur à la maison, de l’As au Roi. La même donne du jour attend tout le monde.",facts:["1 joueur","donne du jour à graine","hors ligne"],howToPlay:{summary:"Le grand classique du solitaire à cartes ouvertes, distribué de façon déterministe pour une table neuve ou celle du jour.",objective:"Monte les quatre fondations de l’As au Roi, une couleur par pile.",sections:[{heading:"La donne",body:["Huit colonnes de tableau montrent toutes les cartes faces visibles. Les quatre premières colonnes reçoivent sept cartes ; les quatre dernières en reçoivent six."]},{heading:"Cellules libres",body:["Gare une carte dans chaque cellule libre. Classique en a quatre ; Détente en a six. Une cellule ne tient qu’une carte, qui peut aller au tableau ou à une fondation."]},{heading:"Construire le tableau",body:["Pose les cartes en rang décroissant en alternant les couleurs. Une suite compacte se déplace d’un bloc si la limite de supermouvement le permet. N’importe quelle carte — pas seulement un Roi — peut entrer dans une colonne vide."]},{heading:"Les fondations",body:["Commence chaque couleur par son As, puis monte jusqu’au Roi. Une carte de fondation peut revenir au tableau si tu dois défaire une ligne."]},{heading:"Vider la table",body:["Renvoie toutes les cartes à la maison. Termine les quatre fondations pour gagner."]}]},modes:{daily:{name:"Du jour",tagline:"Une table pour tout le monde",description:"Une donne Classique à graine calée sur la date. Rejoue-la, partage-la, ou reviens demain pour une table neuve.",facts:["quatre cellules","même donne du jour","n’importe quelle carte au vide"]},classic:{name:"Classique",tagline:"Quatre cellules libres",description:"Une donne neuve à graine, avec quatre cellules d’une carte.",facts:["quatre cellules","donne neuve","n’importe quelle carte au vide"]},relaxed:{name:"Détente",tagline:"Six cellules libres",description:"Une donne neuve plus douce : deux cellules de plus facilitent les longues suites.",facts:["six cellules","donne neuve","n’importe quelle carte au vide"]}},fields:{freeCells:{label:"Cellules libres",group:"Donne",options:{4:"Quatre cellules — classique",6:"Six cellules — détente"},help:"Gare une carte dans chaque cellule. Détente ajoute deux cellules."}},presets:{classic:"Classique",relaxed:"Détente"}},spider:{name:"Spider",subtitle:"le solitaire à deux jeux",tagline:"Décolle huit suites à la couleur",description:"Monte dix colonnes en descendant, ne déplace que les suites d’une même couleur et retire chaque Roi-à-As de la table. La même donne quotidienne à deux couleurs attend tout le monde.",facts:["1 joueur","donne du jour à graine","hors ligne"],howToPlay:{summary:"Spider façon Microsoft à deux jeux : dix colonnes, cinq rangées de réserve et huit couleurs à décrocher.",objective:"Envoie huit suites de la même couleur, du Roi à l’As, vers les fondations.",sections:[{heading:"La donne",body:["Dix colonnes sont distribuées : les quatre premières en ont six et les autres cinq. Seule la carte du dessus de chaque colonne commence face visible. Il reste cinquante cartes au talon, en cinq rangées de dix."]},{heading:"Construire le tableau",body:["Pose les cartes en rang décroissant, n’importe quelle couleur. Seule une suite descendante de la même couleur peut se déplacer d’un bloc. Une colonne vide accepte n’importe quelle carte ou suite."]},{heading:"Distribuer une rangée",body:["Clique le talon pour poser une carte face visible sur chaque colonne. Tu ne peux pas distribuer tant qu’une colonne est vide, ou s’il reste moins de dix cartes."]},{heading:"Décrocher une couleur",body:["Quand une suite de la même couleur, du Roi à l’As, est complète sur une colonne, elle part vers une fondation dans le même coup. Une carte retournée nouvellement exposée se retourne toute seule."]},{heading:"Les couleurs",body:["Détendu peint les 104 cartes en piques. Classique (le quotidien) utilise piques et cœurs. Difficile utilise toutes les couleurs, donc les suites empaquetées sont plus rares."]}]},modes:{daily:{name:"Quotidien",tagline:"Une table pour tous",description:"Une donne à deux couleurs semée par la date. Rejoue-la, partage-la, ou reviens demain pour une table neuve.",facts:["deux couleurs","même donne du jour","cinq rangées de talon"]},relaxed:{name:"Détendu",tagline:"Que des piques",description:"Une donne neuve plus douce : chaque carte est un pique, les suites se montent librement.",facts:["une couleur","donne neuve","cinq rangées de talon"]},classic:{name:"Classique",tagline:"Deux couleurs",description:"Une donne neuve à graine peinte en piques et cœurs — le défaut Microsoft.",facts:["deux couleurs","donne neuve","cinq rangées de talon"]},hard:{name:"Difficile",tagline:"Quatre couleurs",description:"La donne complète à deux jeux. Les suites d’une même couleur sont rares et chaque décrochage se mérite.",facts:["quatre couleurs","donne neuve","cinq rangées de talon"]}},fields:{suitCount:{label:"Couleurs",group:"Donne",options:{1:"Une couleur — détendu",2:"Deux couleurs — classique",4:"Quatre couleurs — difficile"},help:"Les donnes à une couleur sont toutes des piques. Le classique utilise piques et cœurs. Le difficile utilise toutes les couleurs."}},presets:{relaxed:"Détendu",classic:"Classique",hard:"Difficile"}},pyramid:{name:"Pyramide",subtitle:"associe jusqu’à treize",tagline:"Vide la pyramide du jour",description:"Vingt-huit cartes en triangle. Associe des rangs libres qui font 13, tourne la pioche et laisse le moins possible.",facts:["1 joueur","pyramide quotidienne déterministe","hors ligne"],howToPlay:{summary:"Un solitaire en solo : vingt-huit cartes en pyramide, et une pioche que tu tournes sur une seule défausse.",objective:"Associe des cartes libres qui font treize et vide la table. Celles qui restent font ton score — plus c’est bas, mieux c’est.",sections:[{heading:"La donne",body:["Sept rangées forment une pyramide de vingt-huit cartes face visible. Une carte est libre quand les deux qui la recouvrent sont parties — ou quand elle est sur la dernière rangée. Les vingt-quatre restantes forment la pioche. La défausse commence vide."]},{heading:"Associe jusqu’à treize",body:["L’As vaut 1 et le Roi vaut 13. Deux cartes libres dont les rangs font 13 peuvent s’associer — Dame et As, Valet et 2, et ainsi de suite. Un Roi vaut déjà 13 et se retire seul. Les enseignes n’ont aucune importance."]},{heading:"La défausse",body:["Tourne une carte de la pioche sur la défausse à la fois. Seule la carte du dessus est vivante : associe-la à une carte libre de la pyramide, ou retire-la si c’est un Roi. Les cartes enterrées de la défausse ne s’associent pas entre elles."]},{heading:"Recycler",body:["Quand la pioche est vide, retourne la défausse sans mélanger. Classique autorise deux recyclages — trois passages. Relaxé ne s’épuise jamais."]},{heading:"Le score",body:["La donne s’arrête quand plus aucune carte ne reste, ou quand rien ne s’associe et que la pioche ne peut plus revenir. Chaque carte encore dans la pyramide, la pioche ou la défausse compte. Zéro est un clear."]}]},modes:{daily:{name:"Quotidien",tagline:"Une pyramide pour tout le monde",description:"Une pyramide Classique semée par la date. Rejoue-la, partage-la, ou reviens demain pour une nouvelle table.",facts:["deux recyclages","même donne quotidienne","le plus bas gagne"]},classic:{name:"Classique",tagline:"Trois passages",description:"Une pyramide fraîche et déterministe. La défausse peut être recyclée deux fois — trois voyages dans la pioche.",facts:["deux recyclages","nouvelle donne","trois passages"]},relaxed:{name:"Relaxé",tagline:"Passages illimités",description:"La même table d’associations, mais la défausse peut être retournée autant de fois que tu veux.",facts:["recyclages illimités","nouvelle donne","pas de limite de passages"]}},fields:{recyclesLimit:{label:"Recyclages de la défausse",group:"Pioche",options:{2:"Deux recyclages — classique","-1":"Illimité — relaxé"},help:"Classique autorise deux recyclages, trois passages dans la pioche. Relaxé ne s’épuise jamais."}},presets:{classic:"Classique",relaxed:"Relaxé"}},eights:{name:"Huit américain",subtitle:"le jeu du huit joker",tagline:"Les huit passent partout",description:"Un paquet ordinaire, une pile qui grandit. Suis la couleur ou le rang, pose un huit pour plier la table à la couleur de ton choix, et fais payer aux autres tout ce qu’ils ont encore en main.",facts:["2–6 joueurs","on joue jusqu’à un score","solo ou entre amis"],howToPlay:{summary:"Un paquet ordinaire, une pile, et des huit qui passent sur tout. Vide ta main et fais payer à la table ce qu’elle a encore en main.",objective:"Vide ta main pour clore la manche et empoche toutes les cartes restantes des autres. Le premier à dépasser le score cible remporte la partie.",sections:[{heading:"Jouer une carte",body:["À ton tour, joue une carte qui suit la pile par la couleur ou par le rang — un 7♦ passe sur n’importe quel carreau et sur n’importe quel autre sept.","Un huit est joker. Il passe sur tout, et c’est toi qui annonces la couleur qui doit suivre.","Rien à jouer ? Pioche. La pile demande la même couleur tant que personne ne la change."]},{heading:"Cartes d’action",body:["Chacune est un réglage de la table, pour qu’une maison joue aussi simplement ou aussi bruyamment qu’elle veut."],bullets:[{label:"8 — joker",text:"toujours jouable ; tu annonces la couleur qui suit (toujours actif)"},{label:"2 — pioche deux",text:"la place suivante prend deux cartes et perd son tour"},{label:"Q — passe",text:"le jeu saute carrément la place suivante"},{label:"A — inverse",text:"la table change de sens ; en tête-à-tête, ça te redonne un tour"}]},{heading:"Piocher",body:["Par tradition, tu pioches jusqu’à trouver quelque chose de jouable. Désactive ça et un tour n’achète qu’une seule carte.","Une carte piochée qui peut être jouée est à toi : joue-la tout de suite ou garde-la — sauf si la table t’oblige à la jouer.","Quand le talon est épuisé, tout ce qui se trouve sous la carte face visible est remélangé en un talon neuf."]},{heading:"Compter la manche",body:["Dès qu’une main se vide, tout le monde compte ce qu’il a encore en main et celui qui s’est débarrassé de tout empoche le lot."],bullets:[{label:"Chaque huit",text:"50 points"},{label:"Chaque 10, V, D ou R",text:"10 points"},{label:"Chaque as",text:"1 point"},{label:"Tout le reste",text:"sa valeur faciale"},{label:"Manche bloquée",text:"talon épuisé et personne ne peut jouer — la main la plus légère gagne et empoche la différence"}]},{heading:"Gagner la partie",body:["Les manches s’enchaînent, la donne avançant d’une place à chaque fois, jusqu’à ce que quelqu’un dépasse le score cible. Le score le plus haut gagne.","Une égalité en tête redonne une manche plutôt que de partager la couronne."]}]},modes:{classic:{name:"Classique",tagline:"Des huit et rien d’autre",description:"Le jeu tel que ta grand-mère le distribuait. Suis la couleur ou le rang, pose un huit pour annoncer une couleur, pioche jusqu’à trouver ton bonheur. Premier à 100.",facts:["seuls les 8 sont jokers","pioche jusqu’au jouable","jusqu’à 100"]},house:{name:"Maison",tagline:"Deux, dames et as",description:"Les règles que presque tout le monde joue vraiment : les deux font piocher, les dames sautent la place suivante, les as retournent la table. Premier à 100.",facts:["2 · Q · A actifs","pas de cumul","jusqu’à 100"]},chaos:{name:"Délire",tagline:"Empile tout",description:"Les deux s’empilent sur les deux jusqu’à ce que quelqu’un avale le paquet, une carte piochée doit être jouée, et tu n’as droit qu’à une pioche par tour. Partie longue, table bruyante.",facts:["cumul activé","jeu forcé","jusqu’à 150"]}},fields:{handSize:{label:"Cartes distribuées",help:"Le nombre de cartes avec lequel chaque place commence une manche.",group:"La donne"},targetScore:{label:"Jouer jusqu’à",help:"Les manches s’enchaînent jusqu’à ce que quelqu’un dépasse ce score.",group:"La donne"},twosDrawTwo:{label:"Les deux font piocher deux",help:"La place suivante prend deux cartes et perd son tour.",group:"Cartes d’action"},queensSkip:{label:"Les dames font passer",help:"Le jeu saute carrément la place suivante.",group:"Cartes d’action"},acesReverse:{label:"Les as inversent",help:"La table change de sens. À deux joueurs, ça fait passer le tour.",group:"Cartes d’action"},stackDrawTwo:{label:"Cumuler les deux",help:"Réponds à un deux par le tien et fais suivre toute la pioche.",group:"Règles de la maison"},drawUntilPlayable:{label:"Piocher jusqu’au jouable",help:"La règle traditionnelle. Désactive-la pour piocher exactement une carte par tour.",group:"Règles de la maison"},forcePlay:{label:"Jeu forcé",help:"Une carte piochée qui peut être jouée doit être jouée.",group:"Règles de la maison"}},presets:{classic:"Huit américain classique",house:"Huit américain maison",chaos:"Huit américain délire"}},durak:{name:"Durak",subtitle:"le fou que personne ne veut être",tagline:"Ne soyez jamais le dernier avec des cartes en main",description:"Un jeu court, une couleur d’atout, et une table d’attaques et de défenses. Battez chaque carte qu’on vous lance ou ramassez tout — le dernier siège encore muni de cartes porte le bonnet du fou.",facts:["2 à 6 joueurs","jeu de 36 cartes","seul ou entre amis"],howToPlay:{summary:"Un jeu court, une couleur d’atout, et une seule mission : ne jamais être le dernier siège encore muni de cartes.",objective:"Videz votre main et restez dehors pour de bon. Une fois la pioche épuisée, le dernier siège encore muni de cartes est le Durak.",sections:[{heading:"La donne",body:["Chaque siège reçoit six cartes d’un jeu de 36 : du six à l’as, quatre couleurs, sans deux, trois, quatre ni cinq.","La carte suivante de la pioche est retournée : sa couleur est l’atout pour toute la donne, et elle reste face visible jusqu’à ce que la pioche soit épuisée.","Qui détient l’atout le plus bas attaque en premier. Personne n’en a ? Le siège un ouvre."]},{heading:"Attaquer et défendre",body:["L’attaquant joue une carte. Le défenseur doit la battre : une carte plus forte de la même couleur, ou n’importe quel atout si l’attaque n’en était pas un.","Les autres sièges peuvent ajouter d’autres cartes, tant que la valeur est déjà apparue sur la table — gagnée ou perdue, cette valeur reste valable jusqu’à la fin de la manche.","Battez toutes les cartes et toute la table est écartée, hors jeu pour de bon — vous attaquez ensuite.","Impossible d’en battre une ? Ramassez toute la table dans votre main. Le jeu passe au siège suivant après vous."],bullets:[{label:"Limite d’attaque",text:"un défenseur ne voit jamais plus de cartes qu’il n’en avait au début de la manche"},{label:"Réapprovisionnement",text:"après chaque manche, les mains remontent à six — l’attaquant d’abord, puis les autres, le défenseur en dernier"}]},{heading:"Perevodnoy (transfert)",body:["Quand cette règle de maison est activée, un défenseur qui n’a encore rien battu peut transférer à la place : il joue une carte de même valeur, et le siège suivant hérite de toute l’attaque."]},{heading:"La fin de la donne",body:["Une fois la pioche épuisée, vider sa main vous met hors jeu pour de bon — définitivement, dans l’ordre où cela arrive.","Le dernier siège encore muni de cartes est le Durak. Tous les autres sont classés selon la rapidité de leur sortie."]}]},modes:{classic:{name:"Classique",tagline:"Podkidnoy — le jeu traditionnel avec relances",description:"Attaquez, défendez, et ajoutez toute carte dont la valeur est déjà sur la table. Pas de transfert : on bat la carte ou on ramasse la table.",facts:["relances activées","pas de transfert","mains de 6 cartes"]},transfer:{name:"Perevodnoy",tagline:"Transmettez toute l’attaque",description:"Tout ce qu’offre le mode Classique, plus une échappatoire : un défenseur qui n’a encore rien battu peut transférer une valeur identique directement au siège suivant.",facts:["transferts activés","relances activées","mains de 6 cartes"]},"heads-up":{name:"Tête-à-tête",tagline:"Un contre un, fin rapide",description:"Conçu pour deux joueurs. La première main vidée gagne aussitôt, pioche ou non — sans attendre que le jeu s’épuise.",facts:["2 joueurs","victoire instantanée","rapide"]}},fields:{transfer:{label:"Transfert (perevodnoy)",help:"Un défenseur qui détient une valeur identique peut transmettre toute l’attaque au siège suivant plutôt que de la battre.",group:"La manche"},throwIns:{label:"Relances (podkidnoy)",help:"N’importe quel siège attaquant peut ajouter d’autres cartes dont la valeur est déjà sur la table.",group:"La manche"},maxAttacks:{label:"Limite d’attaque",help:"Le plus grand nombre de cartes d’attaque qu’un défenseur peut voir en une manche.",group:"La manche"},refillTo:{label:"Taille de la main",help:"Cartes distribuées au départ, et la taille à laquelle chaque main remonte après une manche.",group:"La donne"},instantWin:{label:"Victoire instantanée",help:"La première main vidée gagne aussitôt, même si la pioche contient encore des cartes.",group:"Règles maison"}},presets:{classic:"Durak classique",transfer:"Perevodnoy","heads-up":"Tête-à-tête"}},palace:{name:"Palace",subtitle:"le jeu qui vide les couches",tagline:"Videz la table, couche par couche",description:"La main, puis le visible, puis le caché — brûlez les dix, esquivez les deux, et soyez le premier à vider chaque couche. Aussi connu sous le nom de Shithead ou Karma.",facts:["2–6 joueurs","des deux, des dix et des huit","solo ou entre amis"],howToPlay:{summary:"Débarrassez-vous de tout ce que vous tenez — la main, puis la rangée visible, puis la rangée cachée — avant que quelqu’un d’autre ne vide la table.",objective:"Videz votre main, votre rangée visible et votre rangée cachée en premier pour gagner la manche. Les manches gagnées s’accumulent sur la partie ; le premier à atteindre l’objectif remporte la partie.",sections:[{heading:"La donne",body:["Chacun reçoit trois cartes face cachée, trois cartes face visible posées dessus, et trois cartes en main.","Avant de commencer, échangez autant de cartes de votre main que vous voulez contre vos propres cartes visibles — un seul échange, puis vous vous déclarez prêt."]},{heading:"Jouer sur la pile",body:["À votre tour, jouez une ou plusieurs cartes de même valeur qui égalent ou dépassent la valeur de la pile, ou ramassez toute la pile dans votre main.","Vous devez vider votre main avant de toucher votre rangée visible, et vider la rangée visible avant de toucher la rangée cachée."],bullets:[{label:"Ouvrir la manche",text:"celui qui détient la plus petite carte ordinaire commence — les trois d’abord, puis en montant"},{label:"Ramassez à tout moment",text:"vous pouvez prendre la pile même avec un coup légal en main — parfois c’est le choix le plus sûr"},{label:"Jouer une carte cachée",text:"main et rangée visible vides, retournez une carte cachée à l’aveugle — si elle bat la pile, elle reste en jeu et vous continuez ; sinon, vous ramassez la pile et la carte"}]},{heading:"Les cartes spéciales",body:["Quatre valeurs changent les règles — toutes activées par défaut, toutes réglables :"],bullets:[{label:"2 — réinitialise",text:"se joue sur n’importe quoi ; le seuil de la pile retombe presque à rien"},{label:"10 — brûle",text:"se joue sur n’importe quoi ; la pile sort du jeu et vous rejouez"},{label:"8 — invisible",text:"toujours jouable, et ne change jamais ce que la pile demande — le suivant répond à ce qu’il y a dessous"},{label:"Carré",text:"quatre cartes de même valeur en haut de la pile la brûlent, peu importe comment elles y sont arrivées — vous rejouez"}]},{heading:"Gagner la manche",body:["Dès qu’un joueur vide sa main, sa rangée visible et sa rangée cachée à la fois, la manche se termine immédiatement.","Tous les autres sont classés selon le nombre de cartes qu’il leur reste — moins c’est mieux — avec les cartes cachées restantes comme départage."]},{heading:"Règles de la maison",body:["Réglez la table dans les paramètres de salle avant de commencer :"],bullets:[{label:"Échange avant de jouer",text:"désactivez pour passer directement de la donne au premier coup"},{label:"Le 2 réinitialise / le 10 brûle / le 8 est toujours jouable",text:"désactivez n’importe quel spécial pour rendre cette valeur ordinaire"},{label:"Le carré brûle",text:"désactivez pour laisser une pile de valeurs identiques simplement grandir"},{label:"Premier à (manches gagnées)",text:"combien de manches il faut pour gagner la partie — 1 pour une manche rapide, jusqu’à 7 pour une longue soirée"}]}]},modes:{classic:{name:"Classique",tagline:"L’ascension complète par couches",description:"Échangez, puis videz la main, le visible et le caché. Le premier à trois manches gagnées remporte la table.",facts:["jusqu’à 3 manches","échange activé","tous les spéciaux"]},quick:{name:"Rapide",tagline:"Une manche et c’est réglé",description:"Une seule manche décide de tout — mêmes spéciaux, sans longue partie à accumuler.",facts:["jusqu’à 1 manche","~10 min","idéal en échauffement"]},chaos:{name:"Chaos",tagline:"Sans échange, sans pitié",description:"Directement de la donne au jeu — aucune phase d’échange à préparer. Tous les spéciaux au maximum : le 2 réinitialise, le 10 brûle, le 8 reste invisible, le carré embrase toujours la pile.",facts:["jusqu’à 3 manches","sans phase d’échange","attendez-vous à des brûlages"]}},fields:{allowSwap:{label:"Échange avant de jouer",help:"La phase d’échange entre la donne et le premier coup."},twosReset:{label:"Le 2 réinitialise la pile",help:"Se joue sur n’importe quoi et réinitialise le seuil de la pile."},tensBurn:{label:"Le 10 brûle la pile",help:"Se joue sur n’importe quoi et brûle la pile ; le même joueur rejoue."},eightsBlind:{label:"Le 8 est toujours jouable",help:"Toujours un coup légal, et ne change jamais le seuil de la pile."},fourKindBurn:{label:"Le carré brûle",help:"Quatre cartes de même valeur en haut de la pile la brûlent ; le même joueur rejoue."},winsTo:{label:"Premier à (manches gagnées)",help:"La partie se termine quand un joueur atteint ce nombre de manches gagnées."}},presets:{classic:"Palace classique",quick:"Palace rapide",chaos:"Palace chaotique"}},pinochle:{name:"Pinocle",subtitle:"le jeu en duo",tagline:"Enchéris, déclare, ramasse les plis",description:"Assieds-toi face à ton partenaire, remporte les enchères, annonce l’atout et pose ta déclaration. As, dix et rois sont les cartes qui comptent — remplis ton contrat, ou tu es chuté.",facts:["4 joueurs · 2v2","enchères · déclaration · plis","solo ou entre amis"],howToPlay:{summary:"Le classique américain en duo — enchéris, annonce l’atout, déclare, puis joue les plis.",objective:"Assis face à ton partenaire, remporte les enchères et remplis ton contrat — déclaration plus points de plis au moins égaux à ton annonce. La première équipe à atteindre le score cible après une manche complète remporte la partie.",sections:[{heading:"La table",body:["Quatre joueurs, deux équipes : toi et le joueur en face de toi êtes partenaires. Chaque manche distribue le double jeu complet de 48 cartes — douze chacun, pas de mort. La donne tourne à gauche à chaque manche."]},{heading:"Les enchères",body:["En commençant à la gauche du donneur, chaque joueur passe ou enchérit plus haut que l’enchère précédente. Une fois que tu passes, tu es hors jeu pour la manche. Le dernier joueur restant avec une enchère remporte les enchères et annonce l’atout. Si tout le monde passe sans qu’aucune enchère n’ait été faite, la manche est annulée et redistribuée par le même donneur."],bullets:[{label:"Enchère d’ouverture",text:"doit dépasser le minimum de la table (25 en mode Classique)"},{label:"Surenchères",text:"n’importe quel entier supérieur, jusqu’à un plafond de 60"}]},{heading:"La déclaration",body:["Une fois l’atout annoncé, chaque joueur pose sa déclaration pour marquer des points. Les cartes restent en main — déclarer, c’est marquer des points, pas défausser — et la table la calcule pour toi, personne ne peut donc se tromper."],bullets:[{label:"Suite à l’atout",text:"as-10-roi-dame-valet d’atout, 15 points"},{label:"Mariage",text:"roi + dame d’une couleur — 4 si atout (2 de plus si c’est une deuxième paire en plus de la suite), 2 sinon"},{label:"Pinocle",text:"dame de pique + valet de carreau vaut 4 ; posséder les deux exemplaires de chacune est un double pinocle qui vaut 30"},{label:"Carrés",text:"une carte d’un rang dans les quatre couleurs — as 10, rois 8, dames 6, valets 4"},{label:"Dix",text:"chaque 9 d’atout que tu détiens vaut 1"}]},{heading:"Jouer les plis",body:["L’enchérisseur entame le premier pli. Tu dois fournir la couleur demandée si tu le peux ; l’atout bat une couleur non demandée qui n’est pas l’atout, sinon la carte la plus haute l’emporte. As, dix et rois valent chacun 10 points quand ils sont capturés dans un pli ; le dernier pli vaut 10 points de plus. Le gagnant d’un pli entame le suivant."]},{heading:"Compter une manche",body:["Ajoute la déclaration de l’équipe qui a enchéri aux points de plis qu’elle a remportés. Si le contrat est rempli, elle marque le total complet. Sinon, elle est chutée — elle perd exactement le montant de son enchère, déclaration comprise. L’autre équipe marque toujours ses propres points de plis, et sa déclaration aussi, sauf si la table l’a désactivée."]},{heading:"La partie",body:["Les manches s’accumulent jusqu’à ce qu’une équipe atteigne l’objectif (100 / 150 / 500). Si les deux équipes le franchissent dans la même manche, l’équipe qui a enchéri remporte la partie directement, sauf si elle est chutée — dans ce cas, elle perd le départage face au score le plus élevé, l’enchérisseur remportant tout ex æquo restant."]},{heading:"Règles maison",body:["Les réglages de la salle changent le score cible, l’enchère minimale d’ouverture, et si les adversaires marquent leur déclaration. Les tables Classiques gardent les valeurs par défaut."]}]},modes:{classic:{name:"Classique",tagline:"Partie en 150",description:"Pinocle en duo jusqu’à 150, enchère d’ouverture minimale de 25. Le jeu tel qu’on y joue à chaque table de cuisine.",facts:["partie en 150","enchère min. 25","~30 min"]},quick:{name:"Rapide",tagline:"Premier à 100",description:"Mêmes règles, course plus courte — 100 points, enchère d’ouverture plus basse, terminé plus vite.",facts:["partie en 100","enchère min. 20","~15 min"]},marathon:{name:"Marathon",tagline:"Partie en 500",description:"Une longue lutte en duo jusqu’à 500 — chaque déclaration et chaque chute comptent.",facts:["partie en 500","enchère min. 25","~90 min"]}},fields:{target:{label:"Partie en",group:"Partie",help:"Après chaque manche, la première équipe à atteindre ou dépasser ce score remporte la partie.",options:{100:"100 — rapide",150:"150 — classique",500:"500 — marathon"}},minBid:{label:"Enchère minimale",group:"Enchères",help:"L’enchère d’ouverture doit dépasser ce minimum. Chaque enchère suivante doit battre la précédente, jusqu’à 60."},opponentsScoreMeld:{label:"Les adversaires marquent leur déclaration",group:"Score",help:"Si désactivé, l’équipe qui n’a pas enchéri ne marque que les points de plis remportés — pas sa déclaration."}},presets:{classic:"Classique",quick:"Rapide",marathon:"Marathon"}},tripeaks:{name:"TriPeaks",subtitle:"dégage les trois sommets",tagline:"Joue ±1 sur le trou",description:"Dix-huit cartes en trois sommets, toutes face visible. Libère une carte en dégageant ce qui la recouvre, enchaîne les coups sur le trou et dégage les sommets.",facts:["1 joueur","sommets du jour avec graine","hors ligne"],howToPlay:{summary:"Une réussite à un joueur : trois sommets de dix-huit cartes, toutes face visible, et une pioche que tu tournes sur un unique trou.",objective:"Dégage toutes les cartes des sommets. Les cartes restantes sont ton score — moins il en reste, mieux c’est.",sections:[{heading:"La donne",body:["Trois sommets de dix-huit cartes reposent face visible sur quatre rangées. La rangée de base de neuf cartes est toujours libre. Les trente-quatre cartes restantes forment la pioche, et la première ouvre le trou."]},{heading:"Cartes libres",body:["Une carte devient libre dès que les deux cartes posées dessus ont disparu. Seules les cartes libres peuvent bouger — les cartes encore recouvertes restent bloquées jusqu’à ce que leurs filles se dégagent."]},{heading:"Joue sur le trou",body:["Joue une carte libre sur le trou quand elle est à un rang d’écart — un 8 accepte un 7 ou un 9. Les couleurs et enseignes n’ont pas d’importance. Enchaîne autant de coups que possible."]},{heading:"Tourne la pioche",body:["Si rien sur les sommets ne convient, tourne la carte suivante de la pioche sur le trou. L’ancienne carte du trou est ensevelie dessous."]},{heading:"As, Roi et la pioche",body:["Le TriPeaks Classique traite l’As et le Roi comme des culs-de-sac, et la pioche ne revient jamais. Relaxé permet à l’As et au Roi de s’enchaîner, et autorise un mélange du trou vers la pioche une fois celle-ci épuisée."]},{heading:"Le score",body:["La partie se termine quand les sommets sont dégagés, ou que plus rien ne joue et que la pioche ne peut plus revenir. Les cartes restant sur les sommets forment ton score. Zéro, c’est un sommet vidé."]}]},modes:{daily:{name:"Du jour",tagline:"Une donne pour tout le monde",description:"Une donne Classique déterminée par la date. Rejoue-la, partage-la, ou reviens demain pour de nouveaux sommets.",facts:["sans enchaînement","même donne du jour","moins il en reste, mieux c’est"]},classic:{name:"Classique",tagline:"As et Roi t’arrêtent",description:"Une donne fraîche déterminée par une graine. L’As et le Roi sont des culs-de-sac ; la pioche ne revient jamais.",facts:["sans enchaînement","donne fraîche","sans recyclage"]},relaxed:{name:"Relaxé",tagline:"L’As s’enchaîne au Roi",description:"Les mêmes trois sommets, mais l’As et le Roi se jouent l’un sur l’autre et le trou peut être recyclé une fois.",facts:["enchaîne A–K","donne fraîche","un recyclage"]}},fields:{wrap:{label:"L’As s’enchaîne au Roi",group:"Trou",help:"Le TriPeaks Classique s’arrête à l’As et au Roi. Relaxé laisse A et K se jouer l’un sur l’autre."},recycle:{label:"Recycler le trou",group:"Pioche",help:"Quand la pioche s’épuise, mélange le trou (sauf sa carte du dessus) une fois vers la pioche."}},presets:{classic:"Classique",relaxed:"Relaxé"}}},pt:{blitz:{name:"Blitz",subtitle:"o jogo do 31",tagline:"Corra atrás do 31",description:"Compre, troque e bata na mesa rumo ao 31 num naipe só. Três formatos de partida, bots espertos e uma comemoração bem barulhenta.",facts:["2–4 jogadores","clássico · rápido · cronometrado","solo ou com amigos"],howToPlay:{summary:"O clássico de boteco 31 — compre, troque e bata até ter um naipe valendo 31.",objective:"Termine a rodada com a mão mais valiosa da mesa. A mão pontua pelo melhor naipe: A=11, figuras=10, números pelo valor de face. 31 num naipe só é BLITZ e vence na hora.",sections:[{heading:"Sua vez",body:["Você tem duas ações:"],bullets:[{label:"Comprar",text:"pegue a carta do topo do monte, ou roube o topo da pilha de descarte"},{label:"Descartar",text:"deslize uma carta da sua mão, virada para cima, para a pilha"}]},{heading:"Pontuando a mão",body:["Só conta o seu melhor naipe. Três copas somando 27 vencem três cartas misturadas somando 30.","Trinca é uma mão especial que vale 30½ (ajuste opcional da casa)."]},{heading:"Bater",body:["Em vez de comprar, você pode BATER para encerrar a rodada. Todo mundo tem direito a exatamente mais uma vez, e aí as mãos viram para o confronto.","A mão mais baixa perde uma vida. Se FOI VOCÊ quem bateu e empatou ou ficou por último, a penalidade é sua — bata com confiança."]},{heading:"Blitz!",body:["Com 31 num naipe só, a rodada explode na hora — todos os outros jogadores perdem uma vida, sem confronto.","Recebeu um Blitz antes da sua primeira vez? Conta. Pode se gabar à vontade."]},{heading:"Formatos de partida",bullets:[{label:"Clássico",text:"perca uma vida a cada rodada perdida; vence o último com vidas"},{label:"Rápido",text:"rodadas avulsas, contador de vitórias até N, redistribuição instantânea"},{label:"Cronometrado",text:"relógio de partida, tempos de vez forçados, quem tiver mais rodadas vencidas na buzina leva"}]},{heading:"Regras da casa",body:["Cada mesa pode ser ajustada nas configurações da sala — vidas, penalidades de batida, empates, trinca, trava de descarte e tempos de vez ficam todos lá."]}]},modes:{classic:{name:"Clássico",tagline:"Vidas em jogo",description:"Perdeu a rodada, perdeu uma vida. Bata cedo ou corra atrás do 31 perfeito — o último jogador com fichas leva a partida.",facts:["3 vidas cada","o último de pé","~5–10 min"]},fast:{name:"Rápido",tagline:"Uma rodada por vez",description:"Rodadas independentes, redistribuição instantânea. A mão mais alta leva o pote — o primeiro a três leva a partida.",facts:["primeiro a 3 vitórias","sem eliminações","~2–4 min"]},timed:{name:"Cronometrado",tagline:"Corra contra a buzina",description:"Um relógio de partida de três minutos e tempos de vez curtos. Quem tiver mais rodadas vencidas quando a campainha tocar leva.",facts:["relógio de 3:00","7 s por vez","empates em morte súbita"]}},fields:{threeOfAKind:{label:"Trinca",options:{"30.5":"Vale 30,5",30:"Vale 30",off:"Desligado"}},tieLowest:{label:"Empate na lanterna",options:{both:"Os dois perdem",nobody:"Ninguém perde",redeal:"Redistribuir entre os empatados"}},discardLock:{label:"Travar o descarte que você acabou de pegar"}},presets:{"classic-pub":"Boteco Clássico",cutthroat:"Vale-Tudo",friendly:"Amistoso"}},cribbage:{name:"Cribbage",subtitle:"a corrida dos pinos",tagline:"Avance até 121",description:"A clássica corrida de pub — monte quinzes, sequências e pares na sua mão, marque-os com os pinos no tabuleiro e reze para ninguém cortar um valete atrás de você.",facts:["2 jogadores","clássico · sem piedade","solo ou com amigos"],howToPlay:{summary:"A clássica corrida de pub — monte combinações que pontuam na sua mão e avance com os pinos até 121.",objective:"Seja o primeiro a marcar 121 pontos no tabuleiro. Os pontos vêm duas vezes: das cartas jogadas na mesa (a contagem) e da contagem da sua mão e do crib na hora de mostrar.",sections:[{heading:"A distribuição",body:["Você recebe seis cartas. Fique com quatro e deslize duas, viradas para baixo, para o CRIB — uma mão bônus que pontua para quem está dando as cartas nesta rodada.","Descarte com generosidade quando o crib é seu, e com cautela quando é do adversário."]},{heading:"O corte",body:["Quem dá as cartas corta o baralho para revelar a carta inicial, compartilhada por todas as mãos.","Cortar um valete marca HIS HEELS — dois pontos na hora para quem deu as cartas."]},{heading:"A contagem",body:["Começando à esquerda de quem deu as cartas, os jogadores alternam baixando uma carta, mantendo uma soma corrente dos valores (figuras valem 10). A soma nunca pode passar de 31.","Pontue enquanto joga:"],bullets:[{label:"Quinze",text:"sua carta faz a soma corrente bater exatamente 15 — 2 pontos"},{label:"Par / trinca / quadra",text:"igualar o valor da carta anterior — 2 / 6 / 12 pontos"},{label:"Sequência",text:"três ou mais cartas em ordem, em qualquer sequência de jogo — 1 ponto por carta"},{label:"Trinta e um",text:"sua carta faz a soma bater exatamente 31 — 2 pontos"},{label:"Go e última carta",text:"se ninguém puder jogar sem passar de 31, o último a baixar uma carta marca 1 ponto e a soma zera"}]},{heading:"A mostra",body:["Depois da contagem, todos contam em voz alta: primeiro a mão de quem não deu as cartas, depois a de quem deu, e por fim o crib. A carta inicial conta como quinta carta."],bullets:[{label:"Quinzes",text:"cada combinação de cartas que soma 15 — 2 pontos cada"},{label:"Pares",text:"um par vale 2, trinca 6, quadra 12"},{label:"Sequências",text:"sequências pontuam por carta; sequências duplas multiplicam (7-7-8-9 = 12)"},{label:"Flush",text:"quatro cartas do mesmo naipe na sua MÃO valem 4, cinco com a carta inicial combinando. No CRIB só vale o flush das cinco cartas."},{label:"His nobs",text:"um valete do naipe da carta inicial — 1 ponto"}]},{heading:"Vitória e vexames",body:["O primeiro a chegar a 121 vence, mesmo no meio da contagem. A vez de dar as cartas alterna a cada rodada.","Com a regra do vexame ligada, quem perde terminando abaixo de 90 leva um SKUNK — uma humilhação daquelas para saborear."]},{heading:"Regras da casa",body:["As configurações da sala carregam as discussões de pub:"],bullets:[{label:"Vexames",text:"marque os perdedores abaixo de 90 (ligado por padrão)"},{label:"Muggins",text:"se você não marcar pontos que ganhou na mesa, o adversário pode roubá-los (desligado por padrão) — marque rápido!"}]}]},modes:{"classic-pub":{name:"Pub Clássico",tagline:"O jogo de verdade",description:"Seis cartas, duas para o crib e uma longa corrida de pinos até 121. Vexames contam — termine abaixo de 90 e ouça sobre isso para sempre.",facts:["corrida até 121","linha do vexame aos 90","~10–15 min"]},cutthroat:{name:"Sem Piedade",tagline:"O muggins está de olho",description:"A mesma corrida, com garras mais afiadas: deixe de marcar seus pontos na mesa e o adversário fica com eles.",facts:["muggins ativo","roube pontos não marcados","sem piedade"]},"match-play":{name:"Disputa de Partidas",tagline:"Melhor de três tabuleiros",description:"Uma noite longa como manda o figurino: corra até 121, zere os pinos e corra de novo. O primeiro a vencer dois jogos completos leva a partida.",facts:["primeiro a 2 jogos","distribuidor alterna","~25–40 min"]}},fields:{skunks:{label:"Linha do vexame aos 90"},muggins:{label:"Muggins (roube pontos não marcados)"},gamesToWin:{label:"Jogos para vencer"}},presets:{"classic-pub":"Pub Clássico",cutthroat:"Sem Piedade","match-play":"Disputa de Partidas",friendly:"Amistoso"}},wild:{name:"Wild",subtitle:"o jogo de se livrar das cartas",tagline:"Solte todas as cartas",description:"Um caos de 112 cartas com pulos, inversões, +4, despejos de cor e invasões de vez. A mesma mesa acolhedora, um baralho bem mais barulhento.",facts:["2–4 jogadores","distribuição cronometrada","solo ou com amigos"],howToPlay:{summary:"Um caos de 112 cartas de se livrar da mão — combine com o topo da pilha, solte cartas de ação e esvazie a mão primeiro.",objective:"Seja o primeiro jogador sem cartas na mão. As cartas de ação atrapalham todo mundo — a menos que revidem.",sections:[{heading:"Jogando uma carta",body:["Na sua vez, jogue uma carta que combine com o topo da pilha pela cor ou pela face, ou compre uma carta.","Curingas podem ser jogados a qualquer momento e deixam você escolher a próxima cor."]},{heading:"Cartas de ação",bullets:[{label:"Pular",text:"o próximo jogador perde a vez — e não pode invadir de volta"},{label:"Inverter",text:"o jogo muda de direção; um contra um, dá a você outra vez"},{label:"Compre Duas",text:"o próximo jogador pega duas cartas e perde a vez"},{label:"Despejar Tudo",text:"descarte todas as cartas da sua mão com a cor dela, embaixo dela; cartas de ação varridas não disparam"},{label:"Curinga",text:"jogue a qualquer momento e escolha a próxima cor"},{label:"Curinga Compre Quatro",text:"escolha a cor E entregue quatro cartas ao próximo jogador"},{label:"Curinga Trocar Mãos",text:"escolha a cor e troque de mão com qualquer jogador (carta opcional)"},{label:"Curinga Embaralhar Mãos",text:"junte todas as mãos, embaralhe e redistribua (carta opcional)"}]},{heading:"Última carta",body:['Ficou com duas cartas? Aperte "Última carta!" antes de jogar. Chegue a uma carta sem avisar e você é pego — compre duas.',"Comprar coloca você de volta acima da linha, então o aviso precisa ser feito de novo."]},{heading:"Os relógios",body:["Toda vez é cronometrada. Se o relógio zerar, a mesa faz uma jogada válida por aquele jogador para a pilha não parar.","A distribuição também tem um relógio de partida. No último minuto, as posições ao vivo do primeiro ao quarto aparecem e se atualizam conforme as mãos mudam."],bullets:[{label:"No zero da partida",text:"vence quem tiver menos cartas; mãos do mesmo tamanho são decididas pela ordem dos lugares, para todo replay ter um resultado claro"},{label:"Opções avançadas",text:"defina os segundos por vez e os minutos totais da partida antes da distribuição"}]},{heading:"Caos da casa",body:["Todas as configurações da mesa ficam nas opções avançadas, antes da distribuição:"],bullets:[{label:"Acumular",text:"responda um Compre Duas / Compre Quatro com a mesma carta e a penalidade se empilha para a próxima vítima"},{label:"Invadir",text:"tem a face exata da carta que acabou de ser jogada? Jogue-a fora de vez antes que alguém reaja"},{label:"Comprar até poder jogar",text:"continue comprando até algo combinar, em vez de comprar uma só"},{label:"Jogada forçada",text:"uma carta comprada que pode ser jogada deve ser jogada"},{label:"Desafiar o Compre Quatro",text:"um Compre Quatro só é honesto sem nada da cor anterior — desmascare o blefe e ele fica com a pilha; erre e você pega mais duas"},{label:"Setes e zeros",text:"um 7 troca a sua mão com a de um jogador que você escolher; um 0 passa todas as mãos um lugar adiante"},{label:"Curingas de troca",text:"coloca o Curinga Trocar Mãos e o Curinga Embaralhar Mãos no baralho"}]},{heading:"Vencendo",body:["Esvazie a mão para vencer antes do relógio da partida zerar. Senão, a mão mais leve que restar vence no zero."]}]},modes:{classic:{name:"Clássico",tagline:"À risca",description:"Combine a cor ou o número, depois despeje uma cor inteira de uma vez. Sem acumular, sem invadir — um caos educado.",facts:["uma distribuição","sem acumular","~5 min"]},party:{name:"Festa",tagline:"Empilhe e bata",description:"Compre Duas e Compre Quatro se acumulam, e uma combinação exata deixa qualquer um invadir fora de vez. Caos, com luz quentinha.",facts:["acumular ligado","invasões ligadas","~5 min"]},houseRules:{name:"Regras da Casa",tagline:"Tudo ligado",description:"Setes trocam mãos, zeros passam tudo adiante, curingas de troca entram no baralho, e a carta que você comprou tem que ser jogada.",facts:["trocas de 7 e 0","curingas de troca","jogada forçada"]}},fields:{handSize:{label:"Cartas distribuídas",group:"A distribuição",help:"Com quantas cartas cada lugar começa."},turnTimeSeconds:{label:"Segundos por vez",group:"Tempo",help:"Quando o relógio zera, a mesa faz uma jogada válida por aquele lugar."},matchTimeMinutes:{label:"Minutos de partida",group:"Tempo",help:"No zero, vence o jogador com a mão mais leve que restar."},stackDrawTwo:{label:"Acumular Compre Duas",group:"Penalidades",help:"Responda um Compre Duas com o seu e passe a pilha crescente adiante."},stackDrawFour:{label:"Acumular Compre Quatro",group:"Penalidades",help:"O mesmo para o Compre Quatro. As penalidades podem subir rápido."},jumpIn:{label:"Invadir",group:"Regras da casa",help:"Tem a carta exata que acabou de ser jogada? Jogue-a fora de vez."},drawToMatch:{label:"Comprar até poder jogar",group:"Regras da casa",help:"Continue comprando até algo combinar, em vez de comprar uma carta só."},forcePlay:{label:"Jogada forçada",group:"Regras da casa",help:"Uma carta comprada que pode ser jogada deve ser jogada."},sevenZero:{label:"Setes e zeros",group:"Regras da casa",help:"Jogue um 7 para trocar de mão com alguém; jogue um 0 para passar todas as mãos adiante."},challengeDrawFour:{label:"Desafiar o Compre Quatro",group:"Regras da casa",help:"Um Compre Quatro só é honesto sem nada da cor em jogo. Desmascare o blefe: acerte e ele fica com as cartas, erre e você pega mais duas."},swapCards:{label:"Curingas de troca",group:"O baralho",help:"Coloca o Curinga Trocar Mãos e o Curinga Embaralhar Mãos no baralho."}},presets:{classic:"Wild Clássico",party:"Pilha de Festa",houseRules:"Regras da Casa"}},ratscrew:{name:"Rouba Monte",subtitle:"o jogo do tapa",tagline:"Bata na pilha primeiro",description:"Vire cartas numa pilha comum e bata em dobras, sanduíches e mais antes de todo mundo. Reflexos em tempo real, desafios de figuras, tapas errados que queimam cartas.",facts:["2–4 jogadores","tapas em tempo real","solo ou com amigos"],howToPlay:{summary:"Alterne virando cartas numa pilha comum e BATA até ganhar todas as cartas da mesa.",objective:"Ganhe as 52 cartas. Você aumenta seu monte batendo nos padrões primeiro ou baixando figuras que os adversários não conseguem responder. Quando todos os outros ficam sem cartas — ou voltam ao jogo com um tapa — você vence a partida.",sections:[{heading:"A virada",body:["Começando por você, os jogadores alternam colocando a carta do topo do próprio monte virado para baixo na pilha central, virando-a para o lado oposto a si para ninguém espiar.","Se o seu monte secar, você para de virar — mas com a opção de voltar com um tapa ligada, um tapa de sorte coloca você de volta no jogo."]},{heading:"Figuras e desafios",body:["Uma figura abre um desafio contra o próximo jogador na ordem do turno:"],bullets:[{label:"Valete",text:"ele tem 1 chance de virar outra figura"},{label:"Dama",text:"2 chances"},{label:"Rei",text:"3 chances"},{label:"Ás",text:"4 chances"}]},{heading:"Resolvendo um desafio",body:["Cada carta que não é figura que o desafiado vira queima uma das chances dele.","Virou uma figura nova? O desafio roda a mesa com chances novas para o próximo jogador.","Acabaram as chances? Quem baixou a figura recolhe a pilha central inteira para baixo do seu monte e puxa a próxima virada."]},{heading:"Tapas",body:["No instante em que um padrão de tapa cai na pilha, TODO MUNDO corre para bater. O primeiro tapa válido ganha a pilha central inteira e puxa a próxima.","Uma breve janela de tapa abre sempre que um padrão está valendo — esmague o botão de TAPA antes que ela feche!"],bullets:[{label:"Dobra",text:"duas cartas do mesmo valor em sequência (7♦ 7♣)"},{label:"Sanduíche",text:"mesmo valor com uma carta no meio (7♦ Q♠ 7♥)"},{label:"Casamento",text:"um Rei e uma Dama em sequência, em qualquer ordem (K♦ Q♠) — opção da casa"},{label:"Dez",text:"duas cartas de número seguidas somando dez (3♦ 7♠) — opção da casa"},{label:"Topo-fundo",text:"a carta do topo é igual à carta bem do fundo da pilha — opção da casa"},{label:"Sequência",text:"três valores seguidos subindo ou descendo (4-5-6 ou 9-8-7) — opção da casa"}]},{heading:"Tapas errados",body:["Bater quando nenhum padrão está valendo custa caro: com a queima por tapa errado ligada, a carta do topo do seu monte desliza para baixo da pilha como penalidade. Nervosismo sai caro — olho nas cartas, não na plateia."]},{heading:"Regras da casa",body:["Ajuste o caos nas configurações da sala antes de começar:"],bullets:[{label:"Dobras / Sanduíches",text:"os padrões clássicos de tapa, ambos ligados por padrão"},{label:"Casamento / Dez / Topo-fundo / Sequências",text:"padrões extras, todos desligados por padrão para uma mesa clássica"},{label:"Tapa errado queima uma carta",text:"ligado por padrão; desligue e só padrões valendo poderão ser batidos"},{label:"Voltar com um tapa",text:"jogadores sem cartas ainda podem bater num padrão valendo para ganhar a pilha e voltar ao jogo"},{label:"Janela de tapa",text:"quanto tempo a corrida fica aberta — mais curta, mais cruel"}]},{heading:"Boas maneiras na mesa",body:["Quem ganha a pilha desliza ela para baixo do próprio monte sem embaralhar e vira a próxima. O último jogador segurando todas as cartas vence a partida.","Um curto momento de tolerância mantém os tapas de longa distância honestos: a mesa espera um instante além da janela antes de dar a corrida por encerrada."]}]},modes:{classic:{name:"Tapa Clássico",tagline:"Dobras e sanduíches",description:"O padrão do boteco: vire rápido, fique de olho em dobras e sanduíches e bata antes da janela fechar.",facts:["janela de 1,2 s","tapa errado queima","~8 min"]},"quick-reflex":{name:"Reflexo Rápido",tagline:"Janelas cruéis",description:"Os mesmos padrões clássicos no gatilho — a janela de tapa fecha em 0,7 segundos.",facts:["janela de 0,7 s","para olhos afiados","~6 min"]},slaphappy:{name:"Tapa Maluco",tagline:"Todos os padrões valendo",description:"Casamentos, dez, topo-fundo e sequências contam além dos clássicos. Caos, bem iluminado, extremamente barulhento.",facts:["todos os padrões","janela de 0,8 s","~5 min"]}},fields:{doubles:{label:"Dobras"},sandwiches:{label:"Sanduíches"},marriage:{label:"Casamento (K+Q)"},tens:{label:"Cartas que somam dez"},topBottom:{label:"Topo-fundo"},runs:{label:"Sequências"},misSlapBurn:{label:"Tapa errado queima uma carta"},slapBackIn:{label:"Voltar com um tapa quando sem cartas"},slapWindowMs:{label:"Janela de tapa"}},presets:{classic:"Tapa Clássico","quick-reflex":"Reflexo Rápido",slaphappy:"Tapa Maluco"}},euchre:{name:"Euchre",subtitle:"o jogo de duplas",tagline:"Ganhe vazas pelo seu time",description:"Peça o trunfo, escolha seu naipe e corra atrás dos bowers com o jogador do outro lado da mesa. O primeiro time a chegar em dez leva a partida.",facts:["4 jogadores · 2v2","jogo de vazas","solo ou com amigos"],howToPlay:{summary:"O clássico do Meio-Oeste americano — forme sua dupla, escolha o trunfo e corra com seu time até os 10 pontos.",objective:"Sentado de frente para o seu parceiro, ganhe pelo menos três das cinco vazas de cada mão fazendo do naipe escolhido o rei da mesa. O primeiro time a chegar na pontuação alvo vence a partida.",sections:[{heading:"A mesa",body:["Quatro jogadores, dois times: você e o jogador à sua frente são parceiros. Cinco cartas para cada um; as últimas quatro cartas formam o monte reserva, com a carta de cima virada para cima."]},{heading:"Pedir — primeira rodada de apostas",body:["Começando à esquerda de quem deu as cartas, cada um aceita ou passa a carta virada:"],bullets:[{label:"Pedir",text:"aquele naipe vira trunfo, quem deu as cartas pega a carta para a mão e descarta uma virada para baixo"},{label:"Ir sozinho",text:"pega o trunfo e manda seu parceiro para o banco nesta mão"},{label:"Passar",text:"a decisão passa para a esquerda"}]},{heading:"Escolher o trunfo — segunda rodada",body:["Se os quatro passarem, a carta virada é enterrada e cada lugar pode escolher qualquer outro naipe como trunfo. O naipe recusado está fora de jogo.","Obrigar quem deu as cartas (padrão): se todos os outros passarem na segunda rodada, quem deu as cartas é obrigado a escolher um naipe."]},{heading:"Bowers",body:["Quando um naipe é escolhido, o valete dele é o bower DIREITO — a carta mais alta do jogo. O valete do naipe da mesma cor é o bower ESQUERDO, o segundo mais alto, e conta como trunfo. Então, com copas como trunfo, J♥ e depois J♦ são as duas cartas mandonas."]},{heading:"Jogando as vazas",body:["O jogador à esquerda de quem deu as cartas puxa. Você é obrigado a seguir o naipe puxado se puder — lembre-se de que o bower esquerdo pertence ao trunfo, não ao naipe impresso. A carta mais alta do naipe puxado vence a vaza, a menos que alguém corte com trunfo; o trunfo mais alto ganha de tudo. Quem vence puxa a próxima."]},{heading:"Pontuando uma mão",body:["O time que pediu é o MANDANTE. Depois das cinco vazas:"],bullets:[{label:"3 ou 4 vazas",text:"os mandantes marcam 1 ponto"},{label:"5 vazas",text:"uma marcha — os mandantes marcam 2"},{label:"Marcha sozinho",text:"as cinco vazas jogando sozinho — os mandantes marcam 4"},{label:"Euchrado!",text:"os mandantes ganham menos de três vazas — os defensores marcam 2"}]},{heading:"Ir sozinho",body:["Quem pedir com confiança de sobra pode jogar sem o parceiro, que fica de fora da mão por completo. Ganhe as cinco sozinho e vale 4 pontos — mas faça menos de três e a defesa ainda te euchra por 2."]},{heading:"Regras da casa",body:["As configurações da sala ajustam a partida: jogo até 5/10/15, obrigar quem deu as cartas ligado ou desligado e se ir sozinho é permitido. Quando todas as mãos são abandonadas sem escolha de trunfo, a distribuição simplesmente passa para a esquerda."]}]},modes:{classic:{name:"Boteco clássico",tagline:"O jogo de verdade",description:"Dez pontos, obrigar quem deu as cartas, ir sozinho. O jogo como se joga em todo salão de bombeiros e mesa de cozinha.",facts:["jogo até 10","obrigar o dealer","~20 min"]},"quick-cut":{name:"Corte rápido",tagline:"Primeiro a cinco",description:"As mesmas regras, corrida mais curta — cinco pontos e acabou. Perfeito enquanto a chaleira ainda está esquentando.",facts:["jogo até 5","~10 min"]},"long-game":{name:"Partida longa",tagline:"Acomode-se",description:"Quinze pontos para uma noite inteira de jogo. Rancores são bem-vindos.",facts:["jogo até 15","~30 min"]},"old-school":{name:"Antigamente",tagline:"Quem deu pode passar",description:"Sem obrigar quem deu as cartas — todo mundo pode passar e a distribuição segue adiante. Do jeito que alguns avôs fazem questão de jogar.",facts:["jogo até 10","sem obrigação","~20 min"]}},fields:{targetScore:{label:"Partida até",help:"A primeira dupla a chegar nesta pontuação vence a partida.",group:"Partida",options:{5:"5 — corte rápido",10:"10 — padrão",15:"15 — partida longa"}},stickDealer:{label:"Obrigar quem deu as cartas",help:"Na segunda rodada de apostas, quem deu as cartas é obrigado a escolher um naipe quando todos os outros passam.",group:"Apostas"},goingAlone:{label:"Permitir ir sozinho",help:"Quem pedir com uma mão monstruosa pode mandar o parceiro para o banco naquela mão.",group:"Apostas"}},presets:{classic:"Boteco clássico","quick-cut":"Corte rápido","long-game":"Partida longa","old-school":"Antigamente"}},hearts:{name:"Copas",subtitle:"o jogo de desviar",tagline:"Não pegue nenhuma copa",description:"Desvie de cada copa, fuja da Dama Negra e empurre os pontos para outra pessoa. Passes que giram, escolhas secretas e uma dama bem afiada.",facts:["4 jogadores","passar · vaza · desviar","solo ou com amigos"],howToPlay:{summary:"O clássico jogo de desviar — não pegue nenhuma copa, fuja da Dama Negra e deixe os pontos para os outros.",objective:"Termine a partida com a menor pontuação. Cada copa que você captura custa 1 ponto e a dama de espadas custa 13; quando um jogador passa do limite de fim de jogo (100 por padrão), o menor total vence.",sections:[{heading:"O passe",body:["Antes de cada mão, você escolhe três cartas e desliza para um vizinho — todos escolhem em segredo, e os quatro passes chegam juntos.","A direção gira a cada mão: esquerda, direita, em frente, e depois uma mão de segurar, sem passe nenhum."]},{heading:"Jogando as vazas",body:["O dois de paus puxa a primeira vaza. Siga o naipe se puder; a carta mais alta do naipe puxado leva a vaza, e quem vence puxa a próxima."],bullets:[{label:"Primeira vaza",text:"nenhuma carta de penalidade pode ser jogada nela (ajuste opcional da casa)"},{label:"Quebrar copas",text:"copas não podem puxar até que uma tenha sido descartada numa vaza anterior — a menos que a sua mão seja só de copas"},{label:"Sem o naipe",text:"ficou sem o naipe puxado? Jogue qualquer coisa — é aqui que a dama cai em cima de alguém"}]},{heading:"Pontuando uma mão",body:["Quando as treze vazas terminam, cada copa que você capturou vale 1 ponto e a dama de espadas vale 13."],bullets:[{label:"Valete de ouros",text:"regra opcional da casa — vale −10 para quem o capturar"},{label:"Dar a volta na lua",text:"capture TODAS as treze copas mais a dama e você marca zero enquanto todo mundo leva +26 — ou, com a outra regra da casa, a sua própria pontuação cai 26"}]},{heading:"A partida",body:["As mãos se acumulam até alguém cruzar a linha de fim de jogo (50 / 75 / 100). O menor total vence a partida; empates dividem a coroa."]},{heading:"Regras da casa",body:["As configurações da sala ajustam tudo: direção do passe, mãos de segurar, proteção da primeira vaza, o valete de ouros, o limite de fim de jogo e a virada da lua. Mesas clássicas mantêm os padrões."]}]},modes:{classic:{name:"Clássico",tagline:"À risca",description:"Passes girando esquerda-direita-em frente, uma mão de segurar a cada quatro distribuições, sem pontos na primeira vaza. Partida até 100.",facts:["partida até 100","mãos de segurar ligadas","~15 min"]},quickcut:{name:"Corte Rápido",tagline:"As mesmas copas, mais rápido",description:"Regras idênticas, teto mais baixo — o primeiro a passar de 50 encerra. Uma partida inteira no cafezinho.",facts:["partida até 50","mãos de segurar ligadas","~8 min"]},cutthroat:{name:"Vale-Tudo",tagline:"O valete está solto",description:"O valete de ouros vale −10 para quem o capturar, e cartas de penalidade voam já na primeira vaza. Ninguém está seguro.",facts:["J♦ −10","pontos na primeira vaza","partida até 100"]}},fields:{passDirection:{label:"Passe",options:{left:"Esquerda",right:"Direita",across:"Em frente",hold:"Segurar (sem passe)"}},holdHand:{label:"Mão de segurar a cada quatro distribuições"},noPointsFirstTrick:{label:"Sem cartas de penalidade na primeira vaza"},jackDiamonds:{label:"Valete de ouros vale −10"},gameOver:{label:"O jogo termina em",options:{50:"50 pontos",75:"75 pontos",100:"100 pontos"}},moonShift:{label:"Dar a volta na lua",options:{opponents:"+26 para todo mundo",self:"−26 da sua própria pontuação"}}},presets:{classic:"Copas Clássico",quickcut:"Corte Rápido",cutthroat:"Vale-Tudo"}},gin:{name:"Gin",subtitle:"o clássico do rummy",tagline:"Combine, bata, vença a noite",description:"Dez cartas, duas cadeiras. Monte trincas e sequências, livre-se das cartas mortas e bata na mesa antes do seu adversário.",facts:["2 jogadores","bater · gin · big gin","solo ou com amigos"],howToPlay:{summary:"O clássico para dois — compre, descarte e combine até chegar numa mão digna de batida.",objective:"Transforme suas dez cartas em trincas e sequências para que quase nada sobre, e bata antes do seu adversário. O primeiro a passar do alvo da partida vence.",sections:[{heading:"Combinações e cartas mortas",body:["Uma combinação é uma trinca ou quadra de mesmo valor, ou três ou mais cartas do mesmo naipe em sequência. O ás vale só como baixo (A-2-3, nunca Q-K-A).","Tudo que não está numa combinação é carta morta, contada pelo valor de face, com as figuras valendo dez e os ases um. Quanto menos, melhor."]},{heading:"Seu turno",body:["Dois passos, todo turno:"],bullets:[{label:"Comprar",text:"pegue a carta do topo do monte, ou a do topo do descarte"},{label:"Descartar",text:"deslize uma carta virada para cima sobre o descarte — nunca a carta que você comprou neste turno, de nenhum dos montes"}]},{heading:"A carta virada inicial",body:["Depois da distribuição, uma carta fica virada para cima. Quem não deu as cartas pode pegá-la para a mão ou passar; depois, quem deu tem a mesma escolha. Se os dois passarem, quem não deu compra do monte e o jogo começa."]},{heading:"Bater",body:["Em vez de descartar, você pode bater quando suas cartas mortas estiverem no limite de batida ou abaixo dele (10 por padrão). Isso encerra a mão na hora — sem descarte. Comprar uma décima primeira carta antes abre a linha do big gin, se tudo combinar."]},{heading:"Gin e encaixes",body:["Zero cartas mortas é gin — o defensor não pode encaixar nada e paga todas as suas cartas mortas mais o bônus de gin.","Numa batida simples, o defensor encaixa primeiro: qualquer carta morta dele que estenda uma trinca do batedor para uma quadra ou alongue uma sequência nas duas pontas sai da conta antes da comparação.","Se as cartas mortas do defensor terminarem iguais ou menores que as suas, isso é um undercut — ele leva a diferença mais um bônus no seu lugar."]},{heading:"Pontuação e a partida",body:["As mãos continuam até alguém passar do alvo da partida (100 por padrão), alternando quem dá as cartas a cada mão."],bullets:[{label:"Batida",text:"diferença entre as cartas mortas"},{label:"Undercut",text:"diferença + 25 para o defensor"},{label:"Gin",text:"todas as cartas mortas do defensor + 25"},{label:"Big gin",text:"onze cartas todas combinadas — cartas mortas do defensor + 31 (opcional)"},{label:"Bônus de caixa",text:"opcional: +25 por mão vencida, somado no final (opcional)"}]},{heading:"Regras da casa",body:["Toda mesa pode ser ajustada nas configurações da sala:"],bullets:[{label:"Limite de batida",text:"o quão baixo você precisa estar para bater — limites mais apertados fazem as mãos durarem mais"},{label:"Alvo da partida",text:"50 para um jogo rápido, 100 clássico, mais para os maratonistas"},{label:"Big gin / bônus / bônus de caixa",text:"os botões do prêmio"}]},{heading:"Mãos mortas",body:["Se o monte chegar a duas cartas, a mão morre — sem pontos, quem deu as cartas distribui de novo. Bata mais cedo."]}]},modes:{classic:{name:"Clássico",tagline:"Direto até 100",description:"O padrão de boteco — bata com dez cartas mortas ou menos, gin paga 25, big gin paga 31. O primeiro a passar de 100 leva.",facts:["batida até 10","partida até 100","~15 min"]},quick:{name:"Rápida",tagline:"Corrida até 50",description:"As mesmas regras, escada mais curta. Um duelo rapidinho para o café.",facts:["partida até 50","~8 min"]},purist:{name:"Purista",tagline:"Sem frescura",description:"Big gin fora e bônus de caixa em casa. Batidas puras, cartas mortas puras, sem rede de proteção.",facts:["sem big gin","sem bônus de caixa"]}},fields:{knockCap:{label:"Limite de batida",help:"O máximo de cartas mortas com que você pode bater",group:"Mesa"},matchTarget:{label:"Partida até",help:"O primeiro a passar desta pontuação vence a partida",group:"Mesa"},ginBonus:{label:"Bônus de gin",group:"Bônus"},bigGin:{label:"Big gin",help:"Compre uma décima primeira carta que combine por completo",group:"Bônus"},bigGinBonus:{label:"Bônus de big gin",group:"Bônus"},boxBonus:{label:"Bônus de caixa",help:"+25 por mão vencida, somado ao total final",group:"Bônus"}},presets:{classic:"Clássico",quick:"Rápida",purist:"Purista"}},president:{name:"Presidente",subtitle:"o jogo de subir na vida",tagline:"Suba até a coroa",description:"Cubra a pilha com um jogo maior, esvazie a mão primeiro e suba de Mico a Presidente. Até oito lugares, com coroas e ferroadas incluídas.",facts:["4–8 jogadores","papéis e trocas","solo ou com amigos"],howToPlay:{summary:"O clássico jogo de subir na vida — esvazie a mão primeiro, suba a escada de Mico a Presidente e faça os rivais servirem cartas para você.",objective:"Termine cada rodada no melhor lugar que puder. O primeiro a sair é Presidente, o último é Mico. Os pontos de posição acumulam entre as rodadas; o primeiro a chegar ao total alvo vence a partida.",sections:[{heading:"Jogando na pilha",body:["Quem puxa abre a vaza com qualquer jogo — uma carta sozinha, um par, uma trinca ou uma quadra do mesmo valor.","Em sentido horário, cada jogador precisa cobrir a pilha com o MESMO tamanho de jogo em um valor estritamente maior, ou passar."],bullets:[{label:"Ordem dos valores",text:"o 3 é o mais baixo, subindo até o A, com o 2 acima de tudo"},{label:"Passar",text:"passar só pula esta vez — se alguém cobrir a pilha mais adiante na vaza, você volta ao jogo (a menos que a regra da casa de passe travado esteja ligada)"},{label:"Vencer a vaza",text:"quando todos os outros passam, a pilha é varrida e o vencedor puxa o que quiser"},{label:"O 2 limpa",text:"um 2 sozinho vence a pilha na hora e mantém a puxada — regra da casa, ligada por padrão"}]},{heading:"Terminando a rodada",body:["Ficou sem cartas? Você garante o próximo degrau da escada. O jogo continua até sobrar um único jogador com cartas na mão — o Mico.","O primeiro a sair é Presidente, o segundo é Vice-Presidente, o penúltimo é Vice-Mico e o último lugar é Mico."]},{heading:"Pontuação e a partida",body:["Cada rodada guarda pontos de posição: o Presidente marca tantos pontos quantos forem os lugares, o segundo colocado um a menos, e assim por diante até um único ponto para o Mico.","A partida termina no momento em que alguém alcança o alvo — vence o maior total acumulado, e empates dividem a coroa."]},{heading:"A troca",body:["Antes da próxima rodada, os lugares de baixo pagam tributo das mãos recém-distribuídas e os lugares de alto devolvem o que escolherem:"],bullets:[{label:"Mico → Presidente",text:"as duas melhores cartas do Mico; o Presidente devolve duas quaisquer"},{label:"Vice-Mico → Vice-Presidente",text:"uma carta em cada direção"},{label:"Opção desligada",text:"desligue as trocas nas configurações da sala para um cada-um-por-si mais puro"}]},{heading:"Regras da casa",body:["Ajuste a mesa nas configurações da sala antes de começar:"],bullets:[{label:"O 2 limpa a pilha",text:"ligado por padrão — desligado, o 2 é só mais uma carta imbatível"},{label:"Passes travados",text:"depois de passar, você fica de fora da vaza inteira (desligado por padrão: você volta quando a pilha muda)"},{label:"Trocas",text:"a troca de cartas por papel entre as rodadas"},{label:"Pontos alvo",text:"o tamanho da partida — 7 para uma partidinha, 11 para uma sessão, 21 para uma maratona"}]},{heading:"Etiqueta da mesa",body:["A primeira rodada começa pelo lugar inicial; depois disso, o Presidente sentado puxa todas as rodadas.","As cartas são distribuídas uma a uma até o baralho acabar, então mesas ímpares deixam alguns lugares com uma carta a menos — todo mundo no mesmo barco."]}]},modes:{classic:{name:"Clássico",tagline:"A escada inteira",description:"Coroas, tributos e viradas — o primeiro a onze pontos leva o salão. Do jeito que se joga no boteco.",facts:["primeiro a 11","trocas ligadas","o 2 limpa"]},rapid:{name:"Rápida",tagline:"Curta e apimentada",description:"O primeiro a sete mantém a mesa andando. As mesmas regras, menos rodadas, viradas mais barulhentas.",facts:["primeiro a 7","~10 min","ótimo com 6+"]},marathon:{name:"Maratona",tagline:"Reinados longos",description:"Vinte e um pontos de política. Micos viram presidentes, dinastias nascem e caem.",facts:["primeiro a 21","sessão longa","arco completo"]}},fields:{twoClears:{label:"O 2 limpa a pilha"},passLocks:{label:"Passar tira você da vaza"},trading:{label:"Troca de cartas por papel entre rodadas"},targetPoints:{label:"Primeiro a (pontos)"}},presets:{classic:"Salão Clássico",rapid:"Gabinete Rápido",marathon:"Maratona"}},spades:{name:"Espadas",subtitle:"o jogo de duplas",tagline:"Aposte suas vazas",description:"Sente de frente para o seu parceiro, diga um número e ganhe essa quantidade de vazas — nem a mais, nem a menos se puder evitar. Espadas são sempre trunfo. As sobras vão te achar.",facts:["4 jogadores · 2v2","aposta · trunfo · sobras","solo ou com amigos"],howToPlay:{summary:"O clássico americano de duplas — aposte suas vazas, corte com espadas e corra até os 500.",objective:"Sentado de frente para o seu parceiro, ganhe pelo menos tantas vazas quanto vocês apostarem juntos. O primeiro time a chegar na pontuação alvo (500 por padrão) vence; um empate na linha ou acima dela joga mais uma mão.",sections:[{heading:"A mesa",body:["Quatro jogadores, dois times: você e o jogador à sua frente são parceiros. Cada mão distribui o baralho inteiro de 52 cartas — treze cartas para cada um. Tanto a distribuição quanto a primeira aposta começam à esquerda de quem dá as cartas e seguem no sentido horário."]},{heading:"As apostas",body:["Cada lugar diz um número, uma única vez. Não existe passar nem apostar de novo. O contrato do seu time é a soma das duas apostas que não são nulo."],bullets:[{label:"1–13",text:"quantas vazas você espera ganhar"},{label:"Nulo",text:"uma aposta à parte — não ganhe nenhuma vaza e leve +100, ou −100 se ganhar alguma. As vazas de um nulo furado não ajudam o seu parceiro a cumprir o contrato, mas cada uma ainda conta como sobra"}]},{heading:"Jogando as vazas",body:["O jogador à esquerda de quem deu as cartas puxa a primeira vaza. Siga o naipe se puder; vence a espada mais alta, ou, se não houver, a carta mais alta do naipe puxado. Quem vence a vaza puxa a próxima."],bullets:[{label:"Quebrando espadas",text:"não se pode puxar com espada até que alguém tenha descartado uma por estar sem o naipe — a não ser que só sobrem espadas na sua mão"},{label:"Sem o naipe",text:"acabou o naipe puxado? Jogue o que quiser, inclusive um trunfo"}]},{heading:"Pontuando uma mão",body:["Se os lugares do time que não apostaram nulo ganharem pelo menos o contrato, o time marca 10 pontos por vaza apostada mais 1 por cada vaza a mais. Se vocês ficarem abaixo, o contrato custa −10 por vaza apostada."],bullets:[{label:"Sobras",text:"as vazas a mais (e as vazas de um nulo furado) são sobras. Elas acumulam de mão em mão; a cada dez sobras você perde 100 pontos e o que restar fica na conta"},{label:"Nulo",text:"pontuado à parte, somado ao resultado do contrato do parceiro"}]},{heading:"A partida",body:["As mãos se acumulam até um time alcançar o alvo (250 / 500 / 750). Vence a maior pontuação; se os dois times terminarem com o mesmo total na linha ou acima dela, distribui-se mais uma mão."]},{heading:"Regras da casa",body:["As configurações da sala mexem em apenas três coisas: a pontuação alvo, se o nulo é permitido e se as sobras contam. As mesas clássicas mantêm os padrões. Nulo às cegas não é oferecido."]}]},modes:{classic:{name:"Clássico",tagline:"Pela cartilha",description:"Espadas de duplas até 500, com nulo e com sobras. O jogo como se joga em qualquer mesa de cozinha.",facts:["partida até 500","nulo · sobras","~25 min"]},quick:{name:"Rápida",tagline:"Primeiro a 250",description:"As mesmas regras, corrida mais curta — 250 pontos e acabou. Uma partida inteira na hora do almoço.",facts:["partida até 250","nulo · sobras","~12 min"]},"clean-books":{name:"Vazas limpas",tagline:"Sem sobras",description:"Cumpra sua aposta ou estoure — as vazas a mais não são sobras e não valem ponto. Precisão acima de volume.",facts:["partida até 500","nulo ativado","sobras desativadas"]}},fields:{targetScore:{label:"Partida até",help:"Depois de cada mão, o time mais alto na linha ou acima desta pontuação vence. Se empatar, joga-se mais uma mão.",group:"Partida",options:{250:"250 — corte rápido",500:"500 — padrão",750:"750 — partida longa"}},nil:{label:"Permitir nulo",help:"Uma aposta de zero é nulo: não ganhe nenhuma vaza e leve +100, ou −100 se ganhar alguma. As vazas de um nulo furado não ajudam no contrato do parceiro.",group:"Apostas"},bags:{label:"Contar sobras",help:"As vazas a mais e as vazas de um nulo furado são sobras. A cada dez sobras você perde 100 pontos; o que sobrar fica na conta.",group:"Pontuação"}},presets:{classic:"Clássico",quick:"Rápida","clean-books":"Vazas limpas"}},poker:{name:"Poker",subtitle:"hold’em sem limite",tagline:"A última pilha em pé",description:"Duas cartas só suas, cinco no meio da mesa e todas as suas fichas para dizer o quanto você acredita nelas. Os blinds sobem até alguém ficar com tudo.",facts:["2–6 jogadores","hold’em sem limite","fichas só de brincadeira"],howToPlay:{summary:"Texas hold’em sem limite em formato sit-and-go — todo mundo começa igual, os blinds sobem e vence quem ficar com a última ficha.",objective:"Ganhe todas as fichas. A cada mão você recebe duas cartas só suas e divide cinco no meio da mesa; a melhor mão de cinco cartas leva o pote, e quem ficar sem fichas está fora da partida.",sections:[{heading:"As fichas",body:["As fichas são só o placar, não uma aposta — não há nada para comprar nem para sacar. Todo mundo começa com a mesma pilha, e a partida acaba quando um jogador tem todas elas."]},{heading:"Uma mão",body:["Duas cartas fechadas para cada lugar, depois uma rodada de apostas. Três cartas comunitárias (o flop), uma rodada. Uma quarta (o turn), uma rodada. Uma quinta (o river), a última rodada. Quem ainda estiver na mão mostra as cartas, e as melhores cinco entre as sete disponíveis vencem."],bullets:[{label:"O botão",text:"marca o dealer e anda um lugar para a esquerda a cada mão"},{label:"Blinds",text:"os dois lugares à esquerda do botão colocam fichas antes de saírem as cartas, para sempre haver algo em jogo"}]},{heading:"Sua vez",body:["Quando a ação chega em você, só existem quatro coisas a fazer."],bullets:[{label:"Correr (fold)",text:"desistir da mão e de tudo o que você já colocou"},{label:"Mesa (check)",text:"continuar sem colocar fichas — só quando não há nada a pagar"},{label:"Pagar (call)",text:"igualar a aposta atual"},{label:"Apostar / aumentar",text:"colocar mais, e todos os outros precisam igualar para continuar. Um aumento deve ser pelo menos do tamanho do último — a menos que você esteja apostando tudo o que resta"}]},{heading:"All in",body:["Você nunca pode perder mais do que tem na sua frente. Apostar sua última ficha é ir de all in: você fica na mão até o fim, e qualquer aposta maior que a sua pilha forma um pote paralelo que você não pode ganhar nem perder."]},{heading:"Valor das mãos",body:["Da melhor para a pior. Empates são decididos pela próxima carta mais alta, e um empate de verdade divide o pote."],bullets:[{label:"Straight flush",text:"cinco em sequência, do mesmo naipe — com o ás no topo é um royal flush"},{label:"Quadra",text:"as quatro cartas do mesmo valor"},{label:"Full house",text:"três de um valor e duas de outro"},{label:"Flush",text:"cinco do mesmo naipe"},{label:"Sequência",text:"cinco em sequência — o ás vale como a mais alta ou a mais baixa"},{label:"Trinca",text:"três do mesmo valor"},{label:"Dois pares",text:"duas de um valor e duas de outro"},{label:"Par",text:"duas do mesmo valor"},{label:"Carta alta",text:"nada disso"}]},{heading:"A partida",body:["Os blinds sobem num cronograma, então correr para sempre não é um plano — a partida sempre termina. Estourou, está fora; vence o último jogador com fichas, e todo o resto fica classificado na ordem em que caiu."]},{heading:"Regras da casa",body:["As configurações da sala escolhem a pilha inicial, a velocidade com que os blinds sobem, se o big blind paga um ante pela mesa a partir do terceiro nível e se as mãos derrotadas são viradas no showdown ou descartadas fechadas."]}]},modes:{classic:{name:"Clássico",tagline:"A mesa completa",description:"Três mil fichas para cada um e blinds que sobem a cada oito mãos. Espaço para jogar uma mão até o fim antes de alguém se comprometer.",facts:["3.000 fichas","blinds a cada 8","~25 min"]},turbo:{name:"Turbo",tagline:"All in ou vá para casa",description:"Pilhas curtas e blinds que dobram a cada quatro mãos. Ninguém pode ficar esperando por ases.",facts:["1.500 fichas","blinds a cada 4","~10 min"]},deep:{name:"Deep Stack",tagline:"Jogue o jogador",description:"Seis mil fichas e uma escada lenta, sem ante. O jogo longo, onde posição e paciência valem alguma coisa.",facts:["6.000 fichas","blinds a cada 12","sem ante"]}},fields:{startingStack:{label:"Pilha inicial",help:"Fichas com que cada lugar começa. Pilhas mais fundas dão mais jogo depois do flop antes de alguém se comprometer.",group:"Partida",options:{1500:"1.500 — curta",3e3:"3.000 — padrão",6e3:"6.000 — funda"}},blindSpeed:{label:"Blinds sobem",help:"Os blinds sobem num cronograma para a partida sempre terminar. O turbo força a ação cedo.",group:"Partida",options:{slow:"Lento — a cada 12 mãos",standard:"Padrão — a cada 8 mãos",turbo:"Turbo — a cada 4 mãos"}},ante:{label:"Ante da mesa",help:"A partir do terceiro nível, o big blind paga um blind extra por toda a mesa, para sempre haver algo valendo a pena levar.",group:"Apostas"},showMucked:{label:"Mostrar mãos perdedoras",help:"Desligado, uma mão derrotada é descartada fechada, como seria numa mesa de verdade. Ligado, todo mundo vê cada mão que chegou ao river.",group:"Showdown"}},presets:{classic:"Clássico",turbo:"Turbo",deep:"Deep Stack"}},ohhell:{name:"Oh Hell",subtitle:"o jogo das apostas",tagline:"Diga suas vazas. Faça exatamente isso.",description:"As mãos crescem e encolhem a cada rodada enquanto você aposta o número exato de vazas que vai fazer. A regra do gancho garante que alguém vai errar — garanta que não seja você.",facts:["3–7 jogadores","aposta · trunfo · exato","solo ou com amigos"],howToPlay:{summary:"Aposte o número exato de vazas que você vai fazer — nem mais, nem menos. O baralho encolhe e cresce a cada rodada até alguém superar a mesa nas apostas.",objective:"Ao longo de uma partida de mãos que crescem e depois encolhem, pontue mais que todo mundo acertando sua aposta em cheio. Um jogador está matematicamente condenado a cada rodada — tente não ser esse jogador.",sections:[{heading:"A mesa",body:["De três a sete jogadores, cada um por si. Uma partida é uma sequência de rodadas; a primeira distribui uma carta para cada um, depois as mãos crescem até um pico (limitado para sempre sobrar uma carta de trunfo) e voltam até uma. A distribuição gira no sentido horário a cada rodada."]},{heading:"A virada",body:["Depois da distribuição, a próxima carta do monte é virada para cima — o naipe dela é o trunfo da rodada."],bullets:[{label:"Sem carta sobrando",text:"quando a distribuição usa o baralho inteiro não há o que virar, e a rodada é jogada sem trunfo"},{label:"Cortar o trunfo",text:"mesas com “cortar o trunfo” ativado encolhem a rodada de baralho cheio em uma carta, para ainda dar para cortar um trunfo do fundo"}]},{heading:"As apostas",body:["Começando à esquerda do dealer e seguindo no sentido horário, cada lugar diz um número de 0 até o tamanho da sua mão: exatamente quantas vazas afirma que vai fazer. Não existe passar nem pedir de novo."],bullets:[{label:"A regra do gancho",text:"o dealer aposta por ÚLTIMO e não pode fazer o total das apostas igualar as vazas disponíveis — um jogador nesta mesa tem certeza de que vai errar. A aposta proibida simplesmente não aparece no seu seletor"},{label:"Zero",text:"uma aposta válida como qualquer outra: não fazer vaza nenhuma"}]},{heading:"Jogando as vazas",body:["Quem está à esquerda do dealer puxa a primeira vaza. Siga o naipe se puder; vence o trunfo mais alto, senão a carta mais alta do naipe puxado. Quem ganha a vaza puxa a próxima."]},{heading:"Pontuando uma rodada",body:["Acerte sua aposta EXATAMENTE ou não pontue nada (padrão). Os pontos da rodada de cada lugar entram no total acumulado; depois da última rodada do arco, o maior total vence."],bullets:[{label:"Só exato",text:"acertar em cheio vale 10 + a aposta; qualquer outra coisa vale 0"},{label:"Penalidade",text:"acertar em cheio vale 10 + a aposta; errar custa menos o tamanho do seu erro"},{label:"Mais um",text:"acertar em cheio vale o dobro da aposta; qualquer outra coisa vale 0"}]},{heading:"Variante Wizard",body:["Com Magos e Bobos ativados, quatro Magos e quatro Bobos entram no baralho (60 cartas) e entortam a ordem normal das coisas."],bullets:[{label:"Mago",text:"ganha de tudo; o PRIMEIRO Mago jogado leva a vaza. Puxar com um deixa a vaza sem naipe puxado — qualquer um pode jogar qualquer coisa"},{label:"Bobo",text:"perde para tudo; se todas as cartas da vaza forem Bobos, a primeira vence. Puxar com um passa o naipe puxado para a próxima carta de verdade"},{label:"Virada de trunfo",text:"um Mago virado deixa o DEALER escolher o trunfo; um Bobo virado significa rodada sem trunfo"}]}]},modes:{classic:{name:"Clássico",tagline:"Sobe e desce",description:"O arco clássico — uma carta, crescendo até o pico, de volta até uma. Regra do gancho ligada, só apostas exatas. Alguém erra a cada rodada; tomara que não seja você.",facts:["mãos 1…pico…1","regra do gancho","~20 min"]},quick:{name:"Rápida",tagline:"Distribui grande, encolhe rápido",description:"Começa com cinco cartas e desce direto até uma. Uma partida inteira em dez minutos, só nervo e sem enrolação.",facts:["mãos 5→1","~10 min"]},wizard:{name:"Wizard",tagline:"Sessenta cartas, quatro certezas",description:"Quatro Magos sempre vencem e quatro Bobos nunca vencem. O naipe puxado entorta em volta deles e o dealer às vezes escolhe o trunfo. Caos, formalizado.",facts:["baralho de 60 cartas","magos ativados"]}},fields:{handSize:{label:"Cartas na mão",help:"Cartas distribuídas a cada jogador nesta rodada. Uma partida completa define isso automaticamente a cada rodada.",group:"Partida"},dealer:{label:"Lugar do dealer",help:"Lugar que distribui nesta rodada e aposta por último. Uma partida completa gira a distribuição a cada rodada.",group:"Partida"},handArc:{label:"Arco das mãos",help:"Como os tamanhos de mão se movem ao longo da partida: sobem e descem, só sobem, ou distribuem grande e encolhem.",group:"Partida",options:{updown:"Sobe e desce — 1…pico…1",up:"Só sobe — 1…pico",down:"Só desce — pico…1"}},maxHand:{label:"Maior mão",help:"O arco nunca distribui mais do que isso — limitado para toda rodada guardar uma carta para virar o trunfo.",group:"Partida"},hookRule:{label:"Regra do gancho",help:"Sacaneia o dealer: a última aposta não pode fazer o total ficar exatamente igual às vazas disponíveis, então alguém sempre erra.",group:"Apostas"},scoring:{label:"Pontuação",help:"Acerte sua aposta em cheio para pontuar. Os esquemas diferem no que um erro custa.",group:"Pontuação",options:{exactOnly:"Só exato — 10 + a aposta ou nada",penalty:"Penalidade — erre por n, perca n",plusOne:"Mais um — o dobro da aposta ao acertar"}},wizards:{label:"Magos e Bobos",help:"Adiciona quatro Magos (sempre vencem) e quatro Bobos (sempre perdem) — um baralho de 60 cartas.",group:"Avançado"},trumpOnLastRound:{label:"Cortar trunfo nas rodadas de baralho cheio",help:"Quando uma rodada distribuiria o baralho inteiro, corta um trunfo do fundo primeiro (as mãos encolhem em uma) em vez de jogar sem trunfo.",group:"Avançado"}},presets:{classic:"Clássico",quick:"Rápida",wizard:"Wizard"}},scopa:{name:"Scopa",subtitle:"o jogo da pescaria",tagline:"Varra a mesa",description:"Capture cartas da mesa combinando ou somando valores, junte as moedas douradas e cace o settebello. Limpe a mesa inteira e grite scopa — a palavra mais doce dos salões de cartas italianos.",facts:["2–6 jogadores","captura · somas","solo ou com amigos"],howToPlay:{summary:"O clássico italiano da pescaria — capture cartas da mesa e varra tudo para fazer uma scopa.",objective:"Capture cartas da mesa combinando ou somando os valores delas. Mais cartas, mais ouros, o settebello, a primiera e cada scopa valem um ponto; o primeiro a chegar ao alvo (11 por padrão) vence a partida.",sections:[{heading:"A mesa",body:["Scopa se joga com um baralho italiano de 40 cartas: Denari (ouros), Coppe (copas), Spade (espadas) e Bastoni (paus), valores de 1 a 10. Podem jogar dois, três, quatro ou seis — com quatro e seis você joga em duplas fixas, com os lugares alternados ao redor da mesa.","Cada distribuição dá três cartas a cada jogador e coloca quatro viradas para cima na mesa. Se três ou mais Reis aparecerem na mesa de abertura, o baralho é reembaralhado e distribuído de novo."]},{heading:"Capturando",body:["Na sua vez, jogue exatamente uma carta da sua mão. As cartas capturam só pelo número — o naipe nunca importa."],bullets:[{label:"Combinar",text:"sua carta leva uma única carta da mesa do mesmo valor: um 5 leva um 5"},{label:"Escolher",text:"se duas cartas da mesa tiverem esse valor, você escolhe qual levar — escolha bem, o que sobra importa"},{label:"Somar",text:"sua carta pode levar duas ou mais cartas da mesa que somem o valor dela: um 8 leva um 3 e um 5. Mas se existir uma combinação de uma carta só, você DEVE levá-la — somas são só para quando não há combinação na mesa"},{label:"Largar",text:"nada combina? Sua carta fica na mesa, virada para cima e à disposição de todos"}]},{heading:"Scopa",body:["Varra todas as cartas restantes da mesa numa única captura e você fez uma scopa: um ponto, marcado na hora. Uma scopa na última carta da última distribuição não conta — essas cartas são varridas de qualquer jeito. Quando as mãos esvaziam, três cartas novas são distribuídas a cada jogador; a mesa nunca é reposta. Quando o baralho acaba, o último jogador que capturou varre as cartas que sobraram na mesa, e essa varredura não é scopa."]},{heading:"Pontuando uma rodada",body:["Depois da última distribuição, quatro pontos são divididos, mais as scope que foram feitas. Em mesas de duplas, as capturas dos times são somadas antes da pontuação."],bullets:[{label:"Carte",text:"mais cartas capturadas — 21 ou mais das 40 no jogo de dois; empate não pontua ninguém"},{label:"Denari",text:"mais ouros capturados — 6 ou mais dos 10; empate não pontua ninguém"},{label:"Settebello",text:"quem capturou o belo 7 de ouros marca 1, sempre"},{label:"Primiera",text:"a melhor carta de cada naipe somada — o 7 vale 21, o 6 vale 18, o Ás 16, 5→15, 4→14, 3→13, 2→12 e as figuras só 10. Sem nenhuma carta de algum naipe, você não pode vencer. O maior total leva 1 ponto; empates não pontuam ninguém"},{label:"Scope",text:"um ponto cada, já guardadas durante o jogo"}]},{heading:"A partida",body:["As rodadas se repetem — o dealer anda para a esquerda a cada vez — até alguém cruzar a pontuação alvo. Se os dois lados chegarem empatados na linha, outra rodada decide."]},{heading:"Regras da casa",body:["As configurações da sala expõem os botões clássicos: o alvo (11/16/21), Scopone (baralho inteiro distribuído, sem monte), Napola (bônus pela sequência de ouros), Re di denari (bônus pelo Rei de ouros) e a exibição com naipes franceses, que é puramente visual."]}]},modes:{classic:{name:"Clássico",tagline:"Primeiro a 11",description:"Scopa como se joga em todo bar italiano: três cartas por vez, quatro pontos por rodada, primeiro a onze.",facts:["partida a 11","distribuições de 3 cartas","~20 min"]},lungo:{name:"Lungo",tagline:"O jogo longo",description:"As mesmas regras, corrida até vinte e um. Espaço para viradas, desafetos e scope lendárias.",facts:["partida a 21","distribuições de 3 cartas","~40 min"]},scopone:{name:"Scopone",tagline:"Baralho inteiro, sem piedade",description:"O clássico de quatro da velha guarda: dez cartas para cada um, distribuídas de uma vez, sem monte, nada escondido. Toda captura é um compromisso.",facts:["4 jogadores · 2v2","baralho inteiro","~30 min"]}},fields:{target:{label:"Partida a",help:"Depois de cada rodada, a maior pontuação na linha ou acima dela vence. Empate na linha distribui outra rodada.",group:"Partida",options:{11:"11 — clássico",16:"16 — longo",21:"21 — lungo"}},scopone:{label:"Scopone",help:"O clássico de quatro da velha guarda: o baralho inteiro é distribuído de uma vez e não há monte para puxar. Capturar fica bem mais apertado.",group:"Distribuição"},napola:{label:"Napola",help:"Tenha o Ás, o 2 e o 3 de ouros para 3 pontos de bônus, mais 1 para cada carta de ouros que continuar a sequência (4, 5, …).",group:"Pontuação"},reDenari:{label:"Re di denari",help:"Um ponto de bônus para quem capturar o Rei de ouros.",group:"Pontuação"},frenchSuits:{label:"Exibição com naipes franceses",help:"Mostra denari/coppe/spade como ouros/copas/espadas para a arte de cartas padrão renderizar. Puramente visual — os ids e as regras continuam italianos.",group:"Mesa"}},presets:{classic:"Clássico",lungo:"Lungo","scopone-preset":"Scopone"}},spite:{name:"Spite & Malice",subtitle:"a corrida da pilha de pagamento",tagline:"Devolva na mesma moeda",description:"Monte as pilhas centrais do ás à dama, esvazie a sua pilha de pagamento e arruine os planos dos outros com curingas na hora certa. O nome já diz as regras.",facts:["2–4 jogadores","clássico · rápido · impiedoso","sozinho ou com amigos"],howToPlay:{summary:"Spite & Malice — monte as pilhas centrais do ás à dama e esvazie a sua pilha de pagamento antes de todo mundo.",objective:"Seja o primeiro jogador a esvaziar a pilha de pagamento. Cada carta que você enterra nela é uma carta que os outros adoram comemorar.",sections:[{heading:"A mesa",body:["Quatro tipos de carta, quatro lugares para colocá-las:"],bullets:[{label:"Pilha de pagamento",text:"sua pilha de objetivo, virada para baixo; a carta do topo fica virada para cima"},{label:"Mão",text:"cinco cartas, repostas até cinco no começo do seu turno"},{label:"Pilhas de descarte",text:"quatro pilhas suas — encerrar o turno significa descartar em uma delas"},{label:"Pilhas centrais",text:"até quatro sequências compartilhadas em que todo mundo joga"}]},{heading:"Seu turno",body:["Primeiro, compre até voltar a ter cinco cartas. Depois faça quantas jogadas quiser, na ordem que preferir:","jogue em uma pilha central, jogue o topo da sua pilha de pagamento ou jogue o topo de uma das suas pilhas de descarte.","Seu turno só termina quando você descarta uma carta da mão em uma das suas pilhas de descarte."]},{heading:"Montando as pilhas",body:["Uma pilha central começa com um ás e sobe valor por valor até a dama. O naipe nunca importa.","Complete uma pilha até a dama e ela inteira volta para o monte de compra — a pilha recomeça vazia, esperando um ás ou um curinga."]},{heading:"Curingas",bullets:[{label:"Curingas",text:"dezoito no baralho — jogue um como qualquer valor que precisar, e esse valor fica valendo para a pilha"},{label:"Valores lembrados",text:"um curinga valendo 6 faz a próxima carta ser um 7, jogue quem jogar"}]},{heading:"A pilha de pagamento",body:["Jogar o topo da sua pilha de pagamento vira a próxima carta na hora — e se era a última, você ganha ali mesmo, no meio do turno, sem precisar descartar.","Travado, sem nada para jogar? Descarte com intenção: o que você guarda agora é uma jogada que pode destravar depois."]},{heading:"Quando o monte seca",body:["As pilhas completas voltam direto para o monte, então as cartas continuam circulando.","Se o monte secar no começo do seu turno, todas as pilhas centrais pela metade também voltam — a sequência zera no ás e as cartas enterradas saem da cova.","Se mesmo assim a mesa travar de vez, a pilha de pagamento mais perto de esvaziar leva a partida, em vez de alguém enrolar para sempre."]},{heading:"Jeitos de jogar",bullets:[{label:"Clássico",text:"a corrida completa com pilha de 20 cartas — traga lanche"},{label:"Rápido",text:"pilha de 10 cartas para uma desforra ligeira"},{label:"Impiedoso",text:"pilha de 13 cartas e sem reposição no meio do turno: esvazie a mão cedo demais e jogue com menos cartas"}]}]},modes:{classic:{name:"Clássico",tagline:"A corrida completa",description:"Vinte cartas enterradas em cada pilha de pagamento e todos os curingas do baralho. O jogo como foi feito para ser saboreado devagar.",facts:["pagamento de 20 cartas","reis e curingas livres","~15 min"]},quick:{name:"Rápido",tagline:"Ressentimento mais curto",description:"Pilhas de pagamento com dez cartas mantêm todo o resto igual — mesmos curingas, mesma malícia, metade da espera pela sua vingança.",facts:["pagamento de 10 cartas","todos os curingas","~5–8 min"]},cutthroat:{name:"Impiedoso",tagline:"Sem piedade, sem reposição",description:"Treze cartas de profundidade e sem reposição no meio do turno: esvazie a mão na hora errada e jogue com menos cartas enquanto outra pessoa ganha.",facts:["pagamento de 13 cartas","sem reposição no turno","brutal"]}},fields:{payoffSize:{label:"Pilha de pagamento",help:"Cartas enterradas em cada pilha de pagamento. Esvazie a sua para vencer — números menores fazem partidas mais curtas.",group:"A distribuição"},handSize:{label:"Cartas distribuídas",help:"Tamanho da mão, reposta até o limite no começo de cada turno.",group:"A distribuição"},discardPiles:{label:"Pilhas de descarte",help:"Pilhas em frente a cada jogador. Encerrar um turno significa descartar em uma delas.",group:"A distribuição"},wilds:{label:"Curingas no baralho",help:"Um curinga vale qualquer valor que você disser. Dezoito é o baralho da caixa; menos torna cada um precioso.",group:"Curingas"},buildPiles:{label:"Pilhas centrais",help:"Sequências compartilhadas em que todo mundo joga. Menos pilhas significam mais espera pelo 1 dos outros.",group:"O centro"},refillMidTurn:{label:"Reposição no turno",help:"Esvazie a mão e ela volta a cinco cartas para você continuar jogando. Desligado é impiedoso.",group:"Regras da casa"}},presets:{classic:"Clássico",quick:"Rápido",cutthroat:"Impiedoso"}},klondike:{name:"Klondike",subtitle:"o clássico do solitário",tagline:"Limpe a mesa do dia",description:"Monte sete colunas em ordem decrescente alternando as cores, vire o monte e mande cada naipe para casa do ás ao rei. A mesma distribuição do dia espera por todo mundo.",facts:["1 jogador","distribuição diária fixa","offline"],howToPlay:{summary:"O clássico solitário de sete colunas, distribuído de forma determinística para uma mesa nova ou para o desafio do dia.",objective:"Monte as quatro fundações do ás ao rei, um naipe por pilha.",sections:[{heading:"A distribuição",body:["Sete colunas guardam de uma a sete cartas. Só a carta do topo de cada coluna começa virada para cima; as outras vinte e quatro formam o monte."]},{heading:"Monte as colunas",body:["Coloque as cartas em ordem decrescente e alternando as cores. Uma sequência virada para cima se move inteira junta. Só um rei — sozinho ou liderando uma sequência — pode entrar em uma coluna vazia."]},{heading:"Vire e recicle",body:["No Clássico, viram-se três cartas do monte por vez; no Tranquilo, uma. Só a carta do topo do descarte pode se mover. Quando o monte acabar, vire o descarte de volta sem embaralhar. Não há limite de passadas."]},{heading:"Fundações",body:["Comece cada naipe com o ás e suba até o rei. Uma carta da fundação pode voltar para a mesa se você precisar desfazer uma linha."]},{heading:"Limpe a mesa",body:["Ao mover a última carta virada para cima de uma coluna, a carta recém-exposta vira automaticamente. Complete as quatro fundações para vencer."]}]},modes:{daily:{name:"Diário",tagline:"Uma mesa para todo mundo",description:"Uma distribuição de Tirar Três fixada na data. Jogue de novo, compartilhe ou volte amanhã para uma mesa nova.",facts:["tirar três","mesma distribuição do dia","passadas ilimitadas"]},classic:{name:"Clássico",tagline:"Tirar três",description:"Uma distribuição nova em que o monte vira três cartas por vez.",facts:["tirar três","distribuição nova","passadas ilimitadas"]},relaxed:{name:"Tranquilo",tagline:"Tirar uma",description:"Uma distribuição nova e mais leve: cada carta do monte chega uma de cada vez.",facts:["tirar uma","distribuição nova","passadas ilimitadas"]}},fields:{drawCount:{label:"Tirada do monte",help:"Vire uma ou três cartas por vez. O descarte pode ser reciclado sem limite de passadas.",group:"Distribuição",options:{3:"Tirar três — clássico",1:"Tirar uma — tranquilo"}}},presets:{classic:"Clássico",relaxed:"Tranquilo"}},golf:{name:"Golfe",subtitle:"o paciência rápido",tagline:"Jogue ±1 no buraco",description:"Sete colunas de cinco, todas as cartas viradas. Jogue um valor vizinho do buraco, encadeie o quanto puder e deixe o mínimo possível na grama.",facts:["1 jogador","buraco diário com semente","offline"],howToPlay:{summary:"Um paciência rápido para uma pessoa: sete colunas de cinco, todas as cartas à mostra e um só buraco.",objective:"Limpe todas as cartas da grama. As que restarem são a sua pontuação — quanto menor, melhor.",sections:[{heading:"A distribuição",body:["Sete colunas recebem cinco cartas viradas cada. As dezessete restantes formam o estoque. A primeira carta do estoque abre o buraco."]},{heading:"Jogue no buraco",body:["Só a carta mais baixa de cada coluna pode sair. Jogue-a no buraco quando estiver a um valor de distância — um 8 aceita 7 ou 9. Naipes e cores não importam."]},{heading:"Vire o estoque",body:["Se nada na grama encaixa, vire a próxima carta do estoque sobre o buraco. A carta antiga fica enterrada e não volta. Não há reciclagem."]},{heading:"Ás e Rei",body:["O Golfe clássico trata Ás e Rei como beco sem saída. Fairway deixa os dois se conectarem para a sequência continuar."]},{heading:"A pontuação",body:["O buraco acaba quando a grama está limpa ou o estoque acaba e não há mais jogadas. As cartas que restam no tableau são a sua pontuação. Zero é um clear."]}]},modes:{daily:{name:"Diário",tagline:"Um buraco para todos",description:"Um buraco Clássico com semente da data. Rejogue, compartilhe ou volte amanhã para uma mesa nova.",facts:["sem volta","mesmo deal diário","ganha quem deixa menos"]},classic:{name:"Clássico",tagline:"Ás e Rei te param",description:"Um buraco novo com semente. Ás e Rei são becos sem saída; o estoque nunca volta.",facts:["sem volta","deal novo","sem reciclagem"]},fairway:{name:"Fairway",tagline:"Ás envolve o Rei",description:"O mesmo buraco rápido, mas Ás e Rei jogam um no outro para as sequências durarem mais.",facts:["envolve A–K","deal novo","sem reciclagem"]}},fields:{wrap:{label:"Ás envolve o Rei",group:"Buraco",help:"O Golfe clássico para no Ás e no Rei. Fairway deixa A e K jogarem um no outro."}},presets:{classic:"Clássico",fairway:"Fairway"}},freecell:{name:"FreeCell",subtitle:"o solitário aberto",tagline:"Limpe a mesa do dia",description:"Oito colunas, todas as cartas viradas para cima. Estacione extras nas células livres e mande cada naipe para casa do ás ao rei. A mesma distribuição do dia espera por todo mundo.",facts:["1 jogador","distribuição diária fixa","offline"],howToPlay:{summary:"O clássico solitário de cartas abertas, distribuído de forma determinística para uma mesa nova ou para o desafio do dia.",objective:"Monte as quatro fundações do ás ao rei, um naipe por pilha.",sections:[{heading:"A distribuição",body:["Oito colunas mostram todas as cartas viradas para cima. As quatro primeiras recebem sete cartas; as quatro últimas recebem seis."]},{heading:"Células livres",body:["Estacione uma carta em cada célula livre. O Clássico tem quatro células; o Tranquilo tem seis. Cada célula guarda uma carta, que pode ir para a mesa ou para uma fundação."]},{heading:"Monte as colunas",body:["Coloque as cartas em ordem decrescente e alternando as cores. Uma sequência compacta se move junta se o limite de supermovimento permitir. Qualquer carta — não só um rei — pode entrar numa coluna vazia."]},{heading:"Fundações",body:["Comece cada naipe com o ás e suba até o rei. Uma carta da fundação pode voltar para a mesa se você precisar desfazer uma linha."]},{heading:"Limpe a mesa",body:["Mande todas as cartas para casa. Complete as quatro fundações para vencer."]}]},modes:{daily:{name:"Diário",tagline:"Uma mesa para todo mundo",description:"Uma distribuição Clássica fixada na data. Jogue de novo, compartilhe ou volte amanhã para uma mesa nova.",facts:["quatro células","mesma distribuição do dia","qualquer carta no vazio"]},classic:{name:"Clássico",tagline:"Quatro células livres",description:"Uma distribuição nova com quatro células de uma carta.",facts:["quatro células","distribuição nova","qualquer carta no vazio"]},relaxed:{name:"Tranquilo",tagline:"Seis células livres",description:"Uma distribuição nova e mais leve: duas células a mais facilitam sequências longas.",facts:["seis células","distribuição nova","qualquer carta no vazio"]}},fields:{freeCells:{label:"Células livres",group:"Distribuição",options:{4:"Quatro células — clássico",6:"Seis células — tranquilo"},help:"Estacione uma carta em cada célula. O Tranquilo adiciona duas células extras."}},presets:{classic:"Clássico",relaxed:"Tranquilo"}},spider:{name:"Spider",subtitle:"o paciência de dois baralhos",tagline:"Tira oito sequências do mesmo naipe",description:"Monta dez colunas em ordem decrescente, move só sequências do mesmo naipe e tira cada Rei-a-Ás da mesa. O mesmo baralho diário de dois naipes espera por todos.",facts:["1 jogador","baralho diário com semente","offline"],howToPlay:{summary:"Spider ao estilo Microsoft com dois baralhos: dez colunas, cinco filas de reserva e oito naipes para limpar.",objective:"Leva oito sequências do mesmo naipe, do Rei ao Ás, para as bases.",sections:[{heading:"O baralho",body:["Dez colunas são dadas: as quatro primeiras têm seis cartas e as outras cinco. Só a carta de cima de cada coluna começa virada. Restam cinquenta cartas no estoque em cinco filas de dez."]},{heading:"Monta o tabuleiro",body:["Coloca as cartas em ordem decrescente, qualquer naipe. Só uma sequência descendente do mesmo naipe pode mover-se em bloco. Uma coluna vazia aceita qualquer carta ou sequência."]},{heading:"Dá uma fila",body:["Clica no estoque para dar uma carta virada a cada coluna. Não podes dar enquanto alguma coluna estiver vazia, nem quando restarem menos de dez cartas."]},{heading:"Limpa um naipe",body:["Quando uma sequência do mesmo naipe de Rei a Ás fica completa numa coluna, ela vai para uma base no mesmo lance. Uma carta tapada que fique descoberta vira sozinha."]},{heading:"Os naipes",body:["Relaxado pinta as 104 cartas como espadas. Clássico (o diário) usa espadas e copas. Difícil usa todos os naipes, por isso as sequências empacotadas são mais raras."]}]},modes:{daily:{name:"Diário",tagline:"Uma mesa para todos",description:"Um baralho de dois naipes com semente da data. Rejoga, partilha, ou volta amanhã a uma mesa nova.",facts:["dois naipes","mesmo baralho diário","cinco filas de estoque"]},relaxed:{name:"Relaxado",tagline:"Só espadas",description:"Um baralho novo mais suave: cada carta é uma espada, e as sequências juntam-se com facilidade.",facts:["um naipe","baralho novo","cinco filas de estoque"]},classic:{name:"Clássico",tagline:"Dois naipes",description:"Um baralho novo com semente pintado em espadas e copas — o padrão da Microsoft.",facts:["dois naipes","baralho novo","cinco filas de estoque"]},hard:{name:"Difícil",tagline:"Quatro naipes",description:"O baralho completo de dois maços. Sequências do mesmo naipe são raras e cada limpeza é ganha.",facts:["quatro naipes","baralho novo","cinco filas de estoque"]}},fields:{suitCount:{label:"Naipes",group:"Baralho",options:{1:"Um naipe — relaxado",2:"Dois naipes — clássico",4:"Quatro naipes — difícil"},help:"Os baralhos de um naipe são todos espadas. O clássico usa espadas e copas. O difícil usa todos os naipes."}},presets:{relaxed:"Relaxado",classic:"Clássico",hard:"Difícil"}},pyramid:{name:"Pirâmide",subtitle:"some até treze",tagline:"Limpe a pirâmide diária",description:"Vinte e oito cartas em um triângulo. Emparelhe valores livres que somam 13, vire o estoque e deixe o mínimo possível.",facts:["1 jogador","pirâmide diária com semente","offline"],howToPlay:{summary:"Um paciência para uma pessoa: vinte e oito cartas em pirâmide e um estoque que você vira sobre um único descarte.",objective:"Emparelhe cartas livres que somam treze e limpe a mesa. As que restarem são a sua pontuação — quanto menor, melhor.",sections:[{heading:"A distribuição",body:["Sete fileiras formam uma pirâmide de vinte e oito cartas viradas. Uma carta está livre quando as duas que a cobrem saem — ou quando ela está na última fileira. As vinte e quatro restantes formam o estoque. O descarte começa vazio."]},{heading:"Some até treze",body:["O Ás vale 1 e o Rei vale 13. Qualquer par de cartas livres cujos valores somam 13 pode ser emparelhado — Dama e Ás, Valete e 2, e assim por diante. Um Rei já vale 13 e sai sozinho. Os naipes não importam."]},{heading:"O descarte",body:["Vire uma carta do estoque para o descarte de cada vez. Só a carta de cima está viva: emparelhe-a com uma carta livre da pirâmide, ou retire-a se for um Rei. Cartas enterradas do descarte não se emparelham entre si."]},{heading:"Reciclar",body:["Quando o estoque acaba, vire o descarte de volta sem embaralhar. Clássico permite duas reciclagem — três passagens. Relaxado nunca acaba."]},{heading:"A pontuação",body:["A partida termina quando não resta nenhuma carta, ou quando nada emparelha e o estoque não pode voltar. Cada carta ainda na pirâmide, no estoque ou no descarte conta. Zero é um clear."]}]},modes:{daily:{name:"Diário",tagline:"Uma pirâmide para todos",description:"Uma pirâmide Clássica com semente da data. Repita, compartilhe ou volte amanhã para uma mesa nova.",facts:["duas reciclagem","mesmo baralho diário","ganha quem deixa menos"]},classic:{name:"Clássico",tagline:"Três passagens",description:"Uma pirâmide nova com semente. O descarte pode ser reciclado duas vezes — três viagens pelo estoque.",facts:["duas reciclagem","baralho novo","três passagens"]},relaxed:{name:"Relaxado",tagline:"Passagens ilimitadas",description:"A mesma mesa de emparelhar, mas o descarte pode ser virado de volta quantas vezes você quiser.",facts:["reciclagem ilimitada","baralho novo","sem limite de passagens"]}},fields:{recyclesLimit:{label:"Reciclagens do descarte",group:"Estoque",options:{2:"Duas reciclagens — clássico","-1":"Ilimitadas — relaxado"},help:"Clássico permite duas reciclagens, três passagens pelo estoque. Relaxado nunca acaba."}},presets:{classic:"Clássico",relaxed:"Relaxado"}},eights:{name:"Oitos Loucos",subtitle:"o clássico de esvaziar a mão",tagline:"Oitos valem em qualquer lugar",description:"Um baralho comum, uma pilha que só cresce. Siga o naipe ou o valor, jogue um oito para virar a mesa para o naipe que você quiser e cobre de todo mundo o que sobrar na mão deles.",facts:["2–6 jogadores","partida por pontos","sozinho ou com amigos"],howToPlay:{summary:"Um baralho comum, uma pilha e oitos que valem em cima de qualquer coisa. Esvazie a sua mão e cobre da mesa o que ela ainda estiver segurando.",objective:"Esvazie a mão para encerrar a rodada e embolsar todas as cartas que sobrarem na mão dos outros. O primeiro a passar da pontuação alvo leva a partida.",sections:[{heading:"Jogando uma carta",body:["No seu turno, jogue uma carta que combine com a pilha em naipe ou em valor — um 7♦ vai em cima de qualquer ouro e de qualquer outro sete.","Um oito é curinga. Ele vale em cima de qualquer coisa, e você escolhe o naipe que vem a seguir.","Nada para jogar? Compre. A pilha continua pedindo o mesmo naipe até alguém mudá-lo."]},{heading:"Cartas de ação",body:["Cada uma delas é um ajuste da mesa, então a casa pode jogar do jeito mais simples ou mais caótico que quiser."],bullets:[{label:"8 — curinga",text:"sempre pode ser jogado; você escolhe o naipe que segue (sempre ativo)"},{label:"2 — compre dois",text:"o próximo lugar compra duas cartas e perde a vez"},{label:"Q — pula",text:"a vez passa direto pelo próximo lugar"},{label:"A — inverte",text:"a mesa gira ao contrário; um contra um, ela te dá outra vez"}]},{heading:"Comprando",body:["Pela tradição, você compra até aparecer algo que possa jogar. Desligue isso e um turno rende exatamente uma carta.","Uma carta comprada que pode ser jogada é sua para jogar na hora ou guardar — a menos que a mesa obrigue a jogada.","Quando o monte acaba, tudo o que está embaixo da carta virada para cima é embaralhado de volta em um monte novo."]},{heading:"Pontuando a rodada",body:["No momento em que uma mão esvazia, todo mundo conta o que ainda está segurando e quem esvaziou embolsa tudo."],bullets:[{label:"Cada oito",text:"50 pontos"},{label:"Qualquer 10, J, Q ou K",text:"10 pontos"},{label:"Qualquer ás",text:"1 ponto"},{label:"Todo o resto",text:"seu valor de face"},{label:"Rodada travada",text:"monte esgotado e ninguém consegue jogar — a mão mais leve vence e embolsa a diferença"}]},{heading:"Vencendo a partida",body:["As rodadas continuam, com a distribuição passando um lugar a cada vez, até alguém cruzar a pontuação alvo. Vence a maior pontuação.","Um empate no topo distribui outra rodada em vez de dividir a coroa."]}]},modes:{classic:{name:"Direto",tagline:"Oitos e mais nada",description:"O jogo como a sua avó distribuía. Combine o naipe ou o valor, jogue um oito para chamar um naipe, compre até algo servir. Primeiro a 100.",facts:["só os 8 são curingas","compre até poder jogar","até 100"]},house:{name:"Da casa",tagline:"Dois, damas e ases",description:"As regras que quase todo mundo joga de verdade: os dois mandam comprar, as damas pulam o próximo lugar, os ases viram a mesa ao contrário. Primeiro a 100.",facts:["2 · Q · A ativos","sem acumular","até 100"]},chaos:{name:"Louco",tagline:"Empilhe tudo",description:"Dois em cima de dois até alguém engolir o bolo inteiro, a carta que você comprou tem que ser jogada e só vale uma compra por turno. Partida longa, mesa barulhenta.",facts:["acumular ativo","jogada obrigatória","até 150"]}},fields:{handSize:{label:"Cartas distribuídas",help:"Quantas cartas cada lugar começa a rodada com.",group:"A distribuição"},targetScore:{label:"Jogar até",help:"As rodadas continuam até alguém cruzar esta pontuação.",group:"A distribuição"},twosDrawTwo:{label:"Dois mandam comprar dois",help:"O próximo lugar compra duas cartas e perde a vez.",group:"Cartas de ação"},queensSkip:{label:"Damas pulam",help:"A vez passa direto pelo próximo lugar.",group:"Cartas de ação"},acesReverse:{label:"Ases invertem",help:"Vira a mesa ao contrário. Com dois jogadores, funciona como um pulo.",group:"Cartas de ação"},stackDrawTwo:{label:"Acumular dois",help:"Responda um dois com o seu e passe a compra acumulada adiante.",group:"Regras da casa"},drawUntilPlayable:{label:"Comprar até poder jogar",help:"A regra tradicional. Desligue para comprar exatamente uma carta por turno.",group:"Regras da casa"},forcePlay:{label:"Jogada obrigatória",help:"Uma carta que você comprou e que pode ser jogada tem que ser jogada.",group:"Regras da casa"}},presets:{classic:"Oitos Direto",house:"Oitos da Casa",chaos:"Oitos Loucos"}},durak:{name:"Durak",subtitle:"o bobo que ninguém quer ser",tagline:"Nunca seja o último com cartas na mão",description:"Um baralho curto, um naipe de trunfo e uma mesa de ataques e defesas. Vença cada carta lançada contra você ou recolha tudo — o último assento ainda com cartas veste o gorro de bobo.",facts:["2–6 jogadores","baralho de 36 cartas","sozinho ou com amigos"],howToPlay:{summary:"Um baralho curto, um naipe de trunfo e uma única missão: nunca ser o último assento ainda com cartas na mão.",objective:"Esvazie sua mão e fique fora para sempre. Assim que o monte acabar, o último assento ainda com cartas é o Durak.",sections:[{heading:"A distribuição",body:["Cada assento recebe seis cartas de um baralho de 36: do seis ao ás, quatro naipes, sem dois, três, quatro nem cinco.","A próxima carta do monte é virada: seu naipe é o trunfo de toda a mão, e fica virada para cima até o monte acabar.","Quem tiver o trunfo mais baixo ataca primeiro. Ninguém tem um? O assento um abre."]},{heading:"Atacar e defender",body:["O atacante joga uma carta. O defensor deve vencê-la: uma carta mais alta do mesmo naipe, ou qualquer trunfo se o ataque não era de trunfo.","Outros assentos podem lançar mais cartas, desde que o valor já tenha aparecido na mesa — vencida ou não, esse valor continua válido até o fim da rodada.","Vença todas as cartas e a mesa inteira é retirada, fora do jogo para sempre — você ataca em seguida.","Não consegue vencer uma? Recolha toda a mesa para sua mão. O jogo passa para o assento seguinte ao seu."],bullets:[{label:"Limite de ataque",text:"um defensor nunca vê mais cartas do que tinha quando a rodada começou"},{label:"Reposição",text:"depois de cada rodada, as mãos voltam a seis — primeiro o atacante, depois os demais, o defensor por último"}]},{heading:"Perevodnoy (repasse)",body:["Quando essa regra da casa está ativa, um defensor que ainda não venceu nada pode repassar em vez de defender: joga uma carta do mesmo valor, e o próximo assento herda todo o ataque."]},{heading:"O fim da mão",body:["Assim que o monte acabar, esvaziar sua mão tira você do jogo para sempre — em definitivo, na ordem em que acontecer.","O último assento ainda com cartas é o Durak. Todos os outros são classificados pela ordem em que saíram."]}]},modes:{classic:{name:"Clássico",tagline:"Podkidnoy — o jogo tradicional de lançar cartas",description:"Ataque, defenda e lance qualquer carta cujo valor já esteja na mesa. Sem repasses — vença a carta ou recolha a mesa.",facts:["lançar cartas ativo","sem repasse","mãos de 6 cartas"]},transfer:{name:"Perevodnoy",tagline:"Repasse o ataque inteiro",description:"Tudo do modo Clássico, mais uma saída: um defensor que ainda não venceu nada pode repassar um valor igual direto para o próximo assento.",facts:["repasses ativos","lançar cartas ativo","mãos de 6 cartas"]},"heads-up":{name:"Um contra um",tagline:"Frente a frente, final rápido",description:"Feito para dois. A primeira mão a esvaziar vence na hora, com ou sem monte — sem esperar o baralho acabar.",facts:["2 jogadores","vitória instantânea","rápido"]}},fields:{transfer:{label:"Repasse (perevodnoy)",help:"Um defensor com um valor igual pode repassar todo o ataque para o próximo assento em vez de vencê-lo.",group:"A rodada"},throwIns:{label:"Lançar cartas (podkidnoy)",help:"Qualquer assento atacante pode lançar mais cartas cujo valor já esteja na mesa.",group:"A rodada"},maxAttacks:{label:"Limite de ataque",help:"O máximo de cartas de ataque que um defensor pode ver em uma rodada.",group:"A rodada"},refillTo:{label:"Tamanho da mão",help:"Cartas distribuídas no início, e o tamanho ao qual cada mão volta depois de uma rodada.",group:"A distribuição"},instantWin:{label:"Vitória instantânea",help:"A primeira mão a esvaziar vence na hora, mesmo que o monte ainda tenha cartas.",group:"Regras da casa"}},presets:{classic:"Durak clássico",transfer:"Perevodnoy","heads-up":"Um contra um"}},palace:{name:"Palace",subtitle:"o jogo de esvaziar camadas",tagline:"Esvazie a mesa, camada por camada",description:"Mão, depois viradas para cima, depois viradas para baixo — queime os dez, desvie dos dois e seja o primeiro a esvaziar cada camada. Também conhecido como Shithead ou Karma.",facts:["2–6 jogadores","doses, dez e oitos","sozinho ou com amigos"],howToPlay:{summary:"Livre-se de tudo o que tiver — mão, depois fileira virada para cima, depois fileira virada para baixo — antes que outro alguém esvazie a mesa.",objective:"Esvazie sua mão, sua fileira virada para cima e sua fileira virada para baixo primeiro para vencer a rodada. Rodadas vencidas se acumulam na partida; o primeiro a atingir a meta leva a partida.",sections:[{heading:"A distribuição",body:["Cada jogador recebe três cartas viradas para baixo, três cartas viradas para cima sobre elas, e três cartas na mão.","Antes de começar, troque quantas cartas da mão quiser pelas suas próprias cartas viradas para cima — você tem uma troca só, depois se declara pronto."]},{heading:"Jogando na pilha",body:["Na sua vez, jogue uma ou mais cartas do mesmo valor que igualem ou superem o valor da pilha, ou recolha a pilha inteira para a mão.","Você deve esvaziar sua mão antes de tocar na fileira virada para cima, e esvaziar essa fileira antes de tocar na fileira virada para baixo."],bullets:[{label:"Abrindo a rodada",text:"quem tiver a carta comum mais baixa começa — três primeiro, depois subindo"},{label:"Recolha quando quiser",text:"você pode pegar a pilha mesmo tendo uma jogada legal — às vezes é a escolha mais segura"},{label:"Jogadas viradas para baixo",text:"com a mão e a fileira virada para cima vazias, vire uma carta às cegas — se ela superar a pilha, fica em jogo e você continua; se não, você recolhe a pilha e a carta"}]},{heading:"Cartas especiais",body:["Quatro valores mudam as regras — todos ativos por padrão, todos ajustáveis:"],bullets:[{label:"2 — reinicia",text:"joga-se sobre qualquer coisa; o piso da pilha cai quase a nada"},{label:"10 — queima",text:"joga-se sobre qualquer coisa; a pilha sai do jogo e você joga de novo"},{label:"8 — invisível",text:"sempre jogável, e nunca muda o que a pilha pede — o próximo responde ao que está por baixo"},{label:"Quadra",text:"quatro cartas do mesmo valor no topo da pilha a queimam, não importa como chegaram lá — você joga de novo"}]},{heading:"Vencendo a rodada",body:["No momento em que um jogador esvazia mão, fileira virada para cima e fileira virada para baixo juntas, a rodada termina imediatamente.","Todos os demais são classificados por quantas cartas ainda têm — menos é melhor — com as cartas viradas para baixo restantes como desempate."]},{heading:"Regras da casa",body:["Ajuste a mesa nas configurações da sala antes de começar:"],bullets:[{label:"Troca antes de jogar",text:"desative para ir direto da distribuição para a primeira jogada"},{label:"O 2 reinicia / o 10 queima / o 8 sempre pode ser jogado",text:"desative qualquer especial para tornar aquele valor comum"},{label:"Quadra queima",text:"desative para deixar uma pilha de valores iguais simplesmente crescer"},{label:"Primeiro a (rodadas vencidas)",text:"quantas rodadas são precisas para vencer a partida — 1 para uma mão rápida, até 7 para uma noite longa"}]}]},modes:{classic:{name:"Clássico",tagline:"A subida completa por camadas",description:"Troque, depois esvazie mão, viradas para cima e viradas para baixo. O primeiro a três rodadas vencidas leva a mesa.",facts:["até 3 rodadas","troca ativada","todos os especiais"]},quick:{name:"Rápido",tagline:"Uma rodada e pronto",description:"Uma única rodada decide tudo — os mesmos especiais, sem partida longa para acumular.",facts:["até 1 rodada","~10 min","ótimo para aquecer"]},chaos:{name:"Caos",tagline:"Sem troca, sem piedade",description:"Direto da distribuição para o jogo — sem fase de troca para planejar. Todos os especiais no máximo: o 2 reinicia, o 10 queima, o 8 continua invisível, a quadra sempre incendeia a pilha.",facts:["até 3 rodadas","sem fase de troca","espere queimadas"]}},fields:{allowSwap:{label:"Troca antes de jogar",help:"A fase de troca entre a distribuição e a primeira jogada."},twosReset:{label:"O 2 reinicia a pilha",help:"Joga-se sobre qualquer coisa e reinicia o piso da pilha."},tensBurn:{label:"O 10 queima a pilha",help:"Joga-se sobre qualquer coisa e queima a pilha; o mesmo jogador joga de novo."},eightsBlind:{label:"O 8 sempre pode ser jogado",help:"Sempre uma jogada legal, e nunca muda o piso da pilha."},fourKindBurn:{label:"Quadra queima",help:"Quatro cartas do mesmo valor no topo da pilha a queimam; o mesmo jogador joga de novo."},winsTo:{label:"Primeiro a (rodadas vencidas)",help:"A partida termina quando um jogador acumula essa quantidade de rodadas vencidas."}},presets:{classic:"Palace clássico",quick:"Palace rápido",chaos:"Palace caótico"}},pinochle:{name:"Pinochle",subtitle:"o jogo de duplas",tagline:"Dê o lance, declare e leve as vazas",description:"Sente-se de frente para o seu parceiro, vença o leilão, escolha o trunfo e declare sua combinação. Ases, dez e reis são as cartas que valem — cumpra seu lance ou fique devendo.",facts:["4 jogadores · 2v2","lance · declaração · vazas","solo ou com amigos"],howToPlay:{summary:"O clássico americano de duplas — dê o lance, escolha o trunfo, declare e jogue as vazas.",objective:"Sentado de frente para o seu parceiro, vença o leilão e cumpra seu lance — declaração mais pontos de vazas pelo menos iguais ao que você pediu. O primeiro time a chegar na pontuação alvo depois de uma mão completa vence a partida.",sections:[{heading:"A mesa",body:["Quatro jogadores, dois times: você e o jogador à sua frente são parceiros. Cada mão distribui o baralho duplo completo de 48 cartas — doze para cada um, sem morto. A distribuição gira para a esquerda a cada mão."]},{heading:"O leilão",body:["Começando à esquerda de quem deu as cartas, cada lugar passa ou dá um lance maior que o anterior. Depois que você passa, está fora da mão. O último lugar que ainda tem um lance vence o leilão e escolhe o trunfo. Se todos passarem sem nenhum lance, a mão é descartada e redistribuída pelo mesmo dealer."],bullets:[{label:"Lance de abertura",text:"precisa superar o mínimo da mesa (25 no modo Clássico)"},{label:"Aumentos",text:"qualquer número inteiro maior, até um teto de 60"}]},{heading:"A declaração",body:["Depois que o trunfo é escolhido, cada lugar declara sua combinação para marcar pontos. As cartas ficam na mão — declarar é pontuar, não descartar — e a mesa calcula tudo para você, então ninguém pode declarar errado."],bullets:[{label:"Sequência de trunfo",text:"Ás-10-rei-dama-valete de trunfo, 15 pontos"},{label:"Casamento",text:"rei + dama do mesmo naipe — 4 se for trunfo (mais 2 se for um segundo par além da sequência), 2 se não for"},{label:"Pinochle",text:"dama de espadas + valete de ouros vale 4; ter as duas cópias de cada uma é um pinochle duplo, que vale 30"},{label:"Rodadas",text:"uma carta do mesmo valor nos quatro naipes — ases 10, reis 8, damas 6, valetes 4"},{label:"Dix",text:"cada 9 de trunfo que você tiver vale 1"}]},{heading:"Jogando as vazas",body:["Quem venceu o leilão puxa a primeira vaza. Você precisa acompanhar o naipe se puder; o trunfo vence um naipe puxado que não seja trunfo, e do contrário a carta mais alta vence. Ás, dez e rei valem 10 pontos cada um quando capturados em uma vaza; a última vaza vale mais 10. Quem vence uma vaza puxa a próxima."]},{heading:"Pontuando uma mão",body:["Some a declaração do time que arrematou aos pontos de vaza que ele fez. Se cumprir o lance, ele marca o total inteiro. Se ficar devendo, ele quebra — perde exatamente o valor do lance, declaração incluída. O outro time sempre marca seus próprios pontos de vaza, e também sua declaração, a menos que a mesa tenha desativado isso."]},{heading:"A partida",body:["As mãos se acumulam até um time chegar ao alvo (100 / 150 / 500). Se os dois times ultrapassarem na mesma mão, o time que arrematou vence a partida direto, a menos que tenha quebrado — nesse caso, ele perde o desempate para a pontuação mais alta, e quem arrematou vence qualquer empate restante."]},{heading:"Regras da casa",body:["As configurações da sala mudam a pontuação alvo, o lance mínimo de abertura, e se os adversários marcam a própria declaração. As mesas Clássicas mantêm os valores padrão."]}]},modes:{classic:{name:"Clássico",tagline:"Partida até 150",description:"Pinochle de duplas até 150, lance mínimo de abertura 25. O jogo como se joga em toda mesa de cozinha.",facts:["partida até 150","lance mín. 25","~30 min"]},quick:{name:"Rápido",tagline:"Primeiro a 100",description:"As mesmas regras, corrida mais curta — 100 pontos, lance de abertura menor, acaba mais rápido.",facts:["partida até 100","lance mín. 20","~15 min"]},marathon:{name:"Maratona",tagline:"Partida até 500",description:"Uma longa batalha de duplas até 500 — cada declaração e cada quebra importam.",facts:["partida até 500","lance mín. 25","~90 min"]}},fields:{target:{label:"Partida até",group:"Partida",help:"Depois de cada mão, a primeira dupla a chegar ou passar dessa pontuação vence.",options:{100:"100 — rápido",150:"150 — clássico",500:"500 — maratona"}},minBid:{label:"Lance mínimo",group:"Leilão",help:"O lance de abertura do leilão precisa superar esse mínimo. Cada lance seguinte precisa superar o anterior, até 60."},opponentsScoreMeld:{label:"Adversários marcam declaração",group:"Pontuação",help:"Quando desligado, o time que não arrematou só marca os pontos de vaza que fizer — não sua declaração."}},presets:{classic:"Clássico",quick:"Rápido",marathon:"Maratona"}},tripeaks:{name:"TriPeaks",subtitle:"limpe os três picos",tagline:"Jogue ±1 sobre o buraco",description:"Dezoito cartas em três picos, todas viradas para cima. Libere uma carta limpando o que a cobre, encadeie jogadas sobre o buraco e limpe os picos.",facts:["1 jogador","picos diários com semente","offline"],howToPlay:{summary:"Um paciência de um jogador: três picos de dezoito cartas, todas viradas para cima, e um monte que você vira sobre um único buraco.",objective:"Limpe todas as cartas dos picos. As cartas que sobrarem são sua pontuação — quanto menos, melhor.",sections:[{heading:"O baralho",body:["Três picos de dezoito cartas ficam viradas para cima em quatro fileiras. A fileira base de nove está sempre livre. As trinta e quatro cartas restantes formam o monte, e a primeira abre o buraco."]},{heading:"Cartas livres",body:["Uma carta fica livre quando as duas cartas que a cobrem desaparecem. Só cartas livres podem se mover — as que ainda estão cobertas ficam presas até que suas filhas se libertem."]},{heading:"Jogue sobre o buraco",body:["Jogue uma carta livre sobre o buraco quando ela estiver a um valor de distância — um 8 aceita um 7 ou um 9. Naipes e cores não importam. Encadeie o máximo de jogadas que conseguir."]},{heading:"Vire o monte",body:["Se nada nos picos encaixar, vire a próxima carta do monte sobre o buraco. A carta anterior do buraco fica enterrada por baixo."]},{heading:"Ás, Rei e o monte",body:["O TriPeaks Clássico trata o Ás e o Rei como becos sem saída, e o monte nunca volta. Relaxado deixa o Ás e o Rei se conectarem, e permite embaralhar o buraco de volta ao monte uma vez que ele acabe."]},{heading:"A pontuação",body:["A partida termina quando os picos ficam limpos, ou quando nada joga e o monte não pode voltar. As cartas que restarem nos picos são sua pontuação. Zero é uma limpeza total."]}]},modes:{daily:{name:"Diário",tagline:"Um baralho para todos",description:"Um baralho Clássico com semente da data. Repita, compartilhe ou volte amanhã para picos novos.",facts:["sem conexão A–K","mesmo baralho diário","menor sobra vence"]},classic:{name:"Clássico",tagline:"Ás e Rei te param",description:"Um baralho novo com semente. O Ás e o Rei são becos sem saída; o monte nunca volta.",facts:["sem conexão A–K","baralho novo","sem reciclagem"]},relaxed:{name:"Relaxado",tagline:"O Ás conecta com o Rei",description:"Os mesmos três picos, mas o Ás e o Rei se jogam um sobre o outro e o buraco pode ser reciclado uma vez.",facts:["conecta A–K","baralho novo","uma reciclagem"]}},fields:{wrap:{label:"O Ás conecta com o Rei",group:"Buraco",help:"O TriPeaks Clássico para no Ás e no Rei. Relaxado deixa A e K se jogarem um sobre o outro."},recycle:{label:"Reciclar o buraco",group:"Monte",help:"Quando o monte acaba, embaralhe o buraco (menos sua carta do topo) de volta ao monte uma vez."}},presets:{classic:"Clássico",relaxed:"Relaxado"}}},zh:{blitz:{name:"Blitz（31点）",subtitle:"三十一点游戏",tagline:"冲向31点",description:"摸牌、换牌、敲桌，凑出同花色的31点。三种赛制、精明的机器人，还有一场声势浩大的庆祝。",facts:["2–4人","经典·快速·限时","单人或好友"],howToPlay:{summary:"酒馆经典31点——摸牌、换牌、敲桌，凑出同一花色的31点。",objective:"一轮结束时，手牌要比其他所有人都大。手牌按点数最高的单一花色计分：A=11，花牌=10，数字牌按面值。同一花色凑满31点就是BLITZ，立刻获胜。",sections:[{heading:"你的回合",body:["你有两个动作："],bullets:[{label:"摸牌",text:"摸牌堆顶的那张牌，或者拿走弃牌堆顶的牌"},{label:"弃牌",text:"从手牌中滑出一张，正面朝上放到弃牌堆上"}]},{heading:"手牌计分",body:["只算你最好的那个花色。三张红心共27点，胜过三张杂花色共30点。","三条是一手特殊牌，计30½分（房间规则开关）。"]},{heading:"敲桌",body:["你可以不摸牌，改为敲桌结束这一轮。其他人各再出一次，然后全部亮牌比大小。","点数最低的人失去一条命。如果敲桌的是你自己，却并列或垫底，惩罚由你承担——敲桌要有底气。"]},{heading:"Blitz！",body:["手里同一花色凑满31点，这一轮立刻引爆——其他所有人各失一条命，无需比牌。","发牌直接发到Blitz？也算数。尽管得意吧。"]},{heading:"赛制",bullets:[{label:"经典",text:"每输一轮失去一条命；最后还有命的人获胜"},{label:"快速",text:"单轮定胜负，先赢N局者胜，立即重新发牌"},{label:"限时",text:"对局时钟加每回合倒计时，铃响时赢轮最多者胜"}]},{heading:"房间规则",body:["每张牌桌都可以在房间设置里调整——命数、敲桌惩罚、平局处理、三条、弃牌锁定和回合倒计时都在那里。"]}]},modes:{classic:{name:"经典",tagline:"命悬一线",description:"输一轮，丢一条命。是早早敲桌，还是追逐完美的31点——最后手里还有筹码的人赢下这一局。",facts:["每人3条命","活到最后","~5–10分钟"]},fast:{name:"快速",tagline:"一轮一胜负",description:"每轮独立计分，立即重新发牌。点数最高者赢下底池——先赢三轮的人拿下这一局。",facts:["先赢3轮","无人出局","~2–4分钟"]},timed:{name:"限时",tagline:"与时间赛跑",description:"三分钟的对局时钟，加上快出牌的回合倒计时。铃响时赢轮最多的人获胜。",facts:["3:00对局时钟","7秒回合倒计时","平局加赛"]}},fields:{threeOfAKind:{label:"三条",options:{"30.5":"计30.5分",30:"计30分",off:"关闭"}},tieLowest:{label:"最低分并列",options:{both:"双双输命",nobody:"无人受罚",redeal:"并列者重发"}},discardLock:{label:"刚摸的弃牌不可再弃"}},presets:{"classic-pub":"经典酒馆",cutthroat:"狠角色",friendly:"友好局"}},cribbage:{name:"克里比奇",subtitle:"计分板竞速",tagline:"钉到121分",description:"经典酒馆竞速——用手牌凑出十五点、顺子和对子，在计分板上钉分冲线，还要祈祷别被人切出一张J偷了分。",facts:["2名玩家","经典·无情","单人或好友"],howToPlay:{summary:"经典酒馆竞速——用手牌凑出得分组合，再把分一路钉到121。",objective:"率先在计分板上钉满121分。得分有两次机会：往牌桌上出牌时（钉分阶段），以及结算手牌和Crib时。",sections:[{heading:"发牌",body:["你拿到六张牌。留下四张，把两张面朝下滑进CRIB——这手奖励牌归本轮发牌者计分。","是自己的Crib就大方地塞，是对方的就防守着丢。"]},{heading:"切牌",body:["发牌者切牌堆，亮出起始牌，每手牌都共用这张牌。","切出J就是HIS HEELS——发牌者当场得2分。"]},{heading:"钉分",body:["从发牌者左手边开始，玩家轮流出一张牌，累计点数（花牌算10）。任何情况下都不能让累计超过31。","边出边得分："],bullets:[{label:"十五点",text:"你出的牌让累计正好到15——2分"},{label:"对子/三条/四条",text:"与上一张同点数——2/6/12分"},{label:"顺子",text:"三张以上点数连续，无论出牌顺序——每张1分"},{label:"三十一点",text:"你出的牌让累计正好到31——2分"},{label:"Go与最后一张",text:"没人能在31以内出牌时，最后出牌的玩家得1分，累计清零"}]},{heading:"结算",body:["钉分结束后，大家依次大声计分：先是非发牌者的手牌，再是发牌者的，最后是Crib。起始牌算作第五张牌。"],bullets:[{label:"十五点",text:"每一种凑成15的牌组合——每种2分"},{label:"对子",text:"对子2分，三条6分，四条12分"},{label:"顺子",text:"连续序列按张数计分；双顺翻倍（7-7-8-9 = 12）"},{label:"同花",text:"手牌中四张同花色得4分，起始牌也同花色则得5分。CRIB里只有五张全同花才算。"},{label:"His nobs",text:"手中有与起始牌同花色的J——1分"}]},{heading:"获胜与横扫",body:["先到121分者获胜，哪怕是在计分中途。发牌者每轮轮换。","开启横扫规则时，输家若低于90分就是被SKUNK——值得好好嘲笑一番的惨败。"]},{heading:"房间规则",body:["房间设置承载了酒馆里的那些争论："],bullets:[{label:"横扫",text:"点名嘲笑低于90分的输家（默认开启）"},{label:"抢分",text:"你在牌桌上该得的分没喊出来，对手可以抢走（默认关闭）——喊分要趁早！"}]}]},modes:{"classic-pub":{name:"经典酒馆",tagline:"原汁原味",description:"六张牌，两张进Crib，一场钉到121分的长跑。横扫作数——低于90分收场，会被念叨一辈子。",facts:["目标121分","90分横扫线","约10–15分钟"]},cutthroat:{name:"无情局",tagline:"抢分眼在盯",description:"同样的竞速，爪子更利：在牌桌上漏喊的分，对手替你拿走。",facts:["抢分开启","漏喊即被偷","毫不留情"]},"match-play":{name:"多局赛制",tagline:"三板两胜",description:"正经的长夜局：钉到121，钉位归零，再来一遍。先赢下两整局的玩家拿下整场。",facts:["先赢2局","发牌轮换","约25–40分钟"]}},fields:{skunks:{label:"90分横扫线"},muggins:{label:"抢分（偷走漏喊的分）"},gamesToWin:{label:"获胜所需局数"}},presets:{"classic-pub":"经典酒馆",cutthroat:"无情局","match-play":"多局赛制",friendly:"友谊局"}},wild:{name:"Wild",subtitle:"出光手牌的游戏",tagline:"出光每一张牌",description:"112张牌的狂欢：跳过、反转、+4、整色倾倒、抢打出牌。还是那张温暖的牌桌，只是牌堆吵闹得多。",facts:["2–4人","限时发牌","单人或好友"],howToPlay:{summary:"112张牌的出牌狂欢——跟上弃牌堆顶，甩出功能牌，第一个出光手牌。",objective:"成为第一个出光手牌的人。功能牌会拖慢其他人——除非他们奋起反击。",sections:[{heading:"出牌",body:["轮到你时，打出一张与弃牌堆顶颜色或牌面相同的牌，或者改为摸牌。","万能牌随时可出，还能指定下一个颜色。"]},{heading:"功能牌",bullets:[{label:"跳过",text:"下一位玩家失去回合——而且不能抢打回来"},{label:"反转",text:"出牌方向调转；两人对局时等于你再出一回合"},{label:"+2",text:"下一位玩家摸两张牌并失去回合"},{label:"整色倾倒",text:"把手里同颜色的牌全部垫在它下面丢出；被卷走的功能牌不生效"},{label:"万能牌",text:"随时可出，指定下一个颜色"},{label:"万能+4",text:"指定颜色，还让下一位玩家摸四张牌"},{label:"万能换手",text:"指定颜色，然后与任意一人交换手牌（可选牌）"},{label:"万能洗牌",text:"把所有人的手牌收拢、洗匀、重新发（可选牌）"}]},{heading:"最后一张",body:['只剩两张牌了？出牌前先喊"最后一张！"。只剩一张还没喊，被抓到就罚摸两张。',"摸牌会让你重新回到线以上，所以还得再喊一次。"]},{heading:"计时",body:["每个回合都有倒计时。时间耗尽时，牌桌会替那位玩家出一手合法牌，让牌局继续滚动。","发牌也有对局时钟。最后一分钟里会实时显示第一到第四名，随手牌变化而更新。"],bullets:[{label:"对局归零时",text:"手牌最少者获胜；张数相同则按座位顺序定胜负，每次重放都有唯一结果"},{label:"高级选项",text:"发牌前可设置每回合秒数和对局总分钟数"}]},{heading:"房间里的混乱",body:['所有牌桌设置都在发牌前的"高级选项"里：'],bullets:[{label:"叠加",text:"用同样的牌回应+2/+4，惩罚会一路堆给下一个倒霉蛋"},{label:"抢打",text:"手里有和刚打出的牌完全相同的牌？趁所有人没反应过来，抢先拍下"},{label:"摸到能出为止",text:"一直摸牌，直到摸出能出的牌，而不是只摸一张"},{label:"强制出牌",text:"摸到的牌如果能出，就必须出"},{label:"质疑+4",text:"手里没有旧颜色时打+4才算老实——戳穿虚张声势，罚牌归他；质疑错了，你多摸两张"},{label:"7和0",text:"打出7，与你指定的人交换手牌；打出0，所有人的手牌顺移一个座位"},{label:"换牌万能牌",text:"把万能换手和万能洗牌加进牌堆"}]},{heading:"获胜",body:["在对局时钟归零前出光手牌即获胜。否则，归零时手牌最轻者获胜。"]}]},modes:{classic:{name:"经典",tagline:"照章办事",description:"跟颜色或跟数字，然后一次倒空整个颜色。不叠加、不抢打——一场彬彬有礼的狂欢。",facts:["一次发牌","不可叠加","~5分钟"]},party:{name:"派对",tagline:"叠起来，拍下去",description:"+2和+4层层堆叠，牌面完全相同还能抢打出牌。混乱，但灯光温暖。",facts:["叠加开启","抢打开启","~5分钟"]},houseRules:{name:"房间规则",tagline:"全部拉满",description:"7换牌、0传牌，换牌万能牌加入牌堆，摸到的牌还必须打出去。",facts:["7·0换牌","换牌万能牌","强制出牌"]}},fields:{handSize:{label:"发牌张数",group:"发牌",help:"每个座位开局拿到几张牌。"},turnTimeSeconds:{label:"每回合秒数",group:"计时",help:"时间耗尽时，牌桌会替该座位出一手合法牌。"},matchTimeMinutes:{label:"对局分钟数",group:"计时",help:"归零时，剩余手牌最轻的玩家获胜。"},stackDrawTwo:{label:"叠加+2",group:"罚牌",help:"用自己的+2回应+2，把越堆越多的罚牌传下去。"},stackDrawFour:{label:"叠加+4",group:"罚牌",help:"+4同理。罚牌可能涨得飞快。"},jumpIn:{label:"抢打",group:"房间规则",help:"手里有刚打出的那张牌的同款？抢先拍下，不用等轮到你。"},drawToMatch:{label:"摸到能出为止",group:"房间规则",help:"一直摸牌直到摸出能出的牌，而不是只摸一张。"},forcePlay:{label:"强制出牌",group:"房间规则",help:"摸到的牌如果能出，就必须出。"},sevenZero:{label:"7和0",group:"房间规则",help:"打出7，与某人交换手牌；打出0，所有人的手牌顺移一个座位。"},challengeDrawFour:{label:"质疑+4",group:"房间规则",help:"手里没有当前颜色时打+4才算老实。戳穿虚张声势：赢了罚牌归他，输了你多摸两张。"},swapCards:{label:"换牌万能牌",group:"牌堆",help:"把万能换手和万能洗牌加进牌堆。"}},presets:{classic:"经典Wild",party:"派对牌堆",houseRules:"房间规则"}},ratscrew:{name:"拍七",subtitle:"拍牌游戏",tagline:"抢先拍下牌堆",description:"轮流向公共牌堆翻牌，抢在所有人之前拍下对子、三明治和更多牌型。实时反应、花牌挑战、拍错烧牌。",facts:["2–4名玩家","实时抢拍","单人或好友"],howToPlay:{summary:"轮流向公共牌堆翻牌，靠抢拍赢走桌上的每一张牌。",objective:"赢走全部52张牌。靠抢先拍下牌型，或靠打出对手接不住的花牌来壮大自己的牌叠。等其他人都没牌了——或被人一拍拍回局里——你就赢下整局。",sections:[{heading:"翻牌",body:["从你开始，玩家轮流把自己面朝下牌叠顶上的牌放到中央牌堆上，翻牌时朝外翻，谁都别想偷看。","牌叠见底就不用再翻了——但开着“拍回局里”时，一记幸运抢拍就能让你立刻重返牌局。"]},{heading:"花牌与挑战",body:["打出花牌会向下一位玩家发起挑战："],bullets:[{label:"J",text:"对方有1次机会翻出新的花牌"},{label:"Q",text:"2次机会"},{label:"K",text:"3次机会"},{label:"A",text:"4次机会"}]},{heading:"挑战结算",body:["被挑战者每翻出一张非花牌，就烧掉一次机会。","翻出了新花牌？挑战带着全新的机会传给下一位玩家。","机会用光了？打出花牌的玩家把整个中央牌堆收进自己牌叠底下，并翻出下一张。"]},{heading:"抢拍",body:["可拍牌型一落上牌堆，所有人立刻抢着去拍。第一个有效拍击赢走整个中央牌堆，并翻出下一张。","牌型生效时会开一个短暂的抢拍窗口——在窗口关闭前猛砸SLAP按钮！"],bullets:[{label:"对子",text:"两张同点数的牌紧挨着（7♦ 7♣）"},{label:"三明治",text:"同点数中间隔一张牌（7♦ Q♠ 7♥）"},{label:"联姻",text:"K和Q紧挨着，顺序不限（K♦ Q♠）——房间规则开关"},{label:"凑十",text:"两张相邻数字牌相加为十（3♦ 7♠）——房间规则开关"},{label:"首尾相应",text:"顶牌与牌堆最底下那张同点数——房间规则开关"},{label:"顺子",text:"连续三个点数递增或递减（4-5-6或9-8-7）——房间规则开关"}]},{heading:"拍错",body:["没有牌型生效时乱拍要付出代价：开着“拍错烧牌”时，你的顶牌会被塞到牌堆底下作为惩罚。手抖是要花钱的——盯紧牌，别管观众。"]},{heading:"房间规则",body:["开局前在房间设置里调好混乱程度："],bullets:[{label:"对子/三明治",text:"经典抢拍牌型，默认都开启"},{label:"联姻/凑十/首尾/顺子",text:"额外牌型，经典牌桌默认全关"},{label:"拍错烧一张牌",text:"默认开启；关掉后只有生效的牌型才能拍"},{label:"出局可拍回",text:"空手玩家仍可拍下生效牌型，赢走牌堆重返牌局"},{label:"抢拍窗口",text:"竞速保持开放的时长——越短越凶残"}]},{heading:"牌桌礼仪",body:["赢下牌堆的玩家把它不洗牌直接塞到自己牌叠底下，并翻出下一张。最后握有全部牌的玩家赢下整局。","一小段宽限时间让远程抢拍保持公平：牌桌会等窗口过后一拍，才宣布关闭。"]}]},modes:{classic:{name:"经典抢拍",tagline:"对子与三明治",description:"酒馆标准：快速翻牌，盯紧对子和三明治，在窗口关闭前拍下。",facts:["拍窗1.2秒","拍错烧牌","约8分钟"]},"quick-reflex":{name:"极速反应",tagline:"凶残窗口",description:"同样的经典牌型，扳机更敏感——抢拍窗口0.7秒就砰然关闭。",facts:["拍窗0.7秒","眼尖者进","约6分钟"]},slaphappy:{name:"拍牌狂欢",tagline:"牌型全开",description:"联姻、凑十、首尾相应和顺子，全部叠加在经典之上。混乱，暖光，震耳欲聋。",facts:["全部牌型","拍窗0.8秒","约5分钟"]}},fields:{doubles:{label:"对子"},sandwiches:{label:"三明治"},marriage:{label:"联姻（K+Q）"},tens:{label:"凑十"},topBottom:{label:"首尾相应"},runs:{label:"顺子"},misSlapBurn:{label:"拍错烧一张牌"},slapBackIn:{label:"出局可拍回"},slapWindowMs:{label:"抢拍窗口"}},presets:{classic:"经典抢拍","quick-reflex":"极速反应",slaphappy:"拍牌狂欢"}},euchre:{name:"尤克",subtitle:"搭档对战",tagline:"为你的队伍赢墩",description:"叫起它、定好将牌，和对面的搭档一起追逐大小王。先到十分的队伍拿下整局。",facts:["4人·2v2","吃墩","单人或好友"],howToPlay:{summary:"美国中西部经典——结成搭档、定将牌，带你的队伍冲向10分。",objective:"和坐在你对面的搭档一起，靠你叫出的将牌花色，在每手五墩中至少赢下三墩。先达到目标分的队伍赢得整局。",sections:[{heading:"牌桌",body:["四名玩家，两支队伍：你和对面的玩家是搭档。每人五张牌；剩下四张作为底牌，最上面一张翻开。"]},{heading:"叫起——第一轮叫牌",body:["从发牌者左手边开始，每个人对那张翻开的牌二选一："],bullets:[{label:"叫起",text:"该花色成为将牌，发牌者把这张牌收进手牌，并扣下一张牌"},{label:"单打",text:"叫起将牌，并让搭档这一手坐板凳"},{label:"跳过",text:"决定权移向左手边"}]},{heading:"定将牌——第二轮",body:["如果四人都跳过，翻开的牌被扣下，每个座位可以叫其他任何花色作将牌。被扣下的花色不能再叫。","发牌者兜底（默认）：第二轮如果其他人都跳过，发牌者必须叫一个花色。"]},{heading:"大小王",body:["某个花色被定为将牌后，它的J是右王——全场最大的牌。同色另一花色的J是左王，仅次于右王，也算将牌。所以红心是将牌时，J♥和J♦就是最大的两张牌。"]},{heading:"打墩",body:["发牌者左手边的玩家首攻。能跟花色就必须跟——记住左王属于将牌，不属于它印的花色。首攻花色中最大的牌赢墩，除非有人出将牌；最大的将牌通吃。赢墩者首攻下一墩。"]},{heading:"一手计分",body:["叫牌的一方是庄家。五墩打完："],bullets:[{label:"3或4墩",text:"庄家得1分"},{label:"5墩",text:"横扫——庄家得2分"},{label:"单打横扫",text:"单打时五墩全拿——庄家得4分"},{label:"被尤克！",text:"庄家没拿到三墩——防守方得2分"}]},{heading:"单打",body:["足够自信的叫牌者可以不带搭档独自打这一手，搭档全程旁观。单打五墩全拿值4分——但拿不到三墩，防守方照样尤克你得2分。"]},{heading:"房间规则",body:["房间设置调整整局：目标分5/10/15、发牌者兜底开关、是否允许单打。如果一手无人叫将牌而作废，发牌权直接左移。"]}]},modes:{classic:{name:"经典酒馆",tagline:"原汁原味",description:"十分制、发牌者兜底、允许单打。就是消防站和厨房牌桌上玩的那个样子。",facts:["打到10","发牌者兜底","约20分钟"]},"quick-cut":{name:"速战",tagline:"先到五分",description:"规则不变，赛程更短——五分就结束。水还没烧开就能打完。",facts:["打到5","约10分钟"]},"long-game":{name:"长局",tagline:"坐稳了",description:"十五分，够你好好打上一整晚。欢迎记仇。",facts:["打到15","约30分钟"]},"old-school":{name:"老派",tagline:"发牌者可跳过",description:"没有发牌者兜底——人人都可以跳过，发牌权直接左移。有些爷爷辈就认这个玩法。",facts:["打到10","无兜底","约20分钟"]}},fields:{targetScore:{label:"目标分",help:"先达到这个分数的搭档组合赢得整局。",group:"一局",options:{5:"5——速战速决",10:"10——标准",15:"15——长局"}},stickDealer:{label:"发牌者兜底",help:"第二轮叫牌中，如果其他人都跳过，发牌者必须叫一个花色。",group:"叫牌"},goingAlone:{label:"允许单打",help:"手握好牌的叫牌者可以让搭档这一手坐板凳。",group:"叫牌"}},presets:{classic:"经典酒馆","quick-cut":"速战","long-game":"长局","old-school":"老派"}},hearts:{name:"红心大战",subtitle:"躲避罚分的游戏",tagline:"一张红心都别吃",description:"躲开每一张红心，避开黑桃皇后，把罚分全塞给别人。轮流传牌、暗中选牌，还有一位锋利无比的皇后。",facts:["4人","传牌·吃墩·躲避","单人或好友"],howToPlay:{summary:"经典躲避游戏——不吃红心，躲开黑桃皇后，把罚分留给别人。",objective:"一局结束时总分最低者获胜。你每吃到一张红心就计1分，黑桃皇后计13分；当有人越过终局线（默认100分）时，总分最低者获胜。",sections:[{heading:"传牌",body:["每手开局前，你挑出三张牌传给一位邻座——所有人暗中选牌，然后四份传牌同时落地。",'方向每手轮换：向左、向右、对家，然后是一手不传牌的"留手"局。']},{heading:"吃墩",body:["第一墩由梅花2首攻。能跟花色就必须跟；首攻花色中最大的一张赢下这一墩，赢墩者下一墩首攻。"],bullets:[{label:"第一墩",text:"第一墩不能丢罚分牌（房间规则开关）"},{label:"破红心",text:"红心不能首攻，直到有人在之前的墩里垫过红心——除非你手里只剩红心"},{label:"断门",text:"没有首攻花色？随便丢什么——皇后往往就是这样砸到别人头上的"}]},{heading:"一手计分",body:["十三墩打完后，你吃到的每张红心计1分，黑桃皇后计13分。"],bullets:[{label:"方块J",text:"可选房间规则——吃到它的人计−10分"},{label:"射月",text:"吃齐全部十三张红心外加皇后，你自己计0分，其他所有人各+26分——或者按另一条房间规则，你自己的总分减26分"}]},{heading:"整局",body:["一手一手累积，直到有人越过终局线（50/75/100分）。总分最低者赢下这一局；平分则共享桂冠。"]},{heading:"房间规则",body:["房间设置里什么都能调：传牌方向、留手局、首墩保护、方块J、终局线和射月方式。经典牌桌保持默认即可。"]}]},modes:{classic:{name:"经典",tagline:"照章办事",description:"传牌按左、右、对家轮换，每四手来一局留手，首墩不吃罚分。打到100分。",facts:["打到100分","含留手局","~15分钟"]},quickcut:{name:"快局",tagline:"更快见分晓",description:"规则不变，门槛更低——谁先过50分就结束。一杯咖啡的时间打完一整局。",facts:["打到50分","含留手局","~8分钟"]},cutthroat:{name:"狠角色",tagline:"方块J出笼",description:"方块J给吃到它的人计−10分，罚分牌从第一墩就能飞。谁都不安全。",facts:["J♦ −10","首墩可罚分","打到100分"]}},fields:{passDirection:{label:"传牌方向",options:{left:"向左",right:"向右",across:"对家",hold:"留手（不传）"}},holdHand:{label:"每四手来一局留手"},noPointsFirstTrick:{label:"第一墩不丢罚分牌"},jackDiamonds:{label:"方块J计−10分"},gameOver:{label:"终局分数",options:{50:"50分",75:"75分",100:"100分"}},moonShift:{label:"射月",options:{opponents:"其他人各+26分",self:"自己总分−26分"}}},presets:{classic:"经典红心大战",quickcut:"快局",cutthroat:"狠角色"}},gin:{name:"金拉米",subtitle:"拉米经典",tagline:"组牌、敲桌、赢下今晚",description:"十张牌，两把椅子。凑出刻子和顺子，甩掉你的死牌，抢在对手之前拍桌收局。",facts:["2人","敲·金·大金","单人或好友"],howToPlay:{summary:"经典双人牌戏——摸牌、弃牌、组牌，凑出一手值得敲桌的好牌。",objective:"把手里十张牌凑成刻子和顺子，几乎不留死牌，然后抢在对手之前敲桌。先越过局分目标的座位获胜。",sections:[{heading:"组牌与死牌",body:["组牌要么是三到四张同点数的刻子，要么是同花色三张以上的顺子。A只能算小（A-2-3，不能Q-K-A）。","没进组牌的牌都是死牌，按牌面计点：花牌算十，A算一。越少越好。"]},{heading:"你的回合",body:["每个回合两步："],bullets:[{label:"摸牌",text:"从牌堆顶摸一张，或拿走弃牌堆顶那张"},{label:"弃牌",text:"把一张牌面朝上放到弃牌堆上——本回合刚摸的那张不能弃，无论从哪堆摸的"}]},{heading:"开局的明牌",body:["发完牌后有一张牌面朝上放着。非发牌者可以把它收进手牌，或跳过；然后发牌者也有同样的选择。如果两人都跳过，非发牌者从牌堆摸牌，对局开始。"]},{heading:"敲桌",body:["死牌不高于敲桌上限（默认10）时，你可以敲桌代替弃牌。这一手立即结束——不再弃牌。先摸第十一张牌，如果全部成组，就开启了大金路线。"]},{heading:"金与补牌",body:["死牌为零就是金——防守方不能补牌，按全部死牌赔付，外加金奖励。","普通敲桌时防守方先补牌：手里能把敲桌者的刻子补成四张、或把顺子往两头接长的剩余牌，都先从账上划掉再比较。","如果防守方补完牌后死牌不高于你，就是反切——改由他们拿走差额加奖励。"]},{heading:"计分与一局",body:["一手接一手，直到有人越过局分目标（默认100），发牌者每手轮换。"],bullets:[{label:"敲桌",text:"双方死牌之差"},{label:"反切",text:"差额+25归防守方"},{label:"金",text:"防守方全部死牌+25"},{label:"大金",text:"十一张牌全部成组——防守方死牌+31（可开关）"},{label:"局盒奖励",text:"可选：每赢一手+25，结算时并入总分（可开关）"}]},{heading:"房间规则",body:["每张牌桌都可以在房间设置里调整："],bullets:[{label:"敲桌上限",text:"死牌多低才能敲——上限越紧，一手拖得越久"},{label:"局分目标",text:"50快节奏，100经典，更高适合磨局"},{label:"大金／奖励／局盒奖励",text:"赔付旋钮"}]},{heading:"死局",body:["牌堆只剩两张时，这一手作废——不计分，发牌者重新发牌。要敲就趁早。"]}]},modes:{classic:{name:"经典",tagline:"直奔100",description:"酒馆标准——死牌10以内可敲，金赔25，大金赔31。先过100者胜。",facts:["敲桌上限10","打到100","约15分钟"]},quick:{name:"快速",tagline:"冲向50",description:"规则不变，梯子更短。烧水间隙就能来一局的快双人局。",facts:["打到50","约8分钟"]},purist:{name:"纯粹",tagline:"没有花活",description:"大金关闭，局盒奖励也不带。纯粹的敲桌、纯粹的死牌，没有安全网。",facts:["无大金","无局盒奖励"]}},fields:{knockCap:{label:"敲桌上限",help:"敲桌时允许的最高死牌点数",group:"牌桌"},matchTarget:{label:"局分目标",help:"先越过这个分数的座位赢得整局",group:"牌桌"},ginBonus:{label:"金奖励",group:"奖励"},bigGin:{label:"大金",help:"摸第十一张牌并全部成组",group:"奖励"},bigGinBonus:{label:"大金奖励",group:"奖励"},boxBonus:{label:"局盒奖励",help:"每赢一手+25，并入最终总分",group:"奖励"}},presets:{classic:"经典",quick:"快速局",purist:"纯粹"}},president:{name:"大富豪",subtitle:"攀爬游戏",tagline:"一路爬上王座",description:"用更大的牌组压过牌堆，最先出完手牌，从最底层爬到大富豪。最多八个座位，王冠与屈辱俱全。",facts:["4–8名玩家","身份与换牌","单人或好友"],howToPlay:{summary:"经典攀爬游戏——最先出完手牌，从最底层一路爬到大富豪，让对手乖乖给你进贡。",objective:"每一轮都尽量占据最好的名次。最先出完的是大富豪，最后出完的是垫底。名次分逐轮累积；先到目标总分者赢得整局。",sections:[{heading:"压牌堆",body:["首攻者用任意牌组开一墩——同点数的单张、对子、三张或四张。","顺时针依次，每人必须用同样张数、点数严格更大的牌组压过牌堆，否则跳过。"],bullets:[{label:"点数顺序",text:"3最小，一路升到A，2高踞一切之上"},{label:"跳过",text:"跳过只跳过这一拍——本墩中若有人稍后压过牌堆，你还可以回到牌局（除非开启了锁定跳过规则）"},{label:"赢下一墩",text:"其他人都跳过后，牌堆被收走，赢家可以用任意牌组首攻"},{label:"2清场",text:"单张2立刻赢下牌堆并继续首攻——房间规则，默认开启"}]},{heading:"结束一轮",body:["出完手牌，你就锁定了梯子上的下一个名次。一直打到只剩一个人手里还有牌——那就是垫底。","最先出完是大富豪，第二是副富豪，倒数第二是副垫底，最后的座位是垫底。"]},{heading:"计分与整局",body:["每一轮都累积名次分：大富豪得的分数等于座位数，第二名少一分，依次递减，垫底只得1分。","有人达到目标分时整局立即结束——累积总分最高者获胜，平分则共享王冠。"]},{heading:"进贡换牌",body:["下一轮开始前，低座位从新手牌里进贡，高座位回赠自己挑的牌："],bullets:[{label:"垫底 → 大富豪",text:"垫底交出最好的两张牌；大富豪回赠任意两张"},{label:"副垫底 → 副富豪",text:"各交一张"},{label:"关闭开关",text:"在房间设置里关掉换牌，来一局更纯粹的混战"}]},{heading:"房间规则",body:["开局前在房间设置里调好牌桌："],bullets:[{label:"2清场",text:"默认开启——关掉后，2只是一张打不败的普通牌"},{label:"锁定跳过",text:"一旦跳过，整墩都作壁上观（默认关闭：牌堆变化时你可以回来）"},{label:"换牌",text:"轮次之间按身份进行的换牌"},{label:"目标分数",text:"整局多大——7分速战，11分常规，21分马拉松"}]},{heading:"牌桌礼仪",body:["第一轮由起始座位首攻；之后每一轮都由在位的大富豪首攻。","手牌逐张轮发直到牌堆见底，所以人数不整的牌桌会有座位少一张牌——大家都一样。"]}]},modes:{classic:{name:"经典",tagline:"完整天梯",description:"王冠、进贡与逆袭——先到11分者称霸牌桌。酒馆里就是这么玩的。",facts:["先到11分","换牌开启","2清场"]},rapid:{name:"快速",tagline:"短小火辣",description:"先到7分，节奏不停。同样的规则，更少的轮次，更响的逆袭。",facts:["先到7分","约10分钟","6人以上更妙"]},marathon:{name:"马拉松",tagline:"王朝绵长",description:"21分的权谋大戏。垫底翻身成大富豪，王朝起落，尽在局中。",facts:["先到21分","长局","完整历程"]}},fields:{twoClears:{label:"2清场"},passLocks:{label:"跳过后锁定整墩"},trading:{label:"轮次间按身份换牌"},targetPoints:{label:"目标分数"}},presets:{classic:"经典牌桌",rapid:"快速内阁",marathon:"马拉松"}},spades:{name:"黑桃",subtitle:"搭档对战",tagline:"报出你的墩数",description:"和搭档面对面坐下，报一个数字，然后尽量恰好赢下那么多墩——多一墩少一墩都别要。黑桃永远是将牌。沙袋总会找上你。",facts:["4人·2v2","叫牌·将牌·沙袋","单人或好友"],howToPlay:{summary:"美式搭档经典——报墩、破黑桃，向500分冲刺。",objective:"和坐在你对面的搭档一起，赢下至少你们两人叫牌之和的墩数。先达到目标分（默认500）的队伍获胜；若双方在目标线上或以上平分，就再发一手。",sections:[{heading:"牌桌",body:["四名玩家，两支队伍：你和对面的玩家是搭档。每手发完整副52张牌——每人十三张。发牌和首次叫牌都从发牌者左手边开始，按顺时针进行。"]},{heading:"叫牌",body:["每个座位报一个数字，只报一次。不能跳过，也不能重报。你们队的合约就是两个非零叫牌之和。"],bullets:[{label:"1–13",text:"你预计能赢下的墩数"},{label:"零（Nil）",text:"一种特殊叫牌——一墩不拿得+100，拿到任何一墩则−100。零叫失败后拿到的墩帮不了搭档完成合约，但每一墩仍算一个沙袋"}]},{heading:"打墩",body:["发牌者左手边的玩家首攻第一墩。能跟花色就必须跟；最大的黑桃赢墩，否则是首攻花色中最大的牌。赢墩者首攻下一墩。"],bullets:[{label:"破黑桃",text:"在有人缺门垫出黑桃之前，不能用黑桃首攻——除非你手里只剩黑桃"},{label:"缺门",text:"没有首攻花色了？随便出，包括将牌"}]},{heading:"一手计分",body:["如果队里非零叫的座位拿够了合约墩数，每叫一墩得10分，每超一墩再加1分。没拿够的话，合约每墩扣10分。"],bullets:[{label:"沙袋",text:"超出的墩（以及零叫失败后拿到的墩）都是沙袋。沙袋逐手累积；每攒满十个扣100分，剩下的沙袋继续留账"},{label:"零（Nil）",text:"单独计分，加在搭档的合约结果之上"}]},{heading:"一局",body:["一手一手累积，直到有队伍达到目标分（250 / 500 / 750）。分高者胜；若两队在目标线上或以上同分，就再发一手。"]},{heading:"房间规则",body:["房间设置只有三个开关：目标分、是否允许零叫、是否计沙袋。经典牌桌保持默认。不提供盲零。"]}]},modes:{classic:{name:"经典",tagline:"照章办事",description:"搭档黑桃打到500分，零叫开、沙袋开。就是每家厨房牌桌上玩的那个样子。",facts:["打到500","零叫·沙袋","约25分钟"]},quick:{name:"快速",tagline:"先到250",description:"规则不变，赛程更短——250分就结束。一顿午饭的功夫打完一整局。",facts:["打到250","零叫·沙袋","约12分钟"]},"clean-books":{name:"干净墩",tagline:"没有沙袋",description:"要么完成叫牌，要么宕掉——超墩不算沙袋，也不加分。要精准，不要注水。",facts:["打到500","零叫开","沙袋关"]}},fields:{targetScore:{label:"目标分",help:"每手结束后，达到或超过这个分数的最高分队获胜。平分则再发一手。",group:"一局",options:{250:"250——速战速决",500:"500——标准",750:"750——长局"}},nil:{label:"允许零叫",help:"叫零即零叫（Nil）：一墩不拿得+100，拿到任何一墩则−100。零叫失败后拿到的墩帮不了搭档的合约。",group:"叫牌"},bags:{label:"计沙袋",help:"超墩和零叫失败后拿到的墩都是沙袋。每攒满十个扣100分；剩下的沙袋继续留账。",group:"计分"}},presets:{classic:"经典",quick:"快速","clean-books":"干净墩"}},poker:{name:"扑克",subtitle:"无限注德州扑克",tagline:"笑到最后的筹码",description:"两张自己的底牌，五张公共牌，再用全部筹码表明你有多相信它们。盲注会一路上涨，直到有人赢走所有筹码。",facts:["2–6名玩家","无限注德州","只用游戏筹码"],howToPlay:{summary:"无限注德州扑克，以单桌淘汰赛的形式进行——所有人起步相同，盲注不断上涨，最后手握筹码的人获胜。",objective:"赢走所有筹码。每手牌你会发到两张底牌，并与全桌共享五张公共牌；凑出最大的五张牌型者赢得底池，筹码输光的人出局。",sections:[{heading:"筹码",body:["筹码只是记分，不是真钱——没有买入，也没有兑现。所有人起步筹码相同，当一名玩家握有全部筹码时，一局结束。"]},{heading:"一手牌",body:["先给每个座位发两张暗牌，然后一轮下注。翻出三张公共牌（翻牌），再一轮下注。第四张（转牌），再一轮。第五张（河牌），最后一轮。还在牌局里的人摊牌，七张牌中凑出的最大五张获胜。"],bullets:[{label:"按钮位",text:"标记庄家位置，每手牌向左移动一个座位"},{label:"盲注",text:"按钮位左边的两个座位在发牌前强制下注，保证每手牌都有东西可争"}]},{heading:"轮到你",body:["当行动轮到你时，永远只有四件事可做。"],bullets:[{label:"弃牌",text:"放弃这手牌，已投入的筹码也一并放弃"},{label:"过牌",text:"不下注继续留在牌局——仅在无人下注时可用"},{label:"跟注",text:"跟上当前的下注额"},{label:"下注／加注",text:"投入更多，其他人必须跟上才能留下。加注至少要与上一次加注同额——除非你全押了"}]},{heading:"全押",body:["你输的永远不会超过面前的筹码。押上最后一颗筹码就是全押：你会留在这手牌直到摊牌，超出你筹码的下注会另建边池，你赢不到也输不掉。"]},{heading:"牌型大小",body:["从大到小排列。牌型相同比次大牌，完全相同则平分底池。"],bullets:[{label:"同花顺",text:"五张连号且同一花色——A 最大时为皇家同花顺"},{label:"四条",text:"四张同点数"},{label:"葫芦",text:"三张同点加一对"},{label:"同花",text:"五张同一花色"},{label:"顺子",text:"五张连号——A 可当最大或最小"},{label:"三条",text:"三张同点数"},{label:"两对",text:"两个不同点数的对子"},{label:"一对",text:"两张同点数"},{label:"高牌",text:"以上皆不是"}]},{heading:"一局比赛",body:["盲注按时间表上涨，所以一味弃牌不是办法——一局总会分出胜负。输光就出局；最后手握筹码的人获胜，其余人按出局先后排名。"]},{heading:"房间规则",body:["房间设置可选择起始筹码、盲注上涨速度、大盲是否从第三级起为全桌下前注，以及摊牌时输家的牌是翻开还是盖牌收场。"]}]},modes:{classic:{name:"经典",tagline:"完整牌桌",description:"每人三千筹码，盲注每八手上涨一级。在被逼到全押之前，有充足空间打完一手牌。",facts:["3,000筹码","每8手涨盲","约25分钟"]},turbo:{name:"极速",tagline:"要么全押要么走",description:"短筹码，盲注每四手翻一倍。没人等得起口袋A。",facts:["1,500筹码","每4手涨盲","约10分钟"]},deep:{name:"深筹码",tagline:"读懂对手",description:"六千筹码配缓慢的盲注阶梯，没有前注。打的是长线，位置感和耐心才真正值钱。",facts:["6,000筹码","每12手涨盲","无前注"]}},fields:{startingStack:{label:"起始筹码",help:"每个座位开局时拥有的筹码。筹码越深，翻牌后的操作空间越大。",group:"对局",options:{1500:"1,500——短筹码",3e3:"3,000——标准",6e3:"6,000——深筹码"}},blindSpeed:{label:"盲注上涨",help:"盲注按时间表上涨，保证一局总会结束。极速模式会早早逼出行动。",group:"对局",options:{slow:"慢速——每12手",standard:"标准——每8手",turbo:"极速——每4手"}},ante:{label:"全桌前注",help:"从第三级起，大盲额外为全桌下一个盲注的前注，让底池永远值得去争。",group:"下注"},showMucked:{label:"亮出输家的牌",help:"关闭时，输掉的牌像真实牌桌一样盖牌收场；开启时，所有打到河牌的牌都会亮给大家看。",group:"摊牌"}},presets:{classic:"经典",turbo:"极速",deep:"深筹码"}},ohhell:{name:"Oh Hell",subtitle:"叫墩游戏",tagline:"报几墩，就赢几墩",description:"手牌一轮轮变大又变小，而你要报出自己会赢下的确切墩数。坑人规则保证每轮总有人落空——别让自己成为那个人。",facts:["3–7名玩家","叫牌·将牌·精准","单人或好友"],howToPlay:{summary:"报出你会赢下的确切墩数——不多也不少。手牌一轮轮缩小又变大，直到有人叫牌胜过全桌。",objective:"在一局手牌先增后减的比赛里，靠精准完成叫牌来得分超过所有人。每轮总有人注定要落空——尽量别是你。",sections:[{heading:"牌桌",body:["三到七名玩家，各自为战。一局由一连串轮次组成：第一轮每人发一张牌，之后手牌逐渐增到峰值（留有上限，保证总能翻出将牌），再一路减回一张。发牌每轮顺时针轮换。"]},{heading:"翻将牌",body:["发完牌后，从牌堆翻开下一张牌——它的花色就是本轮的将牌。"],bullets:[{label:"无牌可翻",text:"当发牌用光了整副牌，就没有牌可翻，本轮以无将牌进行"},{label:"切将牌",text:"启用「切将牌」的牌桌会把整副牌的轮次缩小一张，好从牌堆底部切出将牌"}]},{heading:"叫牌",body:["从庄家左手边开始顺时针，每个座位报一个从 0 到自己手牌数的数字：他声称自己会赢下的确切墩数。不能跳过，也没有第二次机会。"],bullets:[{label:"坑人规则",text:"庄家最后叫牌，且不能使总叫墩数恰好等于本轮的总墩数——这桌必有一人落空。被禁的数字根本不会出现在你的转盘上"},{label:"零",text:"和其他数字一样合法：一墩也不赢"}]},{heading:"打墩",body:["庄家左手边首攻第一墩。能跟花色就必须跟；最大的将牌赢墩，否则首攻花色中最大的牌赢。赢墩者首攻下一墩。"]},{heading:"一轮计分",body:["叫牌必须分毫不差，否则一分不得（默认）。每个座位的轮次得分计入累计总分；整轮弧线打完后，总分最高者获胜。"],bullets:[{label:"精准制",text:"恰好完成得 10 + 叫墩数；否则得 0"},{label:"罚分制",text:"恰好完成得 10 + 叫墩数；落空则扣掉相差的墩数"},{label:"加倍制",text:"恰好完成得叫墩数的两倍；否则得 0"}]},{heading:"巫师变体",body:["开启巫师与小丑后，四张巫师和四张小丑加入牌堆（共 60 张），平常的大小顺序被彻底打乱。"],bullets:[{label:"巫师",text:"大过一切；打出的第一张巫师赢墩。首攻巫师会让这一墩没有首攻花色——任何人都可以出任何牌"},{label:"小丑",text:"小过一切；若一墩全是小丑，则第一张赢墩。首攻小丑时，首攻花色由下一张真正的牌决定"},{label:"翻将牌",text:"翻出巫师时由庄家选定将牌；翻出小丑则本轮无将牌"}]}]},modes:{classic:{name:"经典",tagline:"先升后降",description:"经典弧线——从一张牌开始，涨到峰值，再降回一张。坑人规则开启，只认精准叫牌。每轮总有人落空，希望不是你。",facts:["1…峰值…1","坑人规则开","约20分钟"]},quick:{name:"快速",tagline:"大发快收",description:"从五张牌起步，一路倒数到一张。十分钟内打完一整局，全是胆量，没有水分。",facts:["5→1张牌","约10分钟"]},wizard:{name:"巫师",tagline:"六十张牌，四张必胜",description:"四张巫师逢打必赢，四张小丑逢打必输。首攻花色绕着它们转，庄家有时还能亲选将牌。混乱，但有章法。",facts:["60张牌堆","巫师开启"]}},fields:{handSize:{label:"手牌张数",help:"本轮发给每名玩家的牌数。完整的一局会为每一轮自动设定。",group:"对局"},dealer:{label:"庄家座位",help:"本轮发牌并最后叫牌的座位。完整的一局每轮轮换庄家。",group:"对局"},handArc:{label:"手牌弧线",help:"一局之中手牌大小的走势：先升后降、只升，或大发快收。",group:"对局",options:{updown:"先升后降——1…峰值…1",up:"只升——1…峰值",down:"只降——峰值…1"}},maxHand:{label:"最大手牌",help:"弧线不会超过这个张数——设有上限，保证每轮都有牌可翻作将牌。",group:"对局"},hookRule:{label:"坑人规则",help:"坑一把庄家：最后叫牌者不能使总叫墩数恰好等于总墩数，所以每轮总有人落空。",group:"叫牌"},scoring:{label:"计分方式",help:"精准完成叫牌才能得分。各方案的区别在于落空的代价。",group:"计分",options:{exactOnly:"精准制——10 + 叫墩数，否则为零",penalty:"罚分制——差几墩扣几分",plusOne:"加倍制——完成时叫墩数翻倍"}},wizards:{label:"巫师与小丑",help:"加入四张巫师（逢打必赢）和四张小丑（逢打必输）——一副 60 张的牌堆。",group:"进阶"},trumpOnLastRound:{label:"整副牌轮次切将牌",help:"当一轮会发完整副牌时，先从底部切出将牌（手牌缩小一张），而不是打无将牌。",group:"进阶"}},presets:{classic:"经典",quick:"快速",wizard:"巫师"}},scopa:{name:"斯科帕",subtitle:"捞牌游戏",tagline:"一扫而空",description:"靠对点或凑和从桌上吃牌，囤积金灿灿的金币花色，猎取那张最美的7。把整桌一扫而空就叫一声斯科帕——意大利牌室里最美妙的词。",facts:["2–6名玩家","吃牌·凑和","单人或好友"],howToPlay:{summary:"意大利捞牌经典——从桌上吃牌，把桌面一扫而空就是一声斯科帕。",objective:"通过对点或凑出相同点数来吃掉桌上的牌。牌数最多、金币最多、7♦、primiera 以及每次斯科帕各得一分；先达到目标分（默认 11）者赢下一局。",sections:[{heading:"牌桌",body:["斯科帕使用 40 张的意大利牌：金币（Denari）、圣杯（Coppe）、宝剑（Spade）和棍棒（Bastoni），点数 1 到 10。两人、三人、四人或六人都能玩——四人和六人时结成固定搭档，座位在牌桌旁交错落座。","每次发牌给每名玩家三张牌，并往桌上亮出四张。如果开局桌面上出现三张或更多 K，就重新洗牌重发。"]},{heading:"吃牌",body:["轮到你时，从手牌中打出恰好一张牌。吃牌只看点数——花色永远无关。"],bullets:[{label:"对点",text:"你的牌吃掉桌上一张同点数的牌：5 吃 5"},{label:"选择",text:"如果桌上有两张同点数的牌，由你挑走哪一张——好好选，剩下的牌很关键"},{label:"凑和",text:"你的牌可以吃掉点数加起来等于它的两张或更多牌：8 吃掉 3 和 5。但若存在单张对点，你必须先吃它——只有没有对点时才能凑和"},{label:"摆牌",text:"什么都吃不了？你的牌就亮着留在桌上，任人取用"}]},{heading:"斯科帕",body:["一次吃牌把桌上剩下的牌全部扫光，你就完成了一次斯科帕：得一分，立即入账。但最后一次发牌的最后一张牌扫桌不算——那些牌反正都会被收走。手牌打空后，每人再发三张新牌；桌面永不补充。牌堆耗尽时，最后吃过牌的玩家收走桌上剩余的牌，这次扫桌不算斯科帕。"]},{heading:"一轮计分",body:["最后一次发牌结束后，先评出四分，再加上牌局中挣到的斯科帕。搭档牌桌先把两家的收获合并再计分。"],bullets:[{label:"牌数",text:"吃牌最多者——两人局要拿到 40 张中的 21 张以上；持平则无人得分"},{label:"金币",text:"金币花色吃得最多者——10 张中拿 6 张以上；持平则无人得分"},{label:"7♦",text:"吃到那张美丽的金币 7 的人永远得 1 分"},{label:"Primiera",text:"每个花色各取最好的一张求和——7 计 21，6 计 18，A 计 16，5→15，4→14，3→13，2→12，花牌只计 10。某个花色一张都没有就无法赢它。总分最高者得 1 分；持平则无人得分"},{label:"斯科帕",text:"每次一分，牌局中已经入账"}]},{heading:"一局比赛",body:["一轮接一轮——庄家每次向左移——直到有人越过目标分。若双方在终点线上打平，再赛一轮定胜负。"]},{heading:"房间规则",body:["房间设置提供经典开关：目标分（11/16/21）、Scopone（整副牌一次发完，没有牌堆）、Napola（金币连张加分）、Re di denari（金币 K 加分），以及纯视觉的法式花色显示。"]}]},modes:{classic:{name:"经典",tagline:"先到11分",description:"每家意大利酒吧里的玩法：一次发三张，一轮四分，先到十一分。",facts:["11分制","每次发3张","约20分钟"]},lungo:{name:"长局",tagline:"长线作战",description:"同样的规则，改赛二十一分。留足了翻盘、结怨和传奇斯科帕的空间。",facts:["21分制","每次发3张","约40分钟"]},scopone:{name:"Scopone",tagline:"整副牌，不留情",description:"老派四人局：十张牌一次发完，没有牌堆，没有暗牌。每一次吃牌都是承诺。",facts:["4名玩家·2v2","整副牌","约30分钟"]}},fields:{target:{label:"目标分",help:"每轮结束后，达到或超过这条线的最高分获胜。终点线打平则再发一轮。",group:"对局",options:{11:"11——经典",16:"16——偏长",21:"21——长局"}},scopone:{label:"Scopone",help:"老派四人局：整副牌一次发完，没有牌堆可摸。吃牌会变得紧张得多。",group:"发牌"},napola:{label:"Napola",help:"集齐金币 A、2、3 得 3 分加分，之后每多一张延续连张的金币（4、5、…）再加 1 分。",group:"计分"},reDenari:{label:"Re di denari",help:"吃到金币 K 的玩家得 1 分加分。",group:"计分"},frenchSuits:{label:"法式花色显示",help:"把金币／圣杯／宝剑显示为方块／红心／黑桃，以便使用标准牌面图案。纯属视觉——牌的身份和规则仍是意大利式。",group:"牌桌"}},presets:{classic:"经典",lungo:"长局","scopone-preset":"Scopone"}},spite:{name:"怨恨与恶意",subtitle:"结算牌堆竞速",tagline:"加倍奉还",description:"把中央的公共牌堆从A叠到Q，清空你的结算牌堆，再用恰到好处的万能牌搅黄别人的计划。游戏名就是规则。",facts:["2–4人","经典·快速·无情","单人或好友"],howToPlay:{summary:"怨恨与恶意——把公共的中央牌堆从A叠到Q，抢在所有人之前打完你的结算牌堆。",objective:"成为第一个清空结算牌堆的玩家。你埋进去的每一张牌，都是别人幸灾乐祸的资本。",sections:[{heading:"牌桌",body:["四种牌，四个去处："],bullets:[{label:"结算牌堆",text:"你扣着的目标牌堆；最上面一张翻开"},{label:"手牌",text:"五张牌，你的回合开始时补回五张"},{label:"弃牌堆",text:"四个你自己的牌堆——结束回合就是往其中一个弃牌"},{label:"中央牌堆",text:"最多四个公共牌堆，人人都可以往上叠"}]},{heading:"你的回合",body:["先摸牌补回五张。然后想怎么出就怎么出，顺序随意：","出到中央牌堆、打出结算牌堆的顶牌，或打出你自己某个弃牌堆的顶牌。","只有当你从手牌里弃一张到自己的弃牌堆时，回合才结束。"]},{heading:"叠牌",body:["中央牌堆从A开始，一张一张叠到Q。花色无所谓。","叠满到Q后，整堆被洗回摸牌堆——这个位置重新空出来，等下一张A或万能牌。"]},{heading:"万能牌",bullets:[{label:"万能牌",text:"牌里共十八张——当成你需要的任何点数打出，这个点数会被牌堆记住"},{label:"被记住的点数",text:"一张当6用的万能牌，意味着下一张要出7，不管谁来出"}]},{heading:"结算牌堆",body:["打出结算牌堆的顶牌，下一张立刻翻开——如果那就是最后一张，你当场获胜，回合中途也算，不用再弃牌。","卡住了没牌可出？那就带点心机地弃牌：你现在堆起来的牌，是以后能解锁的一步好棋。"]},{heading:"牌堆见底",body:["叠满的牌堆直接洗回摸牌堆，所以牌一直在循环。","如果你的回合开始时摸牌堆空了，所有叠了一半的中央牌堆也会被扫回去——需求重置回A，埋着的牌重见天日。","如果牌桌彻底锁死，就由结算牌堆最接近清空的玩家收下这一局，免得大家干耗。"]},{heading:"玩法",bullets:[{label:"经典",text:"完整的20张结算牌堆竞速——备好零食"},{label:"快速",text:"10张结算牌堆，来一局速战速决的恩怨局"},{label:"无情",text:"13张结算牌堆，回合中不补牌：过早打空手牌，就只能缺着牌硬撑"}]}]},modes:{classic:{name:"经典",tagline:"全程竞速",description:"每个结算牌堆埋满20张，万能牌全数上阵。这游戏本来就是要慢慢熬着玩的。",facts:["20张结算堆","K与Joker万能","约15分钟"]},quick:{name:"快速",tagline:"恩怨速战",description:"10张结算牌堆，其余原封不动——同样的万能牌，同样的恶意，复仇的等待减半。",facts:["10张结算堆","万能牌全开","约5–8分钟"]},cutthroat:{name:"无情",tagline:"毫不留情",description:"13张的深度，回合中不补牌：时机不对就打空手牌，只能缺着牌看别人赢下这一局。",facts:["13张结算堆","回合中不补牌","狠"]}},fields:{payoffSize:{label:"结算牌堆",help:"埋在每个结算牌堆里的牌数。清空你的牌堆即获胜——数字越小，对局越短。",group:"发牌"},handSize:{label:"发牌数",help:"手牌数量，每个回合开始时补满。",group:"发牌"},discardPiles:{label:"弃牌堆",help:"每位玩家面前的牌堆数。结束回合就是往其中一个弃牌。",group:"发牌"},wilds:{label:"牌里的万能牌",help:"万能牌可以当成你指定的任何点数。十八张是原版牌数；越少，每一张就越珍贵。",group:"万能牌"},buildPiles:{label:"中央牌堆",help:"人人都能往上叠的公共牌堆。数量越少，越要干等别人的1。",group:"中央"},refillMidTurn:{label:"回合中补牌",help:"打空手牌就立刻补回五张，继续操作。关闭就是无情模式。",group:"房间规则"}},presets:{classic:"经典",quick:"快速",cutthroat:"无情"}},klondike:{name:"空当接龙式纸牌（Klondike 单人纸牌）",subtitle:"经典单人纸牌",tagline:"清空每日牌桌",description:"七列牌按红黑相间从大到小叠放，翻动牌堆，把四种花色从A到K送回家。同一天，人人面对同一副每日牌局。",facts:["1人","每日固定牌局","离线可玩"],howToPlay:{summary:"经典的七列单人纸牌，以固定种子发牌——可以是全新牌局，也可以是每日牌局。",objective:"把四个花色的收牌堆都从A叠到K，每堆一个花色。",sections:[{heading:"发牌",body:["七列牌列分别放一到七张牌。每列只有顶牌翻开；其余二十四张组成摸牌堆。"]},{heading:"叠放牌列",body:["按点数递减、红黑相间地放牌。一串翻开的连牌可以整体移动。只有K——单独一张或领着一串——才能进入空列。"]},{heading:"翻牌与回收",body:["经典模式每次从摸牌堆翻三张；轻松模式每次翻一张。只有废牌堆的顶牌可以移动。摸牌堆空了，就把废牌堆原样翻回去，不洗牌。翻牌次数不限。"]},{heading:"收牌堆",body:["每个花色从A开始，一路叠到K。如果需要解开一条线，收牌堆里的牌也可以拿回牌列。"]},{heading:"清空牌桌",body:["移走一列的最后一张翻开的牌，新露出的牌会自动翻开。集齐四个收牌堆即获胜。"]}]},modes:{daily:{name:"每日",tagline:"人人同一局",description:"按日期生成种子的翻三张牌局。重打它、分享它，或者明天再来一张新牌桌。",facts:["翻三张","每日同一局","翻牌不限次"]},classic:{name:"经典",tagline:"每次翻三张",description:"全新种子牌局，每次从摸牌堆翻三张。",facts:["翻三张","全新牌局","翻牌不限次"]},relaxed:{name:"轻松",tagline:"每次翻一张",description:"更温和的全新牌局：摸牌堆每次只来一张。",facts:["翻一张","全新牌局","翻牌不限次"]}},fields:{drawCount:{label:"摸牌方式",group:"发牌",options:{3:"翻三张——经典",1:"翻一张——轻松"},help:"每次翻一张或三张。废牌堆可以回收，翻牌次数不限。"}},presets:{classic:"经典",relaxed:"轻松"}},golf:{name:"高尔夫",subtitle:"快节奏单人纸牌",tagline:"向洞口打出相邻点数",description:"七列各五张，全部正面朝上。把与洞口相差一点的牌打出去，尽量连打，让草地上剩下的牌越少越好。",facts:["1 人","每日固定牌局","可离线"],howToPlay:{summary:"快节奏单人耐心牌：七列各五张，全部可见，只有一个洞口。",objective:"清空草地上的每一张牌。剩下的牌就是你的分数——越低越好。",sections:[{heading:"发牌",body:["七列各放五张正面朝上的牌。剩下十七张组成牌库。牌库最上面一张打开洞口。"]},{heading:"打进洞口",body:["每列只能打最下面那张。当它与洞口相差一点时就可以打出去——8 可以接 7 或 9。花色和颜色都不重要。"]},{heading:"翻牌库",body:["如果草地上没有能打的牌，就把下一张牌库牌翻到洞口。旧的洞口牌被压住，不能再回来。没有回收。"]},{heading:"A 与 K",body:["经典高尔夫把 A 和 K 当作死胡同。球道规则允许它们互相衔接，连打可以继续。"]},{heading:"计分",body:["草地清空，或牌库用尽且再无合法打法时，这一洞结束。还留在列上的牌就是分数。零分就是清台。"]}]},modes:{daily:{name:"每日",tagline:"大家同一洞",description:"按日期播种的经典洞。可以重打、分享，或明天再来一局新桌。",facts:["不循环","每日同一局","剩余越少越好"]},classic:{name:"经典",tagline:"A 与 K 会卡住",description:"一局新的固定种子。A 和 K 是死胡同；牌库不会回收。",facts:["不循环","新牌局","无回收"]},fairway:{name:"球道",tagline:"A 可接 K",description:"同样快的一洞，但 A 和 K 可以互打，连打会更长。",facts:["A–K 循环","新牌局","无回收"]}},fields:{wrap:{label:"A 与 K 循环",group:"洞口",help:"经典高尔夫在 A 和 K 处停下。球道规则允许 A 和 K 互相打出。"}},presets:{classic:"经典",fairway:"球道"}},freecell:{name:"空当接龙",subtitle:"明牌单人纸牌",tagline:"清空每日牌桌",description:"八列牌全部翻开。把多出来的牌停在空当里，再把四种花色从A到K送回家。同一天，人人面对同一副每日牌局。",facts:["1人","每日固定牌局","离线可玩"],howToPlay:{summary:"经典的明牌单人纸牌，以固定种子发牌——可以是全新牌局，也可以是每日牌局。",objective:"把四个花色的收牌堆都从A叠到K，每堆一个花色。",sections:[{heading:"发牌",body:["八列牌全部翻开。前四列各七张，后四列各六张。"]},{heading:"空当",body:["每个空当只能停一张牌。经典模式四个空当；轻松模式六个。空当里的牌可以回到牌列或送进收牌堆。"]},{heading:"叠放牌列",body:["按点数递减、红黑相间地放牌。一串连牌可以整体移动，但要受空当超级移动上限限制。任意牌——不只是K——都能进入空列。"]},{heading:"收牌堆",body:["每个花色从A开始，一路叠到K。如果需要解开一条线，收牌堆里的牌也可以拿回牌列。"]},{heading:"清空牌桌",body:["把每张牌都送回家。集齐四个收牌堆即获胜。"]}]},modes:{daily:{name:"每日",tagline:"人人同一局",description:"按日期生成种子的经典牌局。重打它、分享它，或者明天再来一张新牌桌。",facts:["四个空当","每日同一局","空列可放任意牌"]},classic:{name:"经典",tagline:"四个空当",description:"全新种子牌局，带四个单牌空当。",facts:["四个空当","全新牌局","空列可放任意牌"]},relaxed:{name:"轻松",tagline:"六个空当",description:"更温和的全新牌局：多两个空当，长串更好挪。",facts:["六个空当","全新牌局","空列可放任意牌"]}},fields:{freeCells:{label:"空当数量",group:"发牌",options:{4:"四个空当——经典",6:"六个空当——轻松"},help:"每个空当停一张牌。轻松模式再加两个空当。"}},presets:{classic:"经典",relaxed:"轻松"}},spider:{name:"蜘蛛纸牌",subtitle:"双副单人纸牌",tagline:"清掉八条同花顺",description:"十列按点数递减接龙，只有同花色的连续牌组可以一起移动，把每条从 K 到 A 的同花顺收走。每天同一副双花色牌局等着所有人。",facts:["1 人","每日固定牌局","可离线"],howToPlay:{summary:"微软风格的双副蜘蛛：十列、五排库存，要清掉八条同花顺。",objective:"把八条同花色的 K 到 A 收进基础堆。",sections:[{heading:"发牌",body:["发出十列：前四列各六张，其余各五张。每列只有最上面一张正面朝上。剩下五十张是库存，分成五排，每排十张。"]},{heading:"接龙",body:["按点数递减放置，花色不限。只有同花色的连续递减牌组可以整组移动。空列可以接受任意一张或一组牌。"]},{heading:"发一排",body:["点击牌库，给每一列发一张正面朝上的牌。任何一列为空，或库存不足十张时，不能发牌。"]},{heading:"清掉一条花色",body:["当一列上凑齐同花色的 K 到 A 时，这一整组会在同一步里收进基础堆。新露出来的背面牌会自动翻开。"]},{heading:"花色",body:["轻松模式把 104 张都画成黑桃。经典（每日）用黑桃和红心。困难用全部花色，同花连续组更少。"]}]},modes:{daily:{name:"每日",tagline:"大家同一桌",description:"按日期播种的双花色牌局。可以重打、分享，或明天再来一局新桌。",facts:["两种花色","每日同一局","五排库存"]},relaxed:{name:"轻松",tagline:"全是黑桃",description:"更温和的新牌局：每张都是黑桃，连续组很容易凑齐。",facts:["一种花色","新牌局","五排库存"]},classic:{name:"经典",tagline:"两种花色",description:"一局新的固定种子，画成黑桃和红心——微软的默认规则。",facts:["两种花色","新牌局","五排库存"]},hard:{name:"困难",tagline:"四种花色",description:"完整的双副牌。同花连续组很少，每一次收走都得自己挣。",facts:["四种花色","新牌局","五排库存"]}},fields:{suitCount:{label:"花色",group:"发牌",options:{1:"一种花色 — 轻松",2:"两种花色 — 经典",4:"四种花色 — 困难"},help:"单花色全是黑桃。经典用黑桃和红心。困难用全部花色。"}},presets:{relaxed:"轻松",classic:"经典",hard:"困难"}},pyramid:{name:"金字塔",subtitle:"凑成十三",tagline:"清空每日金字塔",description:"二十八张牌排成三角。把点数相加为 13 的自由牌配对，翻开牌库，剩下越少越好。",facts:["1 人","每日固定金字塔","可离线"],howToPlay:{summary:"单人耐心牌：二十八张牌排成金字塔，牌库翻到单独的废牌堆上。",objective:"把自由牌凑成十三并清空桌面。剩下的牌就是你的分数——越低越好。",sections:[{heading:"发牌",body:["七行组成二十八张正面朝上的金字塔。一张牌在盖住它的两张都拿走后才自由——最底行一开始就自由。剩下二十四张是牌库。废牌堆开始是空的。"]},{heading:"凑成十三",body:["A 算 1，K 算 13。任意两张自由牌点数相加为 13 就可以配对——Q 配 A、J 配 2，以此类推。K 本身就是 13，可以单独拿走。花色无所谓。"]},{heading:"废牌堆",body:["每次从牌库翻一张到废牌堆。只有废牌堆顶牌有效：可以和金字塔上的自由牌配对，如果是 K 也可以单独拿走。被压住的废牌不能互相配对。"]},{heading:"回收",body:["牌库用完后，把废牌堆原样翻回去，不洗牌。经典模式可以回收两次——一共三轮。轻松模式没有次数限制。"]},{heading:"计分",body:["牌局在全部清空时结束，或者再也配不成对、牌库也无法回来时结束。金字塔、牌库和废牌堆里剩下的每张都计分。零分就是清台。"]}]},modes:{daily:{name:"每日",tagline:"同一座金字塔",description:"按日期定死的经典金字塔。可以重打、分享，或者明天再来一局新的。",facts:["两次回收","同一每日牌局","剩下越少越好"]},classic:{name:"经典",tagline:"三轮机会",description:"一局新的定死金字塔。废牌堆可以回收两次——牌库一共走三轮。",facts:["两次回收","新牌局","三轮"]},relaxed:{name:"轻松",tagline:"不限轮数",description:"同样的配对规则，但废牌堆可以随便翻回去。",facts:["无限回收","新牌局","没有轮数限制"]}},fields:{recyclesLimit:{label:"废牌回收",group:"牌库",options:{2:"两次回收 — 经典","-1":"不限次数 — 轻松"},help:"经典模式可以回收两次，牌库走三轮。轻松模式永远不会用完。"}},presets:{classic:"经典",relaxed:"轻松"}},eights:{name:"疯狂八",subtitle:"万能牌甩牌游戏",tagline:"8点通吃",description:"一副普通的牌，一个越堆越高的弃牌堆。跟花色或跟点数，打出一张8把牌桌掰到你想要的花色，再让别人为手里剩下的牌买单。",facts:["2–6人","按分定胜负","单人或好友"],howToPlay:{summary:"一副普通的牌，一个弃牌堆，还有百搭的8。打空你的手牌，让全桌为他们还攥着的牌付分。",objective:"打空手牌结束这一轮，把其他人手里剩下的牌全部收入囊中。最先越过目标分的人赢下这一局。",sections:[{heading:"出牌",body:["轮到你时，打出一张与弃牌堆同花色或同点数的牌——♦7可以压任何方块，也可以压任何别的7。","8是万能牌。它什么都能压，而且由你指定下家必须跟的花色。","没牌可出？摸牌。在有人改变花色之前，弃牌堆一直要同一个花色。"]},{heading:"功能牌",body:["每一张都是牌桌设置，所以想玩得多素或多热闹，全看这桌人。"],bullets:[{label:"8——万能",text:"随时可出；由你指定接下去的花色（始终开启）"},{label:"2——罚两张",text:"下家摸两张牌，并跳过回合"},{label:"Q——跳过",text:"出牌顺序直接越过下家"},{label:"A——反转",text:"牌桌调转方向；两人对局时相当于让你再出一轮"}]},{heading:"摸牌",body:["按传统规矩，一直摸到能出为止。关掉它，每个回合就只能摸一张。","摸到的牌如果能出，你可以立刻打出，也可以留在手里——除非牌桌强制出牌。","摸牌堆用完后，明牌下面的所有牌洗回成新的摸牌堆。"]},{heading:"一轮计分",body:["有人打空手牌的那一刻，其他人清点手里剩下的牌，全部归甩牌的人。"],bullets:[{label:"每张8",text:"50分"},{label:"每张10、J、Q、K",text:"10分"},{label:"每张A",text:"1分"},{label:"其余的牌",text:"按牌面点数计"},{label:"僵持的一轮",text:"摸牌堆耗尽且无人能出——手牌最轻的人获胜，收下差额"}]},{heading:"赢下一局",body:["一轮接一轮地发牌，发牌权每次挪一个座位，直到有人越过目标分。最高分获胜。","榜首平分就再发一轮，绝不共享王座。"]}]},modes:{classic:{name:"原味",tagline:"只有8是万能",description:"你奶奶发牌时的那种玩法。跟花色或跟点数，出8喊花色，摸到能出为止。先到100分。",facts:["仅8万能","摸到能出为止","先到100分"]},house:{name:"家常",tagline:"2、Q、A全上场",description:"几乎所有人心里的那套规则：2罚摸牌，Q跳下家，A调转牌桌。先到100分。",facts:["2·Q·A生效","不可叠加","先到100分"]},chaos:{name:"疯狂",tagline:"叠起来罚",description:"2叠着2往上垒，直到有人一口吞下全部罚牌；摸到的牌必须打出；每回合只许摸一张。局更长，桌更吵。",facts:["可叠加罚牌","摸到必须出","先到150分"]}},fields:{handSize:{label:"发牌数",help:"每个座位在一轮开始时的牌数。",group:"发牌"},targetScore:{label:"目标分",help:"一轮接一轮地打，直到有人越过这个分数。",group:"发牌"},twosDrawTwo:{label:"2罚两张",help:"下家摸两张牌，并跳过回合。",group:"功能牌"},queensSkip:{label:"Q跳过",help:"出牌顺序直接越过下家。",group:"功能牌"},acesReverse:{label:"A反转",help:"调转牌桌方向。两人对局时相当于跳过对方。",group:"功能牌"},stackDrawTwo:{label:"2可叠加",help:"用你自己的2回敬一张2，把累积的罚牌传给下家。",group:"房间规则"},drawUntilPlayable:{label:"摸到能出为止",help:"传统规则。关掉后每回合只摸一张。",group:"房间规则"},forcePlay:{label:"强制出牌",help:"摸到的牌如果能出，就必须打出。",group:"房间规则"}},presets:{classic:"原味疯狂八",house:"家常疯狂八",chaos:"疯狂八"}},durak:{name:"笨蛋",subtitle:"谁都不想当的笨蛋",tagline:"永远别做最后拿着牌的人",description:"一副短牌、一个将牌花色，还有一张全是攻防的桌子。挡下扔向你的每一张牌，或者把整桌牌收入囊中——最后手里还有牌的那个人就要戴上笨蛋的帽子。",facts:["2–6人","36张牌","单人或好友"],howToPlay:{summary:"一副短牌，一个将牌花色，只有一个任务：别做最后手里还有牌的人。",objective:"出光你的牌，永远脱身。一旦牌堆抽空，手里还有牌的最后一人就是笨蛋。",sections:[{heading:"发牌",body:["每人从36张牌中拿到六张牌：六到A，四种花色，没有2到5。","牌堆翻开的下一张牌决定整局的将牌花色，并一直亮面朝上，直到牌堆抽空。","手持最小将牌的人先攻。没人有将牌？由一号座位开局。"]},{heading:"进攻与防守",body:["进攻方出一张牌。防守方必须挡下它：同花色更大的牌，或者，如果进攻的不是将牌，任意一张将牌。","只要牌面已经出现在桌上，其他座位就可以继续跟牌——不管挡没挡下，这张牌面在本回合结束前都算数。","挡下所有的牌，整桌牌都会清出局，永久离场——接下来轮到你进攻。","挡不下？把整桌牌收进手里。轮到你下家进攻。"],bullets:[{label:"进攻上限",text:"防守方看到的牌数永远不会超过本回合开始时手里的牌数"},{label:"补牌",text:"每回合结束后，所有人补牌到六张——先补进攻方，再补其他人，最后补防守方"}]},{heading:"Perevodnoy（转移）",body:["开启这条房规后，还没挡下任何牌的防守方可以选择转移：出一张同点数的牌，把整个进攻转给下家。"]},{heading:"终局",body:["一旦牌堆抽空，出光手牌就能永久离场——按发生的先后顺序。","最后手里还有牌的人就是笨蛋。其他人则按离场的早晚排名。"]}]},modes:{classic:{name:"经典",tagline:"Podkidnoy——传统跟牌玩法",description:"进攻、防守，跟出任何点数已经在桌上的牌。没有转移——要么挡下，要么收牌。",facts:["可以跟牌","没有转移","六张手牌"]},transfer:{name:"Perevodnoy",tagline:"把整个进攻转移出去",description:"经典模式的一切规则，再加一条退路：还没挡下任何牌的防守方可以把同点数的牌直接转给下家。",facts:["可以转移","可以跟牌","六张手牌"]},"heads-up":{name:"单挑",tagline:"一对一，快速分胜负",description:"专为两人设计。谁先出光手牌谁就当场获胜，不管牌堆还剩不剩牌——不必等牌堆抽空。",facts:["2人","秒胜","节奏快"]}},fields:{transfer:{label:"转移（Perevodnoy）",help:"持有同点数牌的防守方可以把整个进攻转给下家，而不是挡下它。",group:"本回合"},throwIns:{label:"跟牌（Podkidnoy）",help:"任何进攻方座位都可以跟出点数已经在桌上的牌。",group:"本回合"},maxAttacks:{label:"进攻上限",help:"防守方在一个回合里最多会看到的进攻牌数。",group:"本回合"},refillTo:{label:"手牌数量",help:"开局发的牌数，也是每回合结束后补牌的目标数量。",group:"发牌"},instantWin:{label:"秒胜",help:"谁先出光手牌就当场获胜，即使牌堆里还有牌。",group:"房规"}},presets:{classic:"经典笨蛋",transfer:"Perevodnoy","heads-up":"单挑"}},palace:{name:"宫廷",subtitle:"一层层甩牌的游戏",tagline:"一层一层清空牌桌",description:'先手牌，再明牌，最后暗牌——烧掉10，躲开2，第一个清空每一层。也叫"衰人"或"因果牌"。',facts:["2–6人","2、10和8都有特殊效果","单人或好友"],howToPlay:{summary:"先手牌，再明牌行，最后暗牌行——甩空你手里的一切，抢在别人之前清空牌桌。",objective:"先甩空手牌、明牌行和暗牌行的人赢下这一轮。赢的轮数会累积；最先达到目标轮数的人赢下整局。",sections:[{heading:"发牌",body:["每位玩家先拿三张暗牌，暗牌上再盖三张明牌，最后拿三张手牌。","开局前，可以把任意数量的手牌和自己的明牌互换——每人只有一次换牌机会，换完就准备开始。"]},{heading:"出牌到弃牌堆",body:["轮到你时，打出一张或多张点数相同、且不低于弃牌堆顶点数的牌，或者把整堆弃牌收回手里。","必须先出完手牌才能碰明牌行，出完明牌行才能碰暗牌行。"],bullets:[{label:"开局先手",text:"谁手里点数最小的普通牌最低，就由谁先出——从3开始往上比"},{label:"随时可以收牌",text:"即使手里有合法的牌可出，也能选择收下弃牌堆——有时候这样更保险"},{label:"暗牌出牌",text:"手牌和明牌行都空了以后，蒙眼翻开一张暗牌——如果能压住弃牌堆就留在场上，你可以继续出牌；压不住就把弃牌堆和这张牌一起收回手里"}]},{heading:"特殊牌",body:["四种点数会改写规则——默认全部开启，都可以在房间设置里关闭："],bullets:[{label:"2——清零",text:"任何时候都能打出；打出后弃牌堆的门槛几乎降到最低"},{label:"10——烧牌",text:"任何时候都能打出；整堆弃牌被移出游戏，你可以再出一次"},{label:"8——隐形",text:"永远可以打出，而且不会改变弃牌堆要求的点数——下家要接的是8底下那张牌"},{label:"四张同点",text:"弃牌堆顶凑齐四张同点数的牌就会烧掉，不管是怎么凑齐的——你可以再出一次"}]},{heading:"赢下一轮",body:["一旦有人同时清空手牌、明牌行和暗牌行，这一轮立刻结束。","其余的人按手里剩下的牌数排名——牌越少排名越好——如果打平，就比谁剩的暗牌更少。"]},{heading:"房间规则",body:["开局前可以在房间设置里调整这些选项："],bullets:[{label:"开局前换牌",text:"关闭后直接从发牌进入出牌，跳过换牌阶段"},{label:"2清零 / 10烧牌 / 8永远可出",text:"关闭任意一项，就让对应的点数变回普通牌"},{label:"四张同点烧牌",text:"关闭后同点数的牌可以一直堆在弃牌堆顶，不会被烧掉"},{label:"先赢多少轮",text:"赢下这么多轮才算赢下整局——1轮就是速战速决，最多可设到7轮打一整晚"}]}]},modes:{classic:{name:"经典",tagline:"完整的分层攻略",description:"先换牌，再依次甩空手牌、明牌和暗牌。率先赢下三轮的人拿下整局。",facts:["先赢3轮","换牌开启","特殊牌全开"]},quick:{name:"速战",tagline:"一轮定胜负",description:"只打一轮就分胜负——特殊牌规则不变，不用打完整局。",facts:["先赢1轮","约10分钟","适合热身"]},chaos:{name:"混乱",tagline:"没有换牌，毫不留情",description:"发牌后直接开打，没有换牌阶段可以谋划。特殊牌全部拉满：2清零、10烧牌、8依旧隐形，四张同点必烧。",facts:["先赢3轮","没有换牌阶段","随时可能烧牌"]}},fields:{allowSwap:{label:"开局前换牌",help:"发牌和第一次出牌之间的换牌阶段。"},twosReset:{label:"2清零弃牌堆",help:"任何时候都能打出，并把弃牌堆的门槛清零。"},tensBurn:{label:"10烧掉弃牌堆",help:"任何时候都能打出，并烧掉弃牌堆；同一位玩家再出一次。"},eightsBlind:{label:"8永远可以打出",help:"始终是合法的出牌，而且不会改变弃牌堆的门槛。"},fourKindBurn:{label:"四张同点烧牌",help:"弃牌堆顶四张同点数的牌会被烧掉；同一位玩家再出一次。"},winsTo:{label:"先赢多少轮",help:"有玩家赢下这么多轮后，整局结束。"}},presets:{classic:"经典宫廷",quick:"速战宫廷",chaos:"混乱宫廷"}},pinochle:{name:"皮诺克尔",subtitle:"双人搭档纸牌",tagline:"叫牌、报组合、吃墩",description:"与坐在对面的搭档一起，赢得叫牌、定将牌、摆出你的报组合。A、10和K是最要紧的牌——完成你的叫牌，否则就要认罚。",facts:["4人·2v2","叫牌·报组合·吃墩","单人或好友"],howToPlay:{summary:"美式搭档经典玩法——叫牌、定将牌、报组合，然后打牌定胜负。",objective:"与对面的搭档一起，赢得叫牌权并完成你的叫牌——报组合加上墩牌得分要达到或超过你叫的数字。一手打完后，先达到目标分的队伍赢得整局。",sections:[{heading:"牌桌",body:["四名玩家，两支队伍：你和对面的玩家是搭档。每手用完整的48张双副牌发牌——每人十二张，没有余牌。发牌权每手向左轮换。"]},{heading:"叫牌",body:["从发牌者左手边开始，每个座位可以跳过，也可以出比上一个更高的叫牌。一旦跳过，你这一手就出局了。最后一个还留着叫牌的座位赢得叫牌权，并定将牌。如果所有人都跳过、无人叫牌，这一手作废，由同一个发牌者重新发牌。"],bullets:[{label:"起叫",text:"必须达到桌面设定的最低值（经典模式为25）"},{label:"加价",text:"任意更高的整数，上限为60"}]},{heading:"报组合",body:["将牌确定后，每个座位摆出自己的组合来计分。牌仍留在手里——报组合是计分，不是弃牌——系统会替你算好，谁都无法虚报。"],bullets:[{label:"将牌顺子",text:"将牌的A-10-K-Q-J，15分"},{label:"同花配对",text:"同花色的K+Q——将牌配对4分（如果是顺子之外的第二对，再加2分），非将牌配对2分"},{label:"皮诺克尔配对",text:"黑桃Q + 方块J算4分；两种花色各凑齐一对是双皮诺克尔，值30分"},{label:"一圈",text:"四个花色各一张同点数的牌——A圈10分，K圈8分，Q圈6分，J圈4分"},{label:"将牌9",text:"手中每张将牌的9都值1分"}]},{heading:"打墩",body:["叫牌者首攻第一墩。能跟牌就必须跟；将牌能压过非将牌的首攻花色，否则由最大的牌赢墩。A、10、K在墩里被吃到时各值10分；最后一墩再加10分。赢墩的人首攻下一墩。"]},{heading:"一手计分",body:["把叫牌方的报组合分加上他们吃到的墩牌分。完成叫牌，就能把总分全部记上。没完成，就算栽了——正好扣掉叫牌的分数，报组合也算在内。对方总是能记上自己的墩牌分，除非桌面关闭了这个选项，否则也能记上自己的报组合分。"]},{heading:"整场比赛",body:["一手接一手打下去，直到有队伍达到目标分（100/150/500）。如果两队在同一手都超过目标分，叫牌方直接赢下整场比赛，除非他们栽了——这种情况下叫牌方在比分较高的一方面前输掉决胜，但若仍然打平，叫牌方赢。"]},{heading:"房间规则",body:["房间设置可以调整目标分、最低起叫分，以及对方是否给报组合计分。经典桌保留默认值。"]}]},modes:{classic:{name:"经典",tagline:"打到150分",description:"双人搭档皮诺克尔，打到150分，最低起叫25分。就是家家户户厨房牌桌上玩的那个样子。",facts:["打到150分","起叫25","约30分钟"]},quick:{name:"速战",tagline:"先到100分",description:"规则不变，赛程更短——100分，起叫更低，结束更快。",facts:["打到100分","起叫20","约15分钟"]},marathon:{name:"马拉松",tagline:"打到500分",description:"一场漫长的搭档鏖战，打到500分——每一次报组合、每一次栽跟头都要紧。",facts:["打到500分","起叫25","约90分钟"]}},fields:{target:{label:"目标分",group:"一局",help:"每手结束后，先达到或超过这个分数的搭档组合获胜。",options:{100:"100——速战",150:"150——经典",500:"500——马拉松"}},minBid:{label:"最低叫牌",group:"叫牌",help:"叫牌的起叫必须达到这个下限。之后每次叫牌都必须超过上一个，最高到60。"},opponentsScoreMeld:{label:"对方计报组合分",group:"计分",help:"关闭后，未叫牌的一方只计算吃墩得到的牌分——不计报组合分。"}},presets:{classic:"经典",quick:"速战",marathon:"马拉松"}},tripeaks:{name:"TriPeaks",subtitle:"清空三座牌峰",tagline:"打出与坑位相差一点的牌",description:"十八张牌组成三座牌峰，全部正面朝上。清空压着的牌来解锁它，把牌连打进坑位，清空整座牌峰。",facts:["1 人游戏","每日定局牌峰","离线"],howToPlay:{summary:"单人纸牌游戏：三座共十八张牌的牌峰，全部正面朝上，还有一叠翻到唯一坑位上的余牌。",objective:"清空牌峰上所有的牌。剩下的牌就是你的分数——越少越好。",sections:[{heading:"发牌",body:["三座牌峰共十八张牌，正面朝上分四层摆放。九张牌的底层永远是空的，可以直接打出。剩下的三十四张牌是余牌堆，第一张会翻开成为坑位。"]},{heading:"空闲的牌",body:["一张牌只要压在它上面的两张牌都被清走，就会变成空闲的牌。只有空闲的牌能移动——还被压着的牌要等它下面的牌先清空。"]},{heading:"打到坑位上",body:["当一张空闲的牌与坑位只差一点数时就能打出——8 可以接 7 或 9。花色和颜色都无所谓。能连打多少就连打多少。"]},{heading:"翻余牌堆",body:["如果牌峰上没有能打的牌，就翻开余牌堆的下一张盖到坑位上。原来坑位上的牌会被压在下面。"]},{heading:"A、K 和余牌堆",body:["经典三峰把 A 和 K 当成死路，余牌堆用完就不会回来。轻松模式让 A 和 K 可以互相衔接，余牌堆用完后还能把坑位洗回余牌堆一次。"]},{heading:"计分",body:["当牌峰清空，或者没有牌能打且余牌堆无法再补充时，牌局结束。留在牌峰上的牌就是你的分数，零分代表清空。"]}]},modes:{daily:{name:"每日",tagline:"所有人打同一局",description:"按日期定局的经典牌局，每个人都一样。可以重打、分享，或者明天再来挑战新的一局。",facts:["不可衔接","每天同一局","剩得越少越好"]},classic:{name:"经典",tagline:"A 和 K 是死路",description:"每局随机发牌。A 和 K 是死路，余牌堆用完就不会回来。",facts:["不可衔接","每局随机","不能回收"]},relaxed:{name:"轻松",tagline:"A 可以衔接 K",description:"同样是三座牌峰，但 A 和 K 可以互相打出，坑位用完的余牌堆还能回收一次。",facts:["A–K 可衔接","每局随机","可回收一次"]}},fields:{wrap:{label:"A 可以衔接 K",group:"坑位",help:"经典三峰在 A 和 K 处断开。轻松模式让 A 和 K 可以互相打出。"},recycle:{label:"回收坑位",group:"余牌堆",help:"余牌堆用完后，把坑位（除最上面那张）洗回余牌堆一次。"}},presets:{classic:"经典",relaxed:"轻松"}}}};e.s(["useLocalizedGame",0,function(e){let t=(0,s.useLocaleStore)(e=>e.locale);return(0,a.useMemo)(()=>{var a,s;return a=e,s=t,i((0,o.getGame)(a),l[s]?.[a])},[e,t])},"useLocalizedGames",0,function(){let e=(0,s.useLocaleStore)(e=>e.locale);return(0,a.useMemo)(()=>{let a;return(a=l[e])?o.GAMES.map(e=>i(e,a[e.id])):o.GAMES},[e])},"useLocalizedModes",0,function(e,o){let n=(0,s.useLocaleStore)(e=>e.locale);return(0,a.useMemo)(()=>{var a;return a=l[n]?.[e],a?.modes?o.map(e=>{let o=a.modes?.[e.id];return o?{...e,name:t(o.name,e.name),tagline:t(o.tagline,e.tagline),description:t(o.description,e.description),facts:r(o.facts,e.facts)}:e}):o},[e,n,o])},"useLocalizedSchema",0,function(e,o){let t=(0,s.useLocaleStore)(e=>e.locale);return(0,a.useMemo)(()=>{var a;return(a=l[t]?.[e])?n(o,a):o},[e,t,o])}],9335)}]);